def parse_csv(text: str) -> list[list[str]]:
    if text == "":
        return []

    records = []
    current_record = []
    current_field = []
    in_quote = False
    n = len(text)
    i = 0
    record_just_finished = False

    while i < n:
        char = text[i]

        if in_quote:
            if char == '"':
                if i + 1 < n and text[i+1] == '"':
                    current_field.append('"')
                    i += 1
                else:
                    in_quote = False
                    # Check what follows the closing quote
                    if i + 1 < n:
                        next_char = text[i+1]
                        if next_char == ',':
                            pass
                        elif next_char == '\r':
                            if i + 2 < n and text[i+2] == '\n':
                                pass
                            else:
                                raise ValueError("Invalid \\r outside quotes not followed by \\n")
                        elif next_char == '\n':
                            pass
                        else:
                            raise ValueError("Invalid character after closing quote")
            else:
                current_field.append(char)
        else:
            if char == '"':
                if current_field:
                    raise ValueError('" in unquoted field')
                in_quote = True
            elif char == ',':
                current_record.append(''.join(current_field))
                current_field = []
            elif char == '\r':
                if i + 1 < n and text[i+1] == '\n':
                    current_record.append(''.join(current_field))
                    current_field = []
                    records.append(current_record)
                    current_record = []
                    record_just_finished = True
                    i += 1
                else:
                    raise ValueError("Invalid \\r outside quotes not followed by \\n")
            elif char == '\n':
                current_record.append(''.join(current_field))
                current_field = []
                records.append(current_record)
                current_record = []
                record_just_finished = True
            else:
                current_field.append(char)
        i += 1

    if in_quote:
        raise ValueError("Unterminated quoted field")

    if not record_just_finished and (current_record or current_field):
        current_record.append(''.join(current_field))
        records.append(current_record)

