class Node: pass
class Num(Node):
    def __init__(self, val: int): self.val = val
class BinOp(Node):
    def __init__(self, op: str, left: Node, right: Node):
        self.op = op
        self.left = left
        self.right = right
class Unary(Node):
    def __init__(self, op: str, operand: Node):
        self.op = op
        self.operand = operand

