    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            if j - i > 1 and expr[i] == '0':
                raise ValueError("leading zero")
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
        elif c == '/':
            if i + 1 < n and expr[i+1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise ValueError("single '/' is invalid")
        elif c in '+-':
            tokens.append(('OP', c))
            i += 1
        elif c == '(':
            tokens.append(('PAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('PAREN', ')'))
            i += 1
        else:
            raise ValueError("invalid character")
    tokens.append(('EOF',))

    pos = [0]
    def peek():
        return tokens[pos[0]]

