            op = peek()[1]
            pos[0] += 1
            right = parse_power()
            left = BinOp(op, left, right)
        return left

    def parse_power():
        base = parse_unary()
        if peek()[0] == 'OP' and peek()[1] == '**':
            pos[0] += 1
            exp = parse_power()
            return BinOp('**', base, exp)
        return base

    def parse_unary():
        if peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = peek()[1]
            pos[0] += 1
            operand = parse_unary()
            return Unary(op, operand)
        return parse_atom()

    def parse_atom():
        tok = peek()
        if tok[0] == 'NUM':
            pos[0] += 1
            return Num(tok[1])
        elif tok[0] == 'PAREN' and tok[1] == '(':
            pos[0] += 1
            node = parse_expr()
            if peek()[0] != 'PAREN' or peek()[1] != ')':
                raise ValueError("unbalanced parentheses")
            pos[0] += 1
            return node
        else:
            raise ValueError("missing operand or syntax error")

    root = parse_expr()
    if peek()[0] != 'EOF':
        raise ValueError("unexpected token after expression")

    # Evaluator
    def evaluate(node: Node) -> int:
        if isinstance(node, Num):
            return node.val
        elif isinstance(node, Unary):
            operand = evaluate(node.operand)
            return operand if node.op == '+' else -operand
        elif isinstance(node, BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            op = node.op
            if op == '+':
                return left + right
            elif op == '-':
                return left - right
            elif op == '*':
                return left * right
            elif op == '//':
                if right == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return left // right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return left - (left // right) * right
            elif op == '**':
                if right < 0:
                    raise ValueError("negative exponent")
                return left ** right
        return 0

    return evaluate(root)

