            left = self.parse_term()
            while self.peek() and self.peek()[0] in ('PLUS', 'MINUS'):
                op = self.consume()[0]
                right = self.parse_term()
                if op == 'PLUS':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_term(self):
            left = self.parse_factor()
            while self.peek() and self.peek()[0] in ('STAR', 'SLASH_SLASH', 'PERCENT'):
                op = self.consume()[0]
                right = self.parse_factor()
                if op == 'STAR':
                    left = left * right
                elif op == 'SLASH_SLASH':
                    if right == 0:
                        raise ZeroDivisionError("integer division or modulo by zero")
                    left = left // right
                else:
                    if right == 0:
                        raise ZeroDivisionError("integer division or modulo by zero")
                    left = left % right
            return left

        def parse_factor(self):
            sign = 1
            while self.peek() and self.peek()[0] in ('PLUS', 'MINUS'):
                op = self.consume()[0]
                if op == 'MINUS':
                    sign = -sign
            return sign * self.parse_power()

        def parse_power(self):
            base = self.parse_primary()
            if self.peek() and self.peek()[0] == 'STAR_STAR':
                self.consume()
                exp = self.parse_factor()
                if exp < 0:
                    raise ValueError("negative exponent")
                return base ** exp
            return base

        def parse_primary(self):
            tok = self.peek()
            if tok is None:
                raise ValueError("Missing operand")
            if tok[0] == 'NUM':
                self.consume()
                return tok[1]
            if tok[0] == 'LPAREN':
                self.consume()
                val = self.parse_expr()
                if self.peek() is None or self.peek()[0] != 'RPAREN':
                    raise ValueError("Unbalanced parentheses")
                self.consume()
                return val
            raise ValueError("Syntax error")

    return Parser(tokens).parse()

def int_eval(expr: str) -> int:
    if not expr:
        raise ValueError("empty input")

    # Tokenization
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
