            elif c == '-': tokens.append(('MINUS', None))
            elif c == '*': tokens.append(('STAR', None))
            elif c == '%': tokens.append(('PERCENT', None))
            elif c == '(': tokens.append(('LPAREN', None))
            elif c == ')': tokens.append(('RPAREN', None))
            i += 1
        else:
            raise ValueError("invalid character")

