    # Parser state
    pos = 0
    def peek():
        return tokens[pos]

    def next():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        left = parse_term()
        while peek()[0] in ('PLUS', 'MINUS'):
            op = next()[0]
            right = parse_term()
            if op == 'PLUS':
                left = left + right
            else:
                left = left - right
        if peek()[0] in ('NUM', 'LPAREN'):
            raise ValueError("missing operator")
        return left

    def parse_term():
        left = parse_factor()
        while peek()[0] in ('STAR', 'SLASH_SLASH', 'PERCENT'):
            op = next()[0]
            right = parse_factor()
            if op == 'STAR':
                left = left * right
            elif op == 'SLASH_SLASH':
                if right == 0:
                    raise ZeroDivisionError
                left = left // right
            else:  # PERCENT
                if right == 0:
                    raise ZeroDivisionError
                left = left % right
