            raise ValueError("missing operator")
        return left

    def parse_factor():
        left = parse_unary()
        if peek()[0] == 'STAR_STAR':
            next()
            right = parse_factor()
            if right < 0:
                raise ValueError("negative exponent")
            left = left ** right
