        return sign * val

    def parse_primary():
        tok = peek()
        if tok[0] == 'NUM':
            next()
            return tok[1]
        elif tok[0] == 'LPAREN':
            next()
            val = parse_expr()
            if peek()[0] != 'RPAREN':
                raise ValueError("unbalanced parentheses")
            next()
            return val
        else:
            raise ValueError("missing operand")

    result = parse_expr()
    if peek()[0] != 'EOF':
        raise ValueError("unexpected token")
    return result

def int_eval(expr: str) -> int:
    """
    Evaluates an integer expression string following Python's semantics
    for the specified subset.
    """

    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue

        if c.isdigit():
            # Parse integer literal
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            num_str = expr[start:i]
            # Check leading zeros
            if len(num_str) > 1 and num_str[0] == '0':
                raise ValueError("Leading zeros not allowed")
            tokens.append(('NUM', int(num_str)))
            continue

        if c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
            continue

        if c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
            continue

        if c == '+':
            tokens.append(('OP', '+'))
            i += 1
            continue

        if c == '-':
            tokens.append(('OP', '-'))
            i += 1
            continue

        if c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
            continue

        if c == '/':
            if i + 1 < n and expr[i+1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise ValueError("Single '/' is not allowed")
            continue

        if c == '%':
            tokens.append(('OP', '%'))
            i += 1
            continue

        raise ValueError(f"Invalid character: {c}")

    # Parser and Evaluator
    # We use a recursive descent parser with a token pointer
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume(expected_type=None, expected_val=None):
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if expected_type and t[0] != expected_type:
            raise ValueError(f"Expected {expected_type} but got {t}")
        if expected_val and t[1] != expected_val:
            raise ValueError(f"Expected {expected_val} but got {t[1]}")
        pos += 1
        return t

    def parse_expr():
        return parse_add_sub()

    def parse_add_sub():
        left = parse_mul()
        while True:
            t = peek()
            if t and t[0] == 'OP' and t[1] in ('+', '-'):
                op = consume()[1]
                right = parse_mul()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_mul():
        left = parse_unary()
        while True:
            t = peek()
            if t and t[0] == 'OP' and t[1] in ('*', '//', '%'):
                op = consume()[1]
                right = parse_unary()
                if op == '*':
                    left = left * right
                elif op == '//':
                    if right == 0:
                        raise ZeroDivisionError("integer division or modulo by zero")
                    # Python's // rounds toward negative infinity
                    # int(left / right) truncates toward zero.
                    # We can use math.floor or custom logic.
                    # q = left // right in Python does this, but we can't use // on ints directly?
                    # Wait, we are evaluating. We can use Python's // operator for calculation.
                    # The restriction is on parsing/evaluating the expression string.
                    # Using built-in // for calculation is allowed.
                    left = left // right
                else: # %
                    if right == 0:
                        raise ZeroDivisionError("integer division or modulo by zero")
                    left = left % right
            else:
                break
        return left

    def parse_unary():
        t = peek()
        if t and t[0] == 'OP' and t[1] in ('+', '-'):
            op = consume()[1]
            val = parse_unary()
            if op == '+':
                return val
            else:
                return -val
        else:
            return parse_power()

    def parse_power():
        base = parse_primary()
        t = peek()
        if t and t[0] == 'OP' and t[1] == '**':
            consume() # consume '**'
            # Right associative: parse the exponent.
            # The exponent can be a unary expression (e.g., -3)
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent not allowed")
            return base ** exp
        return base

    def parse_primary():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")

        if t[0] == 'NUM':
            consume()
            return t[1]

        if t[0] == 'LPAREN':
            consume()
            val = parse_expr()
            rparen = peek()
            if rparen is None or rparen[1] != ')':
                raise ValueError("Missing closing parenthesis")
            consume('RPAREN', ')')
            return val

        # If we are here, it's an error
        if t[0] == 'OP':
            # Check for binary operator where operand expected
            if t[1] in ('*', '//', '%', '+', '-', '**'):
                raise ValueError(f"Unexpected operator {t[1]}")
        raise ValueError("Syntax error")

    # Check for empty input
    if not tokens:
        raise ValueError("Empty expression")

    result = parse_expr()

    # Check if there are remaining tokens (e.g., unbalanced parens or trailing operators)
    if pos < len(tokens):
        # Check specifically for unbalanced parentheses or trailing tokens
        # If we have tokens left, it's a syntax error
        # e.g. "2 3" -> two numbers adjacent
        # e.g. "2 +" -> trailing operator
        # e.g. "(2" -> missing close
        raise ValueError("Syntax error: unexpected tokens remaining")

    return result

def int_eval(expr: str) -> int:
    if not expr or not expr.strip():
        raise ValueError("Empty input")

    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            num_str = expr[i:j]
            if len(num_str) > 1 and num_str[0] == '0':
                raise ValueError("Leading zeros not allowed")
            tokens.append(('NUM', int(num_str)))
            i = j
        elif c == '/':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            elif i + 1 < n and expr[i+1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise ValueError("Lone '/' is not allowed")
        elif c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
        elif c in '+-':
            tokens.append(('OP', c))
            i += 1
        elif c in '%()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError("Invalid character")

    if not tokens:
        raise ValueError("Empty input")

    # Parser
    pos = 0
    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume(expected_type=None, expected_val=None):
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of input")
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Syntax error: expected {expected_type}")
        if expected_val and tok[1] != expected_val:
            raise ValueError(f"Syntax error: expected '{expected_val}'")
        pos += 1
        return tok

    def parse_add():
        left = parse_mul()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_mul()
            left = ('BINOP', op, left, right)
        return left

    def parse_mul():
        left = parse_power()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '//', '%'):
            op = consume()[1]
            right = parse_power()
            left = ('BINOP', op, left, right)
        return left

    def parse_power():
        left = parse_primary()
        if peek() and peek()[0] == 'OP' and peek()[1] == '**':
            consume()
            right = parse_factor()
            left = ('BINOP', '**', left, right)
        return left

    def parse_factor():
        if peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            child = parse_factor()
            return ('UNARY', op, child)
        return parse_power()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Missing operand")
        if tok[0] == 'NUM':
            consume()
            return ('NUM', tok[1])
        if tok[0] == 'OP' and tok[1] == '(':
            consume()
            node = parse_add()
            if not peek() or peek()[1] != ')':
                raise ValueError("Unbalanced parentheses")
            consume()
            return node
        raise ValueError("Syntax error")

    ast = parse_add()
    if pos < len(tokens):
        raise ValueError("Trailing tokens / syntax error")

    # Evaluator
    def eval_node(node):
        if node[0] == 'NUM':
            return node[1]
        if node[0] == 'UNARY':
            _, op, child = node
            val = eval_node(child)
            return val if op == '+' else -val
        if node[0] == 'BINOP':
            _, op, left, right = node
            l = eval_node(left)
            r = eval_node(right)
            if op == '+':
                return l + r
            if op == '-':
                return l - r
            if op == '*':
                return l * r
            if op == '//':
                if r == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return l // r
            if op == '%':
                if r == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return l % r
            if op == '**':
                if r < 0:
                    raise ValueError("Negative exponent not allowed")
                return l ** r
        raise ValueError("Unknown AST node")

    return eval_node(ast)

def int_eval(expr: str) -> int:
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Tokenization
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            num_str = expr[i:j]
            if len(num_str) > 1 and num_str[0] == '0':
                raise ValueError("Leading zeros not allowed")
            tokens.append(('NUM', int(num_str)))
            i = j
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('POW', '**'))
                i += 2
            else:
                tokens.append(('MUL', '*'))
                i += 1
        elif c == '/':
            if i + 1 < n and expr[i+1] == '/':
                tokens.append(('FLOORDIV', '//'))
                i += 2
            else:
                raise ValueError("Single '/' is not allowed")
        else:
            raise ValueError(f"Invalid character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    # AST Nodes
    class Node: pass
    class Num(Node):
        __slots__ = ('val',)
        def __init__(self, val): self.val = val
    class Unary(Node):
        __slots__ = ('op', 'operand')
        def __init__(self, op, operand): self.op = op; self.operand = operand
    class BinOp(Node):
        __slots__ = ('op', 'left', 'right')
        def __init__(self, op, left, right): self.op = op; self.left = left; self.right = right

    # Recursive Descent Parser
    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        return parse_add()

    def parse_add():
        left = parse_mul()
        while True:
            tok = peek()
            if tok and tok[0] in ('PLUS', 'MINUS'):
                advance()
                right = parse_mul()
                left = BinOp(tok[0], left, right)
            else:
                break
        return left

    def parse_mul():
        left = parse_power()
        while True:
            tok = peek()
            if tok and tok[0] in ('MUL', 'FLOORDIV', 'MOD'):
                advance()
                right = parse_power()
                left = BinOp(tok[0], left, right)
            else:
                break
        return left

    def parse_power():
        left = parse_unary()
        tok = peek()
        if tok and tok[0] == 'POW':
            advance()
            right = parse_power()  # Right-associative
            return BinOp('POW', left, right)
        return left

    def parse_unary():
        tok = peek()
        if tok and tok[0] in ('PLUS', 'MINUS'):
            advance()
            operand = parse_unary()
            return Unary(tok[0], operand)
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            advance()
            return Num(tok[1])
        elif tok[0] == 'LPAREN':
            advance()
            val = parse_expr()
            if peek()[0] != 'RPAREN':
                raise ValueError("Missing ')'")
            advance()
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

    ast = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected tokens or adjacent numbers")

    # Evaluation
    def evaluate(node):
        if isinstance(node, Num):
            return node.val
        elif isinstance(node, Unary):
            val = evaluate(node.operand)
            return -val if node.op == 'MINUS' else val
        elif isinstance(node, BinOp):
            left_val = evaluate(node.left)
            right_val = evaluate(node.right)
            if node.op == 'PLUS':
                return left_val + right_val
            elif node.op == 'MINUS':
                return left_val - right_val
            elif node.op == 'MUL':
                return left_val * right_val
            elif node.op == 'FLOORDIV':
                if right_val == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return left_val // right_val
            elif node.op == 'MOD':
                if right_val == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return left_val % right_val
            elif node.op == 'POW':
                if right_val < 0:
                    raise ValueError("pow() 2nd argument cannot be negative")
                return left_val ** right_val

    return evaluate(ast)

def b64decode_strict(s: str) -> bytes:
    # Check length is multiple of 4
    if len(s) % 4 != 0:
        raise ValueError("Invalid base64 length")

    # Empty string decodes to empty bytes
    if len(s) == 0:
        return b""

    # Check for invalid characters
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
    for char in s:
        if char not in allowed:
            raise ValueError("Invalid base64 character")

    # Check padding rules
    if '=' in s:
        # Padding must be at the end
        if s[-1] != '=':
            raise ValueError("Padding must be at the end")

        # Determine padding count
        if s[-2] == '=':
            # Check for too many padding characters (A=== or ====)
            if s[-3] == '=':
                raise ValueError("Too many padding characters")
            pad_count = 2
        else:
            pad_count = 1

        # Check for padding in non-last group
        if s[:-pad_count].count('=') > 0:
            raise ValueError("Padding in non-last group")

    # Base64 alphabet mapping
    b64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    b64_map = {c: i for i, c in enumerate(b64_chars)}

    result = bytearray()

    # Process in groups of 4
    for i in range(0, len(s), 4):
        group = s[i:i+4]

        # Determine padding for this group
        if group[3] == '=':
            if group[2] == '=':
                pad = 2
            else:
                pad = 1
        else:
            pad = 0

        # Decode characters to 6-bit values
        vals = []
        for char in group[:4-pad]:
            vals.append(b64_map[char])

        # Check unused bits
        if pad == 2:
            # Last data char's low 4 bits must be 0
            if vals[-1] & 0x0F != 0:
                raise ValueError("Invalid padding bits")
            # 12 bits -> 1 byte
            result.append((vals[0] << 2) | (vals[1] >> 4))
        elif pad == 1:
            # Last data char's low 2 bits must be 0
            if vals[-1] & 0x03 != 0:
                raise ValueError("Invalid padding bits")
            # 18 bits -> 2 bytes
            result.append((vals[0] << 2) | (vals[1] >> 4))
            result.append((vals[1] << 4) | (vals[2] >> 2))
        else:
            # 24 bits -> 3 bytes
            result.append((vals[0] << 2) | (vals[1] >> 4))
            result.append((vals[1] << 4) | (vals[2] >> 2))
            result.append((vals[2] << 6) | vals[3])

    return bytes(result)

def b64decode_strict(s: str) -> bytes:
    if not s:
        return b""
    if len(s) % 4 != 0:
        raise ValueError("Invalid length")

    _DECODE = {c: i for i, c in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")}

    result = bytearray()
    n = len(s)

    for i in range(0, n, 4):
        chunk = s[i:i+4]
        is_last = (i == n - 4)

        pad_count = 0
        for c in reversed(chunk):
            if c == '=':
                pad_count += 1
            else:
                break

        if pad_count > 2:
            raise ValueError("Invalid padding count")
        if pad_count > 0 and not is_last:
            raise ValueError("Padding only allowed at end")

        data_len = 4 - pad_count
        for j in range(data_len):
            if chunk[j] not in _DECODE:
                raise ValueError("Invalid character")

        vals = [_DECODE[chunk[j]] for j in range(data_len)]

        if is_last:
            if pad_count == 2 and (vals[-1] & 0x0F):
                raise ValueError("Invalid padding bits")
            if pad_count == 1 and (vals[-1] & 0x03):
                raise ValueError("Invalid padding bits")

        if pad_count == 2:
            result.append((vals[0] << 2) | (vals[1] >> 4))
        elif pad_count == 1:
            result.append((vals[0] << 2) | (vals[1] >> 4))
            result.append(((vals[1] & 0x0F) << 4) | (vals[2] >> 2))
        else:
            result.append((vals[0] << 2) | (vals[1] >> 4))
            result.append(((vals[1] & 0x0F) << 4) | (vals[2] >> 2))
            result.append(((vals[2] & 0x03) << 6) | vals[3])

    return bytes(result)

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Invalid IPv6 address")

    # Reject invalid characters
    if any(c in addr for c in " \t\n\r[]%"):
        raise ValueError("Invalid IPv6 address")

    is_mapped = False
    ipv4_groups = []

    # Handle ::
    if '::' in addr:
        if addr.count('::') > 1:
            raise ValueError("Invalid IPv6 address")
        left_str, right_str = addr.split('::', 1)
        left = left_str.split(':') if left_str else []
        right = right_str.split(':') if right_str else []

        if "" in left or "" in right:
            raise ValueError("Invalid IPv6 address")

        # Check for IPv4 suffix in right
        if right and '.' in right[-1]:
            ipv4_str = right.pop()
            is_mapped = True
            # Parse IPv4
            parts = ipv4_str.split('.')
            if len(parts) != 4:
