                if len(p) > 1 and p[0] == '0':
                    raise ValueError("Invalid IPv6 address")
            ipv4_groups = [(int(parts[0]) << 8) | int(parts[1]), 
                           (int(parts[2]) << 8) | int(parts[3])]

        total_groups = len(left) + len(right) + (2 if is_mapped else 0)
        if total_groups > 8:
            raise ValueError("Invalid IPv6 address")

        missing = 8 - total_groups
        groups = left + ['0'] * missing + right
    else:
        groups = addr.split(':')
        if len(groups) != 8:
            raise ValueError("Invalid IPv6 address")
        if "" in groups:
            raise ValueError("Invalid IPv6 address")

        if '.' in groups[-1]:
