    # Append IPv4 groups if present
    if is_mapped:
        values.extend(ipv4_groups)

    # Format according to RFC 5952
    # Find longest run of zeros (length >= 2)
    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0

    for i, v in enumerate(values):
        if v == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len and cur_len >= 2:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len > best_len and cur_len >= 2:
        best_start = cur_start
        best_len = cur_len

    # Build output
    if is_mapped:
        # IPv4-mapped: ::ffff:a.b.c.d
