    if best_len > 0:
        left_part = ':'.join(f"{v:x}" for v in values[:best_start])
        right_part = ':'.join(f"{v:x}" for v in values[best_start + best_len:])
        if best_start == 0:
            left_part = ""
        if best_start + best_len == 8:
            right_part = ""
        return f"{left_part}::{right_part}"
    else:
        return ':'.join(f"{v:x}" for v in values)

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Invalid IPv6 address")

    # Reject whitespace, zone IDs, brackets, prefix lengths
    if any(c in addr for c in ' \t\n\r%[]/'):
        raise ValueError("Invalid IPv6 address")

    has_double_colon = '::' in addr
    if has_double_colon:
        if ':::' in addr:
            raise ValueError("Invalid IPv6 address")
        before, after = addr.split('::', 1)
        left_parts = before.split(':') if before else []
        right_parts = after.split(':') if after else []

        # Validate no empty segments from split
        for p in left_parts + right_parts:
            if not p:
                raise ValueError("Invalid IPv6 address")

        total_parts = len(left_parts) + len(right_parts)
        if total_parts > 7:
            raise ValueError("Invalid IPv6 address")

        missing = 8 - total_parts
        if missing < 1:
            raise ValueError("Invalid IPv6 address")

        parts = left_parts + ['0'] * missing + right_parts
    else:
        parts = addr.split(':')
        if len(parts) != 8:
            raise ValueError("Invalid IPv6 address")

    groups = []
    for i, part in enumerate(parts):
        if '.' in part:
            # IPv4 suffix must be the very last part
            if i != len(parts) - 1:
                raise ValueError("Invalid IPv6 address")

            ipv4_parts = part.split('.')
            if len(ipv4_parts) != 4:
                raise ValueError("Invalid IPv6 address")

            vals = []
            for v in ipv4_parts:
                if not v or len(v) > 3 or not all(c in '0123456789' for c in v):
                    raise ValueError("Invalid IPv6 address")
                if len(v) > 1 and v[0] == '0':
                    raise ValueError("Invalid IPv6 address")
                num = int(v)
                if num > 255:
                    raise ValueError("Invalid IPv6 address")
                vals.append(num)

            a, b, c, d = vals
            groups.append((a << 8) | b)
            groups.append((c << 8) | d)
        else:
            if not part or len(part) > 4:
                raise ValueError("Invalid IPv6 address")
            if not all(c in '0123456789abcdefABCDEF' for c in part):
                raise ValueError("Invalid IPv6 address")
            groups.append(int(part, 16))

    if len(groups) != 8:
        raise ValueError("Invalid IPv6 address")

    # Convert to lowercase hex without leading zeros
    hex_groups = [format(g, 'x') for g in groups]

    # Find longest run of consecutive "0" groups (length >= 2)
    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0
    for i, g in enumerate(hex_groups):
        if g == '0':
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len > best_len:
        best_start = cur_start
        best_len = cur_len

    # IPv4-mapped address exception
    is_mapped = all(g == 0 for g in groups[:5]) and groups[5] == 0xFFFF
    if is_mapped:
        a = (groups[6] >> 8) & 0xFF
        b = groups[6] & 0xFF
        c = (groups[7] >> 8) & 0xFF
        d = groups[7] & 0xFF
        return f"::ffff:{a}.{b}.{c}.{d}"

    # Apply compression if run length >= 2
    if best_len >= 2:
        left = hex_groups[:best_start]
        right = hex_groups[best_start + best_len:]
        return ':'.join(left) + '::' + ':'.join(right)
    else:
        return ':'.join(hex_groups)

