        if total_explicit > 7:
            raise ValueError("Invalid format: too many groups with ::")

        missing = 8 - total_explicit
        if missing < 1:
            raise ValueError("Invalid :: usage")

        groups = [int(g, 16) for g in left_groups] + [0]*missing + [int(g, 16) for g in right_groups] + ipv4_hex_groups
    else:
        parts = prefix_part.split(':')
        if len(parts) != 8:
            raise ValueError("Invalid format: must have exactly 8 groups without ::")
        for g in parts:
            if not g or len(g) > 4:
                raise ValueError("Invalid hex group")
            try:
                int(g, 16)
            except ValueError:
