        groups = [int(g, 16) for g in parts] + ipv4_hex_groups
        if len(groups) != 8:
            raise ValueError("Invalid number of groups")

    if len(groups) != 8:
        raise ValueError("Invalid number of groups")

    # Find longest run of zeros
    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0

    for i, val in enumerate(groups):
        if val == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len > best_len:
        best_start = cur_start
        best_len = cur_len

    # Check for IPv4-mapped exception
    if groups[:5] == [0]*5 and groups[5] == 0xffff:
        val = (groups[6] << 16) | groups[7]
        a = (val >> 24) & 0xFF
        b = (val >> 16) & 0xFF
        c = (val >> 8) & 0xFF
        d = val & 0xFF
        return f"::ffff:{a}.{b}.{c}.{d}"

    if best_len >= 2:
        left_hex = [format(g, 'x') for g in groups[:best_start]]
        right_hex = [format(g, 'x') for g in groups[best_start+best_len:]]
        return ":".join(left_hex) + "::" + ":".join(right_hex)
    else:
        hex_strs = [format(g, 'x') for g in groups]
        return ":".join(hex_strs)

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Invalid IPv6 address")

    # Check for invalid characters early
    allowed_chars = set('0123456789abcdefABCDEF:.')
    if not all(c in allowed_chars for c in addr):
        raise ValueError("Invalid IPv6 address")

    # Handle IPv4 suffix
    ipv4_suffix = []
    if '.' in addr:
        last_colon = addr.rfind(':')
        if last_colon == -1:
            raise ValueError("Invalid IPv6 address")
        ipv4_part = addr[last_colon+1:]
        addr = addr[:last_colon+1]
        parts = ipv4_part.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 suffix")
        ipv4_vals = []
        for p in parts:
            if not p:
                raise ValueError("Invalid IPv4 suffix")
            if len(p) > 1 and p[0] == '0':
                raise ValueError("Invalid IPv4 suffix: leading zeros")
            try:
                val = int(p)
            except ValueError:
                raise ValueError("Invalid IPv4 suffix")
            if val < 0 or val > 255:
                raise ValueError("Invalid IPv4 suffix: out of range")
            ipv4_vals.append(val)
        g6 = (ipv4_vals[0] << 8) | ipv4_vals[1]
        g7 = (ipv4_vals[2] << 8) | ipv4_vals[3]
        ipv4_suffix = [f"{g6:04x}", f"{g7:04x}"]
    else:
        ipv4_suffix = []

    # Remove trailing colon if IPv4 suffix was present
    if ipv4_suffix:
        if not addr.endswith(':'):
            raise ValueError("Invalid IPv6 address")
        addr = addr[:-1]

    # Handle ::
    if '::' in addr:
        if addr.count('::') > 1:
            raise ValueError("Invalid IPv6 address: multiple ::")

        idx = addr.find('::')
        left = addr[:idx]
        right = addr[idx+2:]

        left_groups = left.split(':') if left else []
        right_groups = right.split(':') if right else []

        for g in left_groups + right_groups:
            if not g:
                raise ValueError("Invalid IPv6 address: empty group")
            if len(g) > 4:
                raise ValueError("Invalid IPv6 address: group too long")
            try:
                int(g, 16)
            except ValueError:
                raise ValueError("Invalid IPv6 address: invalid hex group")

        total_groups = len(left_groups) + len(right_groups) + len(ipv4_suffix)
        if total_groups > 7:
            raise ValueError("Invalid IPv6 address: too many groups")

        zeros_needed = 8 - total_groups
        if zeros_needed < 1:
            raise ValueError("Invalid IPv6 address: :: must represent at least one group")

        groups = left_groups + ['0'] * zeros_needed + right_groups + ipv4_suffix
    else:
        groups = addr.split(':')
        if len(groups) != 8:
            raise ValueError("Invalid IPv6 address: expected 8 groups")
        for g in groups:
            if not g:
                raise ValueError("Invalid IPv6 address: empty group")
            if len(g) > 4:
                raise ValueError("Invalid IPv6 address: group too long")
            try:
                int(g, 16)
            except ValueError:
                raise ValueError("Invalid IPv6 address: invalid hex group")
        groups = groups + ipv4_suffix

    # Convert to canonical hex (lowercase, no leading zeros)
    canonical_groups = [f"{int(g, 16):x}" for g in groups]

    # Check for IPv4-mapped address
    is_ipv4_mapped = False
    ipv4_mapped_suffix = None
    if len(canonical_groups) == 8:
        if all(cg == '0' for cg in canonical_groups[:5]) and canonical_groups[5] == 'ffff':
            is_ipv4_mapped = True
            ipv4_mapped_suffix = f"{int(canonical_groups[6], 16)}.{int(canonical_groups[7], 16)}"

    if is_ipv4_mapped:
        return f"::ffff:{ipv4_mapped_suffix}"

    # Find longest run of consecutive '0' groups (length >= 2)
    best_start = -1
    best_len = 0
    current_start = -1
    current_len = 0

    for i, g in enumerate(canonical_groups):
        if g == '0':
            if current_start == -1:
                current_start = i
                current_len = 1
            else:
                current_len += 1
        else:
            if current_len > best_len and current_len >= 2:
                best_start = current_start
                best_len = current_len
            current_start = -1
            current_len = 0

    if current_len > best_len and current_len >= 2:
        best_start = current_start
        best_len = current_len

    if best_len == 0:
        return ':'.join(canonical_groups)
    else:
        left = canonical_groups[:best_start]
        right = canonical_groups[best_start + best_len:]
        return ':'.join(left) + '::' + ':'.join(right)

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
