    if any(c in addr for c in ' \t\n\r%[]/'):
        raise ValueError("Invalid characters")

    has_ipv4 = '.' in addr
    ipv4_groups = []
    if has_ipv4:
        parts = addr.split('.')
        if len(parts) != 4:
