                raise ValueError("Leading zeros in IPv4 suffix")
            val = int(p)
            if val > 255:
                raise ValueError("IPv4 suffix part out of range")
        ipv4_groups = [int(parts[0]) * 256 + int(parts[1]),
                       int(parts[2]) * 256 + int(parts[3])]
        prefix = addr[:addr.rfind('.')]
    else:
        prefix = addr

    if '::' in prefix:
        if prefix.count('::') > 1:
            raise ValueError("Multiple ::")
        left_str, right_str = prefix.split('::')
        left = left_str.split(':') if left_str else []
        right = right_str.split(':') if right_str else []
        if '' in left or '' in right:
            raise ValueError("Invalid empty group")
        written = len(left) + len(right)
        expected = 6 if has_ipv4 else 8
        if written > expected:
            raise ValueError("Too many groups")
        missing = expected - written
        if missing < 1:
            raise ValueError(":: must replace at least one group")
    else:
        if ':' not in prefix:
            if prefix != '':
                raise ValueError("Invalid format")
            # prefix is empty string, but has_ipv4 is False -> invalid
