            raise ValueError("Invalid number of groups")
        if '' in groups_str:
            raise ValueError("Invalid empty group")
        left = groups_str
        right = []
        missing = 0

    all_groups_str = left + (['0'] * missing) + right
    groups = []
    for g in all_groups_str:
        if len(g) == 0 or len(g) > 4:
            raise ValueError("Invalid group length")
        try:
