        groups.extend(ipv4_groups)

    # IPv4-mapped exception
    if all(g == 0 for g in groups[:5]) and groups[5] == 0xFFFF:
        if has_ipv4:
            ipv4_str = ".".join(str(p) for p in ipv4_groups)
        else:
            ipv4_str = f"{groups[6] // 256}.{groups[6] % 256}.{groups[7] // 256}.{groups[7] % 256}"
        return f"::ffff:{ipv4_str}"

    # Find longest run of consecutive zero groups (length >= 2)
    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0
    for i, g in enumerate(groups):
        if g == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len and cur_len >= 2:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len > best_len and cur_len >= 2:
        best_start = cur_start
        best_len = cur_len

    formatted = []
    i = 0
    while i < 8:
        if i == best_start and best_len > 0:
            formatted.append('::')
            i += best_len
        else:
            formatted.append(format(groups[i], 'x'))
            i += 1

    return ':'.join(formatted)

