    # Expand :: with missing zero groups
    if '::' in addr:
        written_count = len(groups)
        missing = 8 - written_count
        if missing < 1:
            raise ValueError
        insert_pos = len(left_parts)
        groups = groups[:insert_pos] + [0] * missing + groups[insert_pos:]

    # Validate all groups are valid 16-bit values
    for g in groups:
        if g < 0 or g > 65535:
            raise ValueError

    # Check for IPv4-mapped address exception
    is_ipv4_mapped = (len(groups) == 8 and
                      all(g == 0 for g in groups[:5]) and
                      groups[5] == 0xffff)

    if is_ipv4_mapped:
        last32 = (groups[6] << 16) | groups[7]
        a = (last32 >> 24) & 0xff
        b = (last32 >> 16) & 0xff
        c = (last32 >> 8) & 0xff
        d = last32 & 0xff
        return f"::ffff:{a}.{b}.{c}.{d}"

    # Format standard IPv6
    hex_groups = [format(g, 'x') for g in groups]

    # Find longest run of consecutive '0' groups (tie-break: first run)
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0

    for i, h in enumerate(hex_groups):
        if h == '0':
            if curr_len == 0:
                curr_start = i
            curr_len += 1
        else:
            if curr_len > best_len:
                best_start = curr_start
                best_len = curr_len
            curr_len = 0
    if curr_len > best_len:
        best_start = curr_start
        best_len = curr_len

    # RFC 5952: only compress runs of length >= 2
    if best_len < 2:
        best_len = 0
        best_start = -1

    if best_len > 0:
        left = hex_groups[:best_start]
        right = hex_groups[best_start + best_len:]
        return ':'.join(left) + '::' + ':'.join(right)
    else:
        return ':'.join(hex_groups)

def ipv6_canonical(addr: str) -> str:
    def parse_ipv4_suffix(s: str):
        parts = s.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 suffix")
        vals = []
        for p in parts:
            if not p or not all(c in '0123456789' for c in p):
                raise ValueError("Invalid IPv4 part")
            if len(p) > 1 and p[0] == '0':
                raise ValueError("Leading zero in IPv4 part")
            v = int(p)
            if v > 255:
                raise ValueError("IPv4 part out of range")
            vals.append(v)
        return (vals[0] << 8) | vals[1], (vals[2] << 8) | vals[3]

    if not addr or any(c.isspace() for c in addr):
        raise ValueError("Empty or whitespace address")

    ipv4_suffix = None
    if '.' in addr:
        last_colon = addr.rfind(':', 0, addr.rfind('.'))
        if last_colon == -1:
            raise ValueError("Invalid IPv4 suffix placement")
        ipv4_suffix = parse_ipv4_suffix(addr[last_colon+1:])
        addr = addr[:last_colon]

    groups = []
    if '::' in addr:
        if addr.count('::') > 1:
            raise ValueError("Multiple ::")
        left_str, right_str = addr.split('::', 1)
        left_parts = left_str.split(':') if left_str else []
        right_parts = right_str.split(':') if right_str else []

        for p in left_parts + right_parts:
            if not p or len(p) > 4:
                raise ValueError("Invalid group format")
            try:
                int(p, 16)
            except ValueError:
                raise ValueError("Invalid hex group")

        left_count = len(left_parts)
        right_count = len(right_parts)
        total_written = left_count + right_count

        if ipv4_suffix is not None:
            if total_written + 2 > 8:
                raise ValueError("Too many groups")
            missing = 8 - (total_written + 2)
            if missing < 1:
                raise ValueError("Invalid :: expansion")
            groups = [int(p, 16) for p in left_parts] + [0] * missing + list(ipv4_suffix)
        else:
            if total_written > 7:
                raise ValueError("Too many groups")
            missing = 8 - total_written
            if missing < 1:
                raise ValueError("Invalid :: expansion")
            groups = [int(p, 16) for p in left_parts] + [0] * missing + [int(p, 16) for p in right_parts]
    else:
        parts = addr.split(':')
        expected = 6 if ipv4_suffix is not None else 8
        if len(parts) != expected:
            raise ValueError("Wrong number of groups")
        for p in parts:
            if not p or len(p) > 4:
                raise ValueError("Invalid group format")
            try:
                groups.append(int(p, 16))
            except ValueError:
                raise ValueError("Invalid hex group")

    # Format canonical output
    if ipv4_suffix is not None:
        is_mapped = all(g == 0 for g in groups[:5]) and groups[5] == 0xFFFF
        if is_mapped:
            a = (groups[6] >> 8) & 0xFF
            b = groups[6] & 0xFF
            c = (groups[7] >> 8) & 0xFF
            d = groups[7] & 0xFF
            return f"::ffff:{a}.{b}.{c}.{d}"

    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0

    for i, g in enumerate(groups):
        if g == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len and cur_len >= 2:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
            cur_start = -1
    if cur_len > best_len and cur_len >= 2:
        best_start = cur_start
        best_len = cur_len

    if best_len > 0:
        left = [f"{groups[i]:x}" for i in range(best_start)]
        right = [f"{groups[i]:x}" for i in range(best_start + best_len, 8)]
        return ":".join(left) + "::" + ":".join(right)
    else:
        return ":".join(f"{g:x}" for g in groups)

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Invalid input")

    # 1. Handle IPv4 suffix
    ipv4_suffix = None
    if '.' in addr:
        colon_idx = addr.rfind(':')
        if colon_idx == -1:
            raise ValueError("Invalid IPv6: IPv4 suffix without preceding colon")
        ipv4_str = addr[colon_idx + 1:]
        prefix = addr[:colon_idx]

        parts = ipv4_str.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 suffix")
        for p in parts:
            if not p.isdigit() or len(p) == 0:
                raise ValueError("Invalid IPv4 suffix part")
            if len(p) > 1 and p[0] == '0':
                raise ValueError("Leading zeros in IPv4 suffix")
            val = int(p)
            if val < 0 or val > 255:
                raise ValueError("IPv4 suffix out of range")

        ipv4_suffix = (int(parts[0]) * 256 + int(parts[1]),
                       int(parts[2]) * 256 + int(parts[3]))
        addr = prefix

    # 2. Handle :: expansion
    if '::' in addr:
        if addr.count('::') > 1:
            raise ValueError("Multiple :: found")
        left, right = addr.split('::')
        left_parts = left.split(':') if left else []
        right_parts = right.split(':') if right else []

        if '' in left_parts or '' in right_parts:
            raise ValueError("Empty group near ::")
        if len(left_parts) + len(right_parts) > 7:
            raise ValueError("Too many groups with ::")

        missing = 8 - len(left_parts) - len(right_parts)
        if missing < 1:
            raise ValueError(":: must expand at least one group")

        groups = left_parts + ['0'] * missing + right_parts
    else:
        groups = addr.split(':')
        if len(groups) != 8:
            raise ValueError("Exactly 8 groups required without ::")
        if '' in groups:
            raise ValueError("Empty group found")

    # 3. Parse hex groups
    parsed = []
    for g in groups:
        if len(g) == 0 or len(g) > 4:
            raise ValueError("Invalid group length")
        if not all(c in '0123456789abcdefABCDEF' for c in g):
            raise ValueError("Invalid hex character")
        val = int(g, 16)
        if val > 65535:
            raise ValueError("Group out of range")
        parsed.append(val)

    # 4. Format output
    if ipv4_suffix is not None:
        a, b = ipv4_suffix
        ipv4_str = f"{a >> 8}.{a & 0xff}.{b >> 8}.{b & 0xff}"

        # Check for IPv4-mapped exception
        if all(v == 0 for v in parsed[:5]) and parsed[5] == 0xffff:
            return f"::ffff:{ipv4_str}"

        # Format first 6 groups, then append IPv4
        best_start = -1
        best_len = 0
        curr_start = -1
        curr_len = 0
        for i in range(6):
            if parsed[i] == 0:
                if curr_start == -1:
                    curr_start = i
                    curr_len = 1
                else:
                    curr_len += 1
            else:
                if curr_len > best_len:
                    best_start = curr_start
                    best_len = curr_len
                curr_start = -1
                curr_len = 0
        if curr_len > best_len:
            best_start = curr_start
            best_len = curr_len

        if best_len < 2:
            best_start = -1
            best_len = 0

        left = ':'.join(f"{parsed[j]:x}" for j in range(best_start))
        right = ':'.join(f"{parsed[j]:x}" for j in range(best_start + best_len, 6))

        if best_len >= 2:
            return f"{left}::{right}{ipv4_str}" if right else f"{left}::{ipv4_str}"
        else:
            return f"{left}:{right}:{ipv4_str}" if left or right else f"::{ipv4_str}"

    # Standard IPv6 formatting
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0
    for i in range(8):
        if parsed[i] == 0:
            if curr_start == -1:
                curr_start = i
                curr_len = 1
            else:
                curr_len += 1
        else:
            if curr_len > best_len:
                best_start = curr_start
                best_len = curr_len
            curr_start = -1
            curr_len = 0
    if curr_len > best_len:
        best_start = curr_start
        best_len = curr_len

    if best_len < 2:
        best_start = -1
        best_len = 0

    left = ':'.join(f"{parsed[j]:x}" for j in range(best_start))
    right = ':'.join(f"{parsed[j]:x}" for j in range(best_start + best_len, 8))

    if best_len >= 2:
        return f"{left}::{right}"
    else:
        return ':'.join(f"{parsed[j]:x}" for j in range(8))

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Invalid input")

    # Reject invalid characters early
    allowed = set('0123456789abcdefABCDEF:.')
    if not all(c in allowed for c in addr):
        raise ValueError("Invalid characters")

    if addr.count('::') > 1:
        raise ValueError("Multiple '::' found")

    if addr == '::':
        groups = [0] * 8
    elif '::' in addr:
        left_str, right_str = addr.split('::')
        left_parts = left_str.split(':') if left_str else []
        right_parts = right_str.split(':') if right_str else []

        if '' in left_parts or '' in right_parts:
            raise ValueError("Invalid empty group")

        left_hex_count = sum(1 for p in left_parts if '.' not in p)
        right_hex_count = sum(1 for p in right_parts if '.' not in p)
        right_has_ipv4 = any('.' in p for p in right_parts)

        if any('.' in p for p in left_parts):
            raise ValueError("IPv4 part must be final")
        if right_parts.count('', 0) > 0: # handled by empty check above
            pass

        total_written = left_hex_count + right_hex_count + (2 if right_has_ipv4 else 0)
        if total_written > 7:
            raise ValueError("Too many groups")

        num_zeros = 8 - total_written

        groups = []
        for p in left_parts:
            if '.' in p:
                groups.extend(parse_ipv4_part(p))
            else:
                groups.append(parse_hex_group(p))
        groups.extend([0] * num_zeros)
        for p in right_parts:
            if '.' in p:
                groups.extend(parse_ipv4_part(p))
            else:
                groups.append(parse_hex_group(p))
    else:
        parts = addr.split(':')
        if '' in parts:
            raise ValueError("Invalid empty group")
        groups = []
        ipv4_count = 0
        for i, p in enumerate(parts):
            if '.' in p:
                ipv4_count += 1
                if ipv4_count > 1:
                    raise ValueError("Multiple IPv4 parts")
                if p != parts[-1]:
                    raise ValueError("IPv4 part must be final")
                groups.extend(parse_ipv4_part(p))
            else:
                groups.append(parse_hex_group(p))
        if len(groups) != 8:
            raise ValueError("Expected 8 groups")

    # Format output
    if all(g == 0 for g in groups[:5]) and groups[5] == 0xFFFF:
        a = groups[6] >> 8
        b = groups[6] & 0xFF
        c = groups[7] >> 8
        d = groups[7] & 0xFF
        return f"::ffff:{a}.{b}.{c}.{d}"

    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0
    for i, g in enumerate(groups):
        if g == 0:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
        else:
            if cur_len > best_len:
                best_start = cur_start
                best_len = cur_len
            cur_len = 0
    if cur_len > best_len:
        best_start = cur_start
        best_len = cur_len

    if best_len >= 2:
        left = groups[:best_start]
        right = groups[best_start + best_len:]
        left_str = ':'.join(format_hex(g) for g in left)
        right_str = ':'.join(format_hex(g) for g in right)
        if not left_str and not right_str:
            return "::"
        elif not left_str:
            return "::" + right_str
        elif not right_str:
            return left_str + "::"
        else:
            return f"{left_str}::{right_str}"
    else:
        return ':'.join(format_hex(g) for g in groups)

def parse_hex_group(s: str) -> int:
    if not s or len(s) > 4:
        raise ValueError("Invalid hex group length")
    try:
        return int(s, 16)
    except ValueError:
        raise ValueError("Invalid hex digits")

def parse_ipv4_part(s: str) -> list:
    parts = s.split('.')
    if len(parts) != 4:
        raise ValueError("Invalid IPv4 format")
    nums = []
    for p in parts:
        if not p.isdigit():
            raise ValueError("Invalid IPv4 part")
        if len(p) > 1 and p[0] == '0':
            raise ValueError("Leading zero in IPv4")
        val = int(p)
        if val > 255:
            raise ValueError("IPv4 part out of range")
        nums.append(val)
    return [(nums[0] << 8) | nums[1], (nums[2] << 8) | nums[3]]

def format_hex(n: int) -> str:
    return format(n, 'x')

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str) or not addr:
        raise ValueError("Invalid input")

    # Check for multiple ::
    if addr.count('::') > 1:
        raise ValueError("Multiple :: found")

    if '::' in addr:
        left, right = addr.split('::', 1)
        left_parts = left.split(':') if left else []
        right_parts = right.split(':') if right else []
        if '' in left_parts or '' in right_parts:
            raise ValueError("Empty group found")
        num_missing = 8 - (len(left_parts) + len(right_parts))
        if num_missing < 1:
            raise ValueError("Too many groups with ::")
        parts = left_parts + ['0'] * num_missing + right_parts
    else:
        parts = addr.split(':')
        if len(parts) != 8:
            raise ValueError("Invalid number of groups")
        if '' in parts:
            raise ValueError("Empty group found")

    hex_groups = []
    for p in parts:
        if '.' in p:
            if p != parts[-1]:
                raise ValueError("IPv4 notation must be at the end")
            ipv4_parts = p.split('.')
            if len(ipv4_parts) != 4:
                raise ValueError("Invalid IPv4 notation")
            ipv4_ints = []
            for part in ipv4_parts:
                if not part.isdigit():
                    raise ValueError("Invalid IPv4 part")
                if len(part) > 1 and part[0] == '0':
                    raise ValueError("Leading zeros in IPv4")
                val = int(part)
                if val < 0 or val > 255:
                    raise ValueError("IPv4 part out of range")
                ipv4_ints.append(val)
            high = (ipv4_ints[0] << 8) | ipv4_ints[1]
            low = (ipv4_ints[2] << 8) | ipv4_ints[3]
            hex_groups.append(high)
            hex_groups.append(low)
            break
        else:
            if len(p) == 0 or len(p) > 4:
                raise ValueError("Invalid hex group length")
            if not all(c in '0123456789abcdefABCDEF' for c in p):
                raise ValueError("Invalid hex character")
            hex_groups.append(int(p, 16))

    if len(hex_groups) != 8:
        raise ValueError("Invalid number of groups")

    # IPv4-mapped address exception
    if all(g == 0 for g in hex_groups[:5]) and hex_groups[5] == 0xffff:
        a = (hex_groups[6] >> 8) & 0xff
        b = hex_groups[6] & 0xff
        c = (hex_groups[7] >> 8) & 0xff
        d = hex_groups[7] & 0xff
        return f"::ffff:{a}.{b}.{c}.{d}"

    # Find longest run of consecutive zero groups (length >= 2)
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0

    for i, g in enumerate(hex_groups):
        if g == 0:
            if curr_len == 0:
                curr_start = i
            curr_len += 1
        else:
            if curr_len > best_len:
                best_start = curr_start
                best_len = curr_len
            curr_len = 0
    if curr_len > best_len:
        best_start = curr_start
        best_len = curr_len

    if best_len < 2:
        return ":".join(f"{g:x}" for g in hex_groups)
    else:
        left = ":".join(f"{g:x}" for g in hex_groups[:best_start])
        right = ":".join(f"{g:x}" for g in hex_groups[best_start + best_len:])
        if best_start == 0:
            left = ""
        if best_start + best_len == 8:
            right = ""
        if left and right:
            return f"{left}::{right}"
        elif left:
            return f"{left}::"
        elif right:
            return f"::{right}"
        else:
            return "::"

def ipv6_canonical(addr: str) -> str:
    if not isinstance(addr, str):
        raise ValueError("Input must be a string")

    # Strict character check
    if any(c in addr for c in " \t\n\r%[]/"):
        raise ValueError("Invalid characters in address")

    # Handle :: compression
    if "::" in addr:
        if addr.count("::") > 1:
            raise ValueError("Multiple '::' found")
        left_str, right_str = addr.split("::", 1)
        left_groups = left_str.split(":") if left_str else []
        right_groups = right_str.split(":") if right_str else []
    else:
        if addr.startswith(":") or addr.endswith(":"):
            raise ValueError("Leading or trailing ':' without '::'")
        left_groups = addr.split(":")
        right_groups = []

    all_groups = left_groups + right_groups

    # Check for empty groups (e.g., "1::2:" -> right_groups=["2", ""])
    if any(g == "" for g in all_groups):
        raise ValueError("Empty group found")

    parsed_hex_groups = []
    ipv4_suffix = None

    for i, g in enumerate(all_groups):
        if "." in g:
            if i != len(all_groups) - 1:
                raise ValueError("IPv4 notation must be the last group")
            ipv4_suffix = _parse_ipv4(g)
        else:
            parsed_hex_groups.append(_parse_hex_group(g))

    hex_count = len(parsed_hex_groups)
    total_written = hex_count + (2 if ipv4_suffix is not None else 0)

    if total_written > 8:
        raise ValueError("Too many groups")

    if "::" in addr:
        compressed_zeros = 8 - total_written
        if compressed_zeros < 1:
            raise ValueError(":: must compress at least one group")
    else:
        if total_written != 8:
            raise ValueError("Exactly 8 groups required without '::'")

    # Build full 8-group list
    full_groups = parsed_hex_groups[:]
    if ipv4_suffix is not None:
        a, b, c, d = ipv4_suffix
        full_groups.append((a << 8 | b) & 0xFFFF)
        full_groups.append((c << 8 | d) & 0xFFFF)

    if "::" in addr:
        # Count hex groups on the left side to insert zeros at correct position
        left_hex_count = sum(1 for g in left_groups if "." not in g)
        for _ in range(compressed_zeros):
            full_groups.insert(left_hex_count, 0)

    assert len(full_groups) == 8

    # IPv4-mapped exception: first 80 bits zero, next 16 bits ffff
    if (full_groups[0] == 0 and full_groups[1] == 0 and full_groups[2] == 0 and 
        full_groups[3] == 0 and full_groups[4] == 0 and full_groups[5] == 0xFFFF):
        a = (full_groups[6] >> 8) & 0xFF
        b = full_groups[6] & 0xFF
        c = (full_groups[7] >> 8) & 0xFF
        d = full_groups[7] & 0xFF
        return f"::ffff:{a}.{b}.{c}.{d}"

    # Find longest run of consecutive zero groups (length >= 2)
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0

    for i, val in enumerate(full_groups):
        if val == 0:
            if curr_start == -1:
                curr_start = i
                curr_len = 1
            else:
                curr_len += 1
        else:
            if curr_len > best_len and curr_len >= 2:
                best_start = curr_start
                best_len = curr_len
            curr_start = -1
            curr_len = 0
    if curr_len > best_len and curr_len >= 2:
        best_start = curr_start
        best_len = curr_len

    # Format output
    if best_len >= 2:
        left_part = [_format_hex(g) for g in full_groups[:best_start]]
        right_part = [_format_hex(g) for g in full_groups[best_start + best_len:]]
        return ":".join(left_part) + "::" + ":".join(right_part)
    else:
        return ":".join(_format_hex(g) for g in full_groups)


def _parse_hex_group(g: str) -> int:
    if len(g) > 4:
        raise ValueError(f"Invalid hex group length: {g}")
    if not all(c in "0123456789abcdefABCDEF" for c in g):
        raise ValueError(f"Invalid hex group: {g}")
    return int(g, 16)


def _parse_ipv4(s: str) -> tuple:
    parts = s.split(".")
    if len(parts) != 4:
        raise ValueError(f"Invalid IPv4 notation: {s}")
    nums = []
    for p in parts:
        if not p:
            raise ValueError(f"Invalid IPv4 part: {p}")
        if not p.isdigit():
            raise ValueError(f"Invalid IPv4 part: {p}")
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zero in IPv4 part: {p}")
        val = int(p)
        if val > 255:
            raise ValueError(f"IPv4 part out of range: {p}")
        nums.append(val)
    return tuple(nums)


def _format_hex(val: int) -> str:
    return format(val, 'x')

def shell_split(s: str) -> list[str]:
    """
    Splits a command line string into words like a POSIX shell, without expansion.
    """
    words = []
    current_word = []
    i = 0
    n = len(s)
    mode = 0  # 0: normal, 1: single quote, 2: double quote

    while i < n:
        c = s[i]

        if mode == 0:
            if c in ' \t\n\r':
                # Whitespace separator
                if current_word:
                    words.append(''.join(current_word))
                    current_word = []
                # If current_word is empty, we just skip whitespace
                # (runs of whitespace count as one, leading/trailing ignored)
            elif c == "'":
                mode = 1
            elif c == '"':
                mode = 2
            elif c == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing backslash")
                i += 1
                current_word.append(s[i])
            else:
                current_word.append(c)

        elif mode == 1:
            if c == "'":
                mode = 0
            else:
                # Single quotes are literal, including backslashes
                current_word.append(c)

        elif mode == 2:
            if c == '"':
                mode = 0
            elif c == '\\':
                if i + 1 >= n:
                    raise ValueError("Unterminated backslash in double quotes")
                i += 1
                next_c = s[i]
                if next_c == '"' or next_c == '\\':
                    current_word.append(next_c)
                else:
                    # Backslash followed by anything else is kept together
                    current_word.append('\\')
                    current_word.append(next_c)
            else:
                current_word.append(c)

        i += 1

    if mode != 0:
        raise ValueError("Unterminated quote")

    if current_word:
        words.append(''.join(current_word))

    return words

def shell_split(s: str) -> list[str]:
    words = []
    current_word = []
    mode = 'unquoted'
    i = 0
    n = len(s)
    word_started = False

    while i < n:
        c = s[i]

        if mode == 'unquoted':
            if c in ' \t\n\r':
                if word_started:
                    words.append(''.join(current_word))
                    current_word = []
                    word_started = False
            elif c == "'":
                mode = 'single'
                word_started = True
            elif c == '"':
                mode = 'double'
                word_started = True
            elif c == '\\':
                if i + 1 >= n:
                    raise ValueError("Unexpected end of input while escaping")
                current_word.append(s[i+1])
                word_started = True
                i += 1
            else:
                current_word.append(c)
                word_started = True

        elif mode == 'single':
            if c == "'":
                mode = 'unquoted'
            else:
                current_word.append(c)
                word_started = True

        elif mode == 'double':
            if c == '"':
                mode = 'unquoted'
            elif c == '\\':
                if i + 1 >= n:
                    raise ValueError("Unexpected end of input while escaping")
                next_c = s[i+1]
                if next_c in ('"', '\\'):
                    current_word.append(next_c)
                else:
                    current_word.append('\\')
                    current_word.append(next_c)
                word_started = True
                i += 1
            else:
                current_word.append(c)
                word_started = True

        i += 1

    if mode != 'unquoted':
        raise ValueError("Unterminated quote")

    if word_started:
        words.append(''.join(current_word))

    return words

