                        raise ValueError("malformed \\U escape")
                    val = int(hx, 16)
                    if val > 0x10FFFF:
                        raise ValueError("\\U escape value exceeds 0x10FFFF")
                    res.append(chr(val))
                    i += 8
                elif c in '01234567':
                    oct_s = c
                    while i < len(src) and len(oct_s) < 3 and src[i] in '01234567':
                        oct_s += src[i]
                        i += 1
                    res.append(chr(int(oct_s, 8)))
                else:
                    res.append('\\')
                    res.append(c)
            else:
                res.append(src[i])
                i += 1
    else:
        raise ValueError("unterminated string literal")

    return ''.join(res)

def parse_str_literal(src: str) -> str:
    if not src:
        raise ValueError("Empty input")

    i = 0
    n = len(src)
    raw = False

    # Check for prefix
    if i < n and src[i] in 'rR':
        raw = True
        i += 1

    # Detect quote type
    if i + 2 < n and src[i:i+3] in ("'''", '"""'):
        quote_char = src[i]
        i += 3
        is_triple = True
    elif i < n and src[i] in "'\"":
        quote_char = src[i]
        i += 1
        is_triple = False
    else:
        raise ValueError("Invalid quote")

    result = []
    found_close = False

    while i < n:
        # Check for closing quote
        if is_triple:
            if i + 2 < n and src[i:i+3] == quote_char * 3:
                i += 3
                found_close = True
                break
        else:
            if src[i] == quote_char:
                i += 1
                found_close = True
                break

        # Process content
        if raw:
            if src[i] == '\\':
                if i + 1 < n and src[i+1] == quote_char:
                    result.append(src[i:i+2])
                    i += 2
                else:
                    result.append(src[i])
                    i += 1
            else:
                if not is_triple and src[i] == '\n':
                    raise ValueError("Raw newline in single-quoted string")
                result.append(src[i])
                i += 1
        else:
            if src[i] == '\\':
                if i + 1 >= n:
                    raise ValueError("Unterminated literal")
                nxt = src[i+1]
                if nxt == '\n':
                    i += 2
                elif nxt == '\\':
                    result.append('\\')
                    i += 2
                elif nxt == "'":
                    result.append("'")
                    i += 2
                elif nxt == '"':
                    result.append('"')
                    i += 2
                elif nxt == 'a':
                    result.append('\a')
                    i += 2
                elif nxt == 'b':
                    result.append('\b')
                    i += 2
                elif nxt == 'f':
                    result.append('\f')
                    i += 2
                elif nxt == 'n':
                    result.append('\n')
                    i += 2
                elif nxt == 'r':
                    result.append('\r')
                    i += 2
                elif nxt == 't':
                    result.append('\t')
                    i += 2
                elif nxt == 'v':
                    result.append('\v')
                    i += 2
                elif nxt == 'o':
                    oct_str = ''
                    j = i + 2
                    while j < n and len(oct_str) < 3 and src[j] in '01234567':
                        oct_str += src[j]
                        j += 1
                    if not oct_str:
                        raise ValueError("Malformed octal escape")
                    result.append(chr(int(oct_str, 8)))
                    i = j
                elif nxt == 'x':
                    if i + 3 >= n:
                        raise ValueError("Malformed \\x escape")
                    hex_str = src[i+2:i+4]
                    if len(hex_str) != 2 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Malformed \\x escape")
                    result.append(chr(int(hex_str, 16)))
                    i += 4
                elif nxt == 'u':
                    if i + 5 >= n:
                        raise ValueError("Malformed \\u escape")
                    hex_str = src[i+2:i+6]
                    if len(hex_str) != 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Malformed \\u escape")
                    result.append(chr(int(hex_str, 16)))
                    i += 6
                elif nxt == 'U':
                    if i + 9 >= n:
                        raise ValueError("Malformed \\U escape")
                    hex_str = src[i+2:i+10]
                    if len(hex_str) != 8 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Malformed \\U escape")
                    val = int(hex_str, 16)
                    if val > 0x10FFFF:
                        raise ValueError("\\U value exceeds 0x10FFFF")
                    result.append(chr(val))
                    i += 10
                else:
                    result.append(src[i])
                    result.append(src[i+1])
                    i += 2
            else:
                if not is_triple and src[i] == '\n':
                    raise ValueError("Newline in single-quoted string")
                result.append(src[i])
                i += 1

    if not found_close:
        raise ValueError("Unterminated literal")
    if i < n:
        raise ValueError("Trailing characters")

    return ''.join(result)

def parse_str_literal(src: str) -> str:
    if not src:
        raise ValueError("Empty string")

    raw = False
    idx = 0
    if src[0] in 'rR':
        raw = True
        idx = 1
        if idx >= len(src):
            raise ValueError("Invalid literal")

    quote_char = None
    quote_len = 0
    if src[idx] == "'":
        if len(src) - idx >= 3 and src[idx:idx+3] == "'''":
            quote_len = 3
        else:
            quote_len = 1
        quote_char = "'"
    elif src[idx] == '"':
        if len(src) - idx >= 3 and src[idx:idx+3] == '"""':
            quote_len = 3
        else:
            quote_len = 1
        quote_char = '"'
    else:
        raise ValueError("Invalid opening quote")

    open_idx = idx
    close_idx = -1
    i = open_idx + quote_len
    while i < len(src):
        if src[i] == quote_char and (i == open_idx + quote_len or src[i-1] != '\\'):
            close_idx = i
            break
        i += 1

    if close_idx == -1:
        raise ValueError("Unterminated string literal")

    if close_idx + 1 < len(src):
        raise ValueError("Content after closing quote")

    body = src[open_idx + quote_len : close_idx]

    if raw:
        return body
    else:
        # Check for raw newlines in single-quoted non-triple strings
        if quote_len == 1 and '\n' in body.replace('\\\n', ''):
            raise ValueError("Raw newline in single-quoted string")

        res = []
        j = 0
        n = len(body)
        while j < n:
            if body[j] == '\\':
                if j + 1 >= n:
                    raise ValueError("Invalid escape at end of string")
                next_char = body[j+1]
                if next_char == '\n':
                    j += 2
                    continue
                elif next_char in '\'\"\\abfnrtv':
                    res.append(next_char)
                    j += 2
                elif next_char == 'x':
                    if j + 4 > n:
                        raise ValueError("Invalid \\x escape")
                    hex_str = body[j+2 : j+4]
                    if len(hex_str) != 2 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Invalid \\x escape")
                    res.append(chr(int(hex_str, 16)))
                    j += 4
                elif next_char == 'u':
                    if j + 6 > n:
                        raise ValueError("Invalid \\u escape")
                    hex_str = body[j+2 : j+6]
                    if len(hex_str) != 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Invalid \\u escape")
                    res.append(chr(int(hex_str, 16)))
                    j += 6
                elif next_char == 'U':
                    if j + 10 > n:
                        raise ValueError("Invalid \\U escape")
                    hex_str = body[j+2 : j+10]
                    if len(hex_str) != 8 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Invalid \\U escape")
                    val = int(hex_str, 16)
                    if val > 0x10FFFF:
                        raise ValueError("\\U value exceeds 0x10FFFF")
                    res.append(chr(val))
                    j += 10
                elif '0' <= next_char <= '7':
                    oct_str = ""
                    k = 0
                    while k < 3 and j + 2 + k < n and '0' <= body[j+2+k] <= '7':
                        oct_str += body[j+2+k]
                        k += 1
                    res.append(chr(int(oct_str, 8)))
                    j += 2 + k
                else:
                    res.append('\\')
                    res.append(next_char)
                    j += 2
            else:
                res.append(body[j])
                j += 1
        return "".join(res)

def glob_match(pattern: str, path: str) -> bool:
    def tokenize_segment(seg: str):
        tokens = []
        i = 0
        n = len(seg)
        while i < n:
            ch = seg[i]
            if ch == '\\':
                if i + 1 < n:
                    tokens.append(('LIT', seg[i+1]))
                    i += 2
                else:
                    tokens.append(('LIT', ch))
                    i += 1
            elif ch == '*':
                tokens.append(('STAR',))
                i += 1
            elif ch == '?':
                tokens.append(('QMARK',))
                i += 1
            elif ch == '[':
                j = i + 1
                negated = False
                if j < n and seg[j] == '!':
                    negated = True
                    j += 1

                valid = set()
                first_after_bracket = True
                while j < n:
                    c = seg[j]
                    if c == '\\' and j + 1 < n:
                        valid.add(seg[j+1])
                        j += 2
                    elif c == ']' and first_after_bracket:
                        valid.add(']')
                        first_after_bracket = False
                        j += 1
                    elif c == ']':
                        break
                    elif c == '-' and not first_after_bracket and j + 1 < n and seg[j+1] != ']':
                        prev_c = seg[j-1]
                        if prev_c == '\\' and j > i + 1 + (1 if negated else 0):
                            prev_c = seg[j-2]
                        next_c = seg[j+1]
                        if next_c == '\\' and j + 2 < n:
                            next_c = seg[j+2]
                        for k in range(ord(prev_c), ord(next_c) + 1):
                            valid.add(chr(k))
                        j += 2
                    else:
                        valid.add(c)
                        first_after_bracket = False
                        j += 1

                tokens.append(('SET', valid, negated))
                if j < n and seg[j] == ']':
                    i = j + 1
                else:
                    i += 1
            else:
                tokens.append(('LIT', ch))
                i += 1
        return tokens

    def match_segment(tokens, path_seg: str) -> bool:
        m = len(tokens)
        n = len(path_seg)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True
        for i in range(m):
            for j in range(n + 1):
                if not dp[i][j]:
                    continue
                t = tokens[i]
                if t[0] == 'STAR':
                    dp[i+1][j] = True
                    if j < n:
                        dp[i+1][j+1] = True
                elif t[0] == 'QMARK':
                    if j < n:
                        dp[i+1][j+1] = True
                elif t[0] == 'SET':
                    if j < n and path_seg[j] in t[1]:
                        dp[i+1][j+1] = True
                elif t[0] == 'LIT':
                    if j < n and path_seg[j] == t[1]:
                        dp[i+1][j+1] = True
        return dp[m][n]

    p_segs = pattern.split('/')
    s_segs = path.split('/')
    p_tokens = [tokenize_segment(seg) for seg in p_segs]

    m = len(p_segs)
    n = len(s_segs)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(m):
        for j in range(n + 1):
            if not dp[i][j]:
                continue
            if p_segs[i] == '**':
                if i + 1 <= m and j <= n:
                    dp[i+1][j] = True
                if j + 1 <= n:
                    dp[i][j+1] = True
            else:
                if j < n:
                    if match_segment(p_tokens[i], s_segs[j]):
                        dp[i+1][j+1] = True
    return dp[m][n]

def glob_match(pattern: str, path: str) -> bool:
    p_segs = pattern.split("/")
    s_segs = path.split("/")
    P, S = len(p_segs), len(s_segs)

    _seg_cache = {}

    def _bracket_match(pat: str, char: str) -> bool:
        i = 1
        negate = False
        if pat[i] == '!':
            negate = True
            i += 1
        chars = set()
        while i < len(pat) - 1:
            if pat[i] == ']' and i == 1:
                chars.add(']')
                i += 1
                continue
            if i + 2 < len(pat) - 1 and pat[i+1] == '-' and pat[i+2] != ']':
                c1, c2 = pat[i], pat[i+2]
                for code in range(ord(c1), ord(c2) + 1):
                    chars.add(chr(code))
                i += 3
            else:
                chars.add(pat[i])
                i += 1
        return (char in chars) != negate

    def seg_match(p: str, s: str) -> bool:
        key = (p, s)
        if key in _seg_cache:
            return _seg_cache[key]

        m, n = len(p), len(s)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[m][n] = True

        for i in range(m - 1, -1, -1):
            c = p[i]
            if c == '*':
                dp[i][j] = dp[i+1][j] or (j < n and dp[i][j+1])
            elif c == '?':
                dp[i][j] = j < n and dp[i+1][j+1]
            elif c == '[':
                end = p.find(']', i + 1)
                if j < n and _bracket_match(p[i:end+1], s[j]):
                    dp[i][j] = dp[i+1][j+1]
                else:
                    dp[i][j] = False
            elif c == '\\' and i + 1 < m:
                if j < n and p[i+1] == s[j]:
                    dp[i][j] = dp[i+2][j+1]
                else:
                    dp[i][j] = False
            else:
                dp[i][j] = j < n and p[i] == s[j] and dp[i+1][j+1]

        res = dp[0][0]
        _seg_cache[key] = res
        return res

    dp = [[False] * (S + 1) for _ in range(P + 1)]
    dp[P][S] = True

    for i in range(P - 1, -1, -1):
        for j in range(S, -1, -1):
            if p_segs[i] == "**":
                dp[i][j] = dp[i+1][j] or (j < S and dp[i][j+1])
            else:
                if j < S:
                    if seg_match(p_segs[i], s_segs[j]):
                        dp[i][j] = dp[i+1][j+1]
                    else:
                        dp[i][j] = False
                else:
                    dp[i][j] = False

    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    def parse_bracket_content(pat_seg: str, i: int):
        i += 1
        negate = False
        if i < len(pat_seg) and pat_seg[i] == '!':
            negate = True
            i += 1

        items = []
        first_char = True
        while i < len(pat_seg):
            c = pat_seg[i]
            if c == ']':
                if first_char:
                    items.append(('char', ']'))
                    i += 1
                    continue
                else:
                    break
            elif c == '-' and not first_char and i + 1 < len(pat_seg) and pat_seg[i+1] != ']':
                start_char = items[-1][1]
                end_char = pat_seg[i+1]
                if end_char == '\\' and i+2 < len(pat_seg):
                    end_char = pat_seg[i+2]
                    i += 1
                items[-1] = ('range', start_char, end_char)
                i += 2
                first_char = False
                continue
            elif c == '\\' and i + 1 < len(pat_seg):
                c = pat_seg[i+1]
                i += 1
            items.append(('char', c))
            first_char = False
            i += 1

        def matcher(ch):
            matched = False
            for item in items:
                if item[0] == 'char':
                    if ch == item[1]:
                        matched = True
                        break
                elif item[0] == 'range':
                    if item[1] <= ch <= item[2]:
                        matched = True
                        break
            return (not matched) == negate

        return matcher, i

    def preprocess(pat_seg: str):
        atoms = []
        i = 0
        n = len(pat_seg)
        while i < n:
            c = pat_seg[i]
            if c == '*':
                atoms.append(('any',))
            elif c == '?':
                atoms.append(('one',))
            elif c == '[':
                matcher, next_i = parse_bracket_content(pat_seg, i)
                atoms.append(('bracket', matcher))
                i = next_i
                continue
            elif c == '\\' and i + 1 < n:
                atoms.append(('literal', pat_seg[i+1]))
                i += 2
                continue
            else:
                atoms.append(('char', c))
            i += 1
        return atoms

    def match_segment_atoms(atoms, path_seg):
        n = len(atoms)
        m = len(path_seg)
        dp = [[False]*(m+1) for _ in range(n+1)]
        dp[n][m] = True
        for i in range(n-1, -1, -1):
            atom_type = atoms[i][0]
            for j in range(m-1, -1, -1):
                if atom_type == 'any':
                    dp[i][j] = dp[i+1][j] or dp[i][j+1]
                elif atom_type == 'one':
                    dp[i][j] = dp[i+1][j+1]
                elif atom_type == 'bracket':
                    dp[i][j] = atoms[i][1](path_seg[j]) and dp[i+1][j+1]
                elif atom_type == 'literal':
                    dp[i][j] = (atoms[i][1] == path_seg[j]) and dp[i+1][j+1]
                else:
                    dp[i][j] = (atoms[i][1] == path_seg[j]) and dp[i+1][j+1]
        return dp[0][0]

    pat_segs = pattern.split('/')
    path_segs = path.split('/')
    P, Q = len(pat_segs), len(path_segs)

    seg_atoms = {}
    for i, p in enumerate(pat_segs):
        if p != '**':
            seg_atoms[i] = preprocess(p)

    dp = [[False]*(Q+1) for _ in range(P+1)]
    dp[P][Q] = True

    for i in range(P-1, -1, -1):
        p_seg = pat_segs[i]
        if p_seg == '**':
            for j in range(Q-1, -1, -1):
                dp[i][j] = dp[i+1][j] or dp[i][j+1]
        else:
            atoms = seg_atoms[i]
            for j in range(Q-1, -1, -1):
                if match_segment_atoms(atoms, path_segs[j]):
                    dp[i][j] = dp[i+1][j+1]
                else:
                    dp[i][j] = False

    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    def match_segment(pat: str, seg: str) -> bool:
        pi = 0
        si = 0
        n_pat = len(pat)
        n_seg = len(seg)
        star_pi = -1
        star_si = -1

        while si < n_seg:
            if pi < n_pat and pat[pi] == '\\':
                if pi + 1 < n_pat and pat[pi + 1] == seg[si]:
                    pi += 2
                    si += 1
                    continue
                else:
                    return False
            if pi < n_pat and pat[pi] == seg[si]:
