                matched = False
                while k < j:
                    if k + 2 < j and pat[k + 1] == '-':
                        if pat[k] <= seg[si] <= pat[k + 2]:
                            matched = True
                        k += 3
                    else:
                        if pat[k] == seg[si]:
                            matched = True
                        k += 1
                if (not matched) != neg:
                    pi = j + 1
                    si += 1
                    continue
            if pi < n_pat and pat[pi] == '*':
                star_pi = pi
                star_si = si
                pi += 1
                continue
            if star_pi != -1:
                star_si += 1
                si = star_si
                pi = star_pi + 1
                continue
            return False

        while pi < n_pat and pat[pi] == '*':
            pi += 1
        return pi == n_pat

    p_segs = pattern.split('/')
    s_segs = path.split('/')
    n = len(p_segs)
    m = len(s_segs)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[n][m] = True

    for i in range(n - 1, -1, -1):
        for j in range(m, -1, -1):
            if p_segs[i] == '**':
                dp[i][j] = dp[i + 1][j]
                if j < m:
                    dp[i][j] = dp[i][j] or dp[i][j + 1]
            else:
                if j < m and match_segment(p_segs[i], s_segs[j]):
                    dp[i][j] = dp[i + 1][j + 1]
    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    pat_segs = pattern.split('/')
    path_segs = path.split('/')

    m = len(pat_segs)
    n = len(path_segs)

    # dp[i][j] = can pat_segs[i:] match path_segs[j:]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[m][n] = True

    def segment_match(ps, pp):
        m_s, n_s = len(ps), len(pp)
        d = [[False] * (n_s + 1) for _ in range(m_s + 1)]
        d[m_s][n_s] = True

        for i in range(m_s - 1, -1, -1):
            c = ps[i]
            if c == '*':
                for j in range(n_s, -1, -1):
                    d[i][j] = d[i+1][j] or (d[i][j+1] if j < n_s else False)
            elif c == '?':
                for j in range(n_s, -1, -1):
                    d[i][j] = d[i+1][j+1] if j < n_s else False
            elif c == '[':
                end = i + 1
                while end < m_s and ps[end] != ']':
                    end += 1
                # Parse bracket expression once
                k = i + 1
                negate = False
                if k < m_s and ps[k] in '!^':
                    negate = True
                    k += 1
                # Literal ] right after [ or [!
                literal_close = False
                if k < m_s and ps[k] == ']':
                    literal_close = True
                    k += 1

                rules = []
                while k < end:
                    cc = ps[k]
                    if k + 2 < end and ps[k+1] == '-' and ps[k+2] != ']':
                        rules.append(('range', cc, ps[k+2]))
                        k += 3
                    else:
                        rules.append(('char', cc))
                        k += 1

                for j in range(n_s, -1, -1):
                    if j < n_s:
                        char = pp[j]
                        matched = False
                        for typ, v1, *v2 in rules:
                            if typ == 'char':
                                if char == v1:
                                    matched = True
                                    break
                            else: # range
                                if v1 <= char <= v2[0]:
                                    matched = True
                                    break
                        if literal_close and char == ']':
                            matched = True
                        d[i][j] = (matched ^ negate) and d[end + 1][j+1]
                    else:
                        d[i][j] = False
            elif c == '\\':
                for j in range(n_s, -1, -1):
                    if j < n_s and i + 1 < m_s and ps[i+1] == pp[j]:
                        d[i][j] = d[i+2][j+1]
            else:
                for j in range(n_s, -1, -1):
                    if j < n_s and c == pp[j]:
                        d[i][j] = d[i+1][j+1]
        return d[0][0]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if pat_segs[i] == '**':
                dp[i][j] = dp[i+1][j] or dp[i][j+1]
            else:
                if j < n and segment_match(pat_segs[i], path_segs[j]):
                    dp[i][j] = dp[i+1][j+1]
                else:
                    dp[i][j] = False

    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    P = pattern.split('/')
    S = path.split('/')
    seg_cache = {}

    def parse_tokens(pat_seg: str):
        tokens = []
        i = 0
        n = len(pat_seg)
        while i < n:
            c = pat_seg[i]
            if c == '*':
                tokens.append('*')
                i += 1
            elif c == '?':
                tokens.append('?')
                i += 1
            elif c == '[':
                j = i + 1
                negate = False
                if j < n and pat_seg[j] == '!':
                    negate = True
                    j += 1
                matched = set()
                if j < n and pat_seg[j] == ']':
                    matched.add(']')
                    j += 1
                while j < n and pat_seg[j] != ']':
                    if pat_seg[j] == '\\':
                        matched.add(pat_seg[j+1])
                        j += 2
                    elif j + 2 < n and pat_seg[j+1] == '-' and pat_seg[j+2] != ']':
                        for k in range(ord(pat_seg[j]), ord(pat_seg[j+2]) + 1):
                            matched.add(chr(k))
                        j += 3
                    else:
                        matched.add(pat_seg[j])
                        j += 1
                tokens.append(matched)
                i = j + 1
            elif c == '\\':
                tokens.append(pat_seg[i+1])
                i += 2
            else:
                tokens.append(c)
                i += 1
        return tokens

    def segment_match(pat_seg: str, path_seg: str) -> bool:
        key = (pat_seg, path_seg)
        if key in seg_cache:
            return seg_cache[key]
        tokens = parse_tokens(pat_seg)
        m = len(tokens)
        n = len(path_seg)
        dp = [[False]*(n+1) for _ in range(m+1)]
        dp[0][0] = True
        for i in range(1, m+1):
            dp[i][0] = dp[i-1][0] and tokens[i-1] == '*'
        for i in range(1, m+1):
            tok = tokens[i-1]
            for j in range(1, n+1):
                if tok == '*':
                    dp[i][j] = dp[i-1][j] or dp[i][j-1]
                elif tok == '?':
                    dp[i][j] = dp[i-1][j-1]
                elif isinstance(tok, set):
                    dp[i][j] = dp[i-1][j-1] and (path_seg[j-1] in tok)
                else:
                    dp[i][j] = dp[i-1][j-1] and (tok == path_seg[j-1])
        res = dp[m][n]
        seg_cache[key] = res
        return res

    dp = [[False]*(len(S)+1) for _ in range(len(P)+1)]
    dp[len(P)][len(S)] = True

    for i in range(len(P)-1, -1, -1):
        for j in range(len(S)-1, -1, -1):
            if P[i] == '**':
                dp[i][j] = dp[i+1][j] or (dp[i][j+1] if j < len(S) else False)
            else:
                dp[i][j] = segment_match(P[i], S[j]) and dp[i+1][j+1]

    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    def tokenize(p_seg: str):
        tokens = []
        i = 0
        n = len(p_seg)
        while i < n:
            c = p_seg[i]
            if c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '[':
                negated = False
                j = i + 1
                if j < n and p_seg[j] == '!':
                    negated = True
                    j += 1

                chars = set()
                # "]" right after "[" or "[!" is a literal member
                if j < n and p_seg[j] == ']':
                    chars.add(']')
                    j += 1

                while j < n and p_seg[j] != ']':
                    ch = p_seg[j]
                    if ch == '\\':
                        j += 1
                        if j < n:
                            chars.add(p_seg[j])
                        j += 1
                        continue
                    if j + 2 < n and p_seg[j+1] == '-' and p_seg[j+2] != ']':
                        start_c = ch
                        end_c = p_seg[j+2]
                        for code in range(ord(start_c), ord(end_c) + 1):
                            chars.add(chr(code))
                        j += 3
                    else:
                        chars.add(ch)
                        j += 1
                j += 1  # skip closing ']'
                tokens.append(('char_class', chars, negated))
                i = j
            elif c == '\\':
                i += 1
                if i < n:
                    tokens.append(('literal', p_seg[i]))
                i += 1
            else:
                tokens.append(('literal', c))
                i += 1
        return tokens

    def segment_match(tokens, s: str) -> bool:
        M = len(tokens)
        N = len(s)
        dp = [[False] * (N + 1) for _ in range(M + 1)]
        dp[0][0] = True

        # Handle leading stars matching empty string
        i = 0
        while i < M and tokens[i][0] == 'star':
            dp[i+1][0] = True
            i += 1

        for i in range(M):
            for j in range(N + 1):
                if not dp[i][j]:
                    continue
                token = tokens[i]
                if token[0] == 'star':
                    dp[i+1][j] = True
                    if j < N:
                        dp[i][j+1] = True
                elif token[0] == 'any':
                    if j < N:
                        dp[i+1][j+1] = True
                elif token[0] == 'char_class':
                    if j < N:
                        c = s[j]
                        in_set = c in token[1]
                        if token[2] ^ in_set:
                            dp[i+1][j+1] = True
                elif token[0] == 'literal':
                    if j < N and s[j] == token[1]:
                        dp[i+1][j+1] = True
        return dp[M][N]

    p_segs = pattern.split("/")
    a_segs = path.split("/")

    comp_p_segs = []
    for ps in p_segs:
        if ps == "**":
            comp_p_segs.append(None)
        else:
            comp_p_segs.append(tokenize(ps))

    M2 = len(comp_p_segs)
    N2 = len(a_segs)
    dp2 = [[False] * (N2 + 1) for _ in range(M2 + 1)]
    dp2[0][0] = True

    for i in range(M2):
        for j in range(N2 + 1):
            if not dp2[i][j]:
                continue
            tokenized = comp_p_segs[i]
            if tokenized is None:  # **
                dp2[i+1][j] = True
                if j < N2:
                    dp2[i][j+1] = True
            else:
                if j < N2:
                    if segment_match(tokenized, a_segs[j]):
                        dp2[i+1][j+1] = True

    return dp2[M2][N2]

def glob_match(pattern: str, path: str) -> bool:
    p_segs = pattern.split("/")
    s_segs = path.split("/")

    def parse_bracket(pat, start):
        i = start + 1  # skip '['
        negate = False
        if i < len(pat) and pat[i] == '!':
            negate = True
            i += 1
        ranges = []
        individual = set()
        # Literal ']' right after '[' or '[!'
        if i < len(pat) and pat[i] == ']':
            individual.add(']')
            i += 1
        while i < len(pat) and pat[i] != ']':
            if i + 2 < len(pat) and pat[i+1] == '-' and pat[i+2] != ']':
                ranges.append((pat[i], pat[i+2]))
                i += 3
            else:
                individual.add(pat[i])
                i += 1
        return ('R', ranges, individual, negate), i + 1  # skip ']'

    def parse_segment(pat):
        ops = []
        i = 0
        n = len(pat)
        while i < n:
            c = pat[i]
            if c == '\\':
                if i + 1 < n:
                    ops.append(('L', pat[i+1]))
                    i += 2
                else:
                    ops.append(('L', c))
                    i += 1
            elif c == '*':
                ops.append(('S',))
                i += 1
            elif c == '?':
                ops.append(('Q',))
                i += 1
            elif c == '[':
                op, i = parse_bracket(pat, i)
                ops.append(op)
            else:
                ops.append(('L', c))
                i += 1
        return ops

    p_ops = [parse_segment(seg) for seg in p_segs]

    def segment_match(ops, path):
        m = len(ops)
        n = len(path)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True
        for i in range(1, m + 1):
            op = ops[i-1]
            if op[0] == 'S':
                dp[i][0] = dp[i-1][0]
                for j in range(1, n + 1):
                    dp[i][j] = dp[i-1][j] or dp[i][j-1]
            else:
                for j in range(1, n + 1):
                    if op[0] == 'L':
                        if dp[i-1][j-1] and path[j-1] == op[1]:
                            dp[i][j] = True
                    elif op[0] == 'Q':
                        if dp[i-1][j-1]:
                            dp[i][j] = True
                    elif op[0] == 'R':
                        _, ranges, individual, negate = op
                        c = path[j-1]
                        matches = (c in individual) or any(a <= c <= b for a, b in ranges)
                        if negate:
                            matches = not matches
                        if dp[i-1][j-1] and matches:
                            dp[i][j] = True
        return dp[m][n]

    m = len(p_segs)
    n = len(s_segs)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[m][n] = True

    for i in range(m - 1, -1, -1):
        for j in range(n, -1, -1):
            if p_segs[i] == "**":
                dp[i][j] = dp[i+1][j]
                if not dp[i][j] and j < n:
                    dp[i][j] = dp[i][j+1]
            else:
                if j < n:
                    dp[i][j] = segment_match(p_ops[i], s_segs[j]) and dp[i+1][j+1]
                else:
                    dp[i][j] = False

    return dp[0][0]

def justify(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    processed_words = []
    for w in words:
        if len(w) > width:
            for i in range(0, len(w), width):
                processed_words.append(w[i:i+width])
        else:
            processed_words.append(w)

    lines = []
    current_line = []
    current_len = 0
    for w in processed_words:
        if not current_line:
            current_line.append(w)
            current_len = len(w)
        else:
            if current_len + 1 + len(w) <= width:
                current_line.append(w)
                current_len += 1 + len(w)
            else:
                lines.append(current_line)
                current_line = [w]
                current_len = len(w)
    if current_line:
        lines.append(current_line)

    result = []
    for i, line in enumerate(lines):
        if i == len(lines) - 1:
            result.append(" ".join(line).ljust(width))
        elif len(line) == 1:
            result.append(line[0].ljust(width))
        else:
            total_word_len = sum(len(w) for w in line)
            total_spaces = width - total_word_len
            num_gaps = len(line) - 1
            base_space = total_spaces // num_gaps
            extra = total_spaces % num_gaps
            parts = []
            for j, w in enumerate(line):
                parts.append(w)
                if j < len(line) - 1:
                    spaces = base_space + (1 if j < extra else 0)
                    parts.append(" " * spaces)
            result.append("".join(parts))
    return result

import re

def apply_patch(old: list[str], patch: str) -> list[str]:
    if not patch:
        return old.copy()

    lines = patch.rstrip('\n').split('\n')
    if len(lines) < 2:
        raise ValueError("Missing headers")
    if not (lines[0].startswith('--- ') and lines[1].startswith('+++ ')):
        raise ValueError("Invalid headers")

    hunk_lines = lines[2:]
    if not hunk_lines:
        raise ValueError("Missing hunk")

    new_lines = []
    old_idx = 0
    cumulative_diff = 0

    i = 0
    while i < len(hunk_lines):
        line = hunk_lines[i]
        if not line.startswith('@@ -'):
            raise ValueError("Expected hunk header")

        m = re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@$', line)
        if not m:
            raise ValueError("Invalid hunk header")

        s, c, s2, c2 = m.groups()
        s, s2 = int(s), int(s2)
        c = int(c) if c is not None else 1
        c2 = int(c2) if c2 is not None else 1
        i += 1

        old_start = (s - 1) if c > 0 else s
        new_start = (s2 - 1) if c2 > 0 else s2

        if old_idx != old_start:
            raise ValueError(f"Hunk starts at wrong old position: expected {old_start}, got {old_idx}")
        if len(new_lines) != new_start:
            raise ValueError(f"Hunk starts at wrong new position: expected {new_start}, got {len(new_lines)}")
        if new_start != old_start + cumulative_diff:
            raise ValueError("Inconsistent new-side start")

        ctx_del_count = 0
        ctx_add_count = 0

        while i < len(hunk_lines) and (ctx_del_count < c or ctx_add_count < c2):
            bline = hunk_lines[i]
            if len(bline) == 0:
                raise ValueError("Empty body line")

            marker = bline[0]
            text = bline[1:]

            if marker == ' ':
                ctx_del_count += 1
                ctx_add_count += 1
                if old_idx >= len(old):
                    raise ValueError("Context line exceeds old length")
                if text != old[old_idx]:
                    raise ValueError("Context line mismatch")
                old_idx += 1
            elif marker == '-':
                ctx_del_count += 1
                if old_idx >= len(old):
                    raise ValueError("Delete line exceeds old length")
                if text != old[old_idx]:
                    raise ValueError("Delete line mismatch")
                old_idx += 1
            elif marker == '+':
                ctx_add_count += 1
                new_lines.append(text)
            else:
                raise ValueError(f"Invalid body line marker: {marker}")

            i += 1

        if ctx_del_count != c:
            raise ValueError(f"Expected {c} context/delete lines, got {ctx_del_count}")
        if ctx_add_count != c2:
            raise ValueError(f"Expected {c2} context/add lines, got {ctx_add_count}")

        cumulative_diff += c2 - c

    return new_lines

