def apply_patch(old: list[str], patch: str) -> list[str]:
    if patch == '':
        return old.copy()

    lines = patch.split('\n')
    if lines and lines[-1] == '':
        lines.pop()

    if len(lines) < 2 or not lines[0].startswith('--- ') or not lines[1].startswith('+++ '):
        raise ValueError("Invalid patch header")

    hunk_pattern = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@$')

    idx = 2
    n = len(lines)
    new_lines = []
    old_idx = 0
    new_pos = 0

    while idx < n:
        line = lines[idx]
        if not line.startswith('@@ -') or not line.endswith(' @@'):
            raise ValueError("Invalid hunk header format")
        m = hunk_pattern.match(line)
        if not m:
            raise ValueError("Malformed hunk header")

        s_str, c_str, s2_str, c2_str = m.groups()
        S = int(s_str)
        C = int(c_str) if c_str is not None else 1
        S2 = int(s2_str)
        C2 = int(c2_str) if c2_str is not None else 1

        if S < 0 or S2 < 0 or C < 0 or C2 < 0:
            raise ValueError("Invalid numbers in hunk header")

        old_start_0 = S - 1 if C > 0 else S
        new_start_0 = S2 - 1 if C2 > 0 else S2

        if old_start_0 != old_idx:
            raise ValueError("Hunk start position mismatch")
        if new_start_0 != old_idx + new_pos:
            raise ValueError("New side start position mismatch")
        if old_start_0 > len(old):
            raise ValueError("Hunk starts beyond end of old")

        idx += 1
        expect_ctx_minus = 0
        expect_ctx_plus = 0

        while expect_ctx_minus < C or expect_ctx_plus < C2:
            if idx >= n:
                raise ValueError("Patch ends prematurely in hunk body")
            body = lines[idx]
            if not body:
                raise ValueError("Empty body line")
            kind = body[0]
            text = body[1:]

            if kind == '+':
                expect_ctx_plus += 1
                new_lines.append(text)
            elif kind in (' ', '-'):
                if old_idx >= len(old):
                    raise ValueError("Context/minus line beyond old end")
                if old[old_idx] != text:
                    raise ValueError("Context/minus line mismatch")
                expect_ctx_minus += 1
                expect_ctx_plus += 1
                old_idx += 1
            else:
                raise ValueError("Invalid body line kind")

            idx += 1

        if expect_ctx_minus != C or expect_ctx_plus != C2:
            raise ValueError("Hunk body count mismatch")

        new_pos += C2 - C

    if old_idx != len(old):
        raise ValueError("Patch does not cover entire old file")

    return new_lines

