def apply_patch(old: list[str], patch: str) -> list[str]:
    if patch == "":
        return old.copy()

    if patch.endswith('\n'):
        patch = patch[:-1]

    lines = patch.split('\n')
    if len(lines) < 2:
        raise ValueError("Header lines missing")
    if not lines[0].startswith("--- ") or not lines[1].startswith("+++ "):
        raise ValueError("Invalid header lines")

    hunk_regex = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@$')

    old_idx = 0
    new_idx = 0
    new_list = []
    i = 2

    while i < len(lines):
        line = lines[i]
        m = hunk_regex.match(line)
        if not m:
            raise ValueError(f"Invalid hunk header: {line}")

        old_start = int(m.group(1))
        old_count = int(m.group(2)) if m.group(2) is not None else 1
        new_start = int(m.group(3))
        new_count = int(m.group(4)) if m.group(4) is not None else 1

        expected_old_idx = old_start - 1 if old_count > 0 else old_start
        if expected_old_idx != old_idx:
            raise ValueError("Old side index mismatch")
        if old_idx + old_count > len(old):
            raise ValueError("Hunk extends beyond end of old")

        expected_new_idx = new_start - 1 if new_count > 0 else new_start
        if expected_new_idx != new_idx:
            raise ValueError("New side index mismatch")

        c_seen = 0
        c2_seen = 0
        i += 1
        while i < len(lines):
            if c_seen >= old_count and c2_seen >= new_count:
                break

            body_line = lines[i]
            if len(body_line) == 0:
                raise ValueError("Empty body line")

            kind = body_line[0]
            text = body_line[1:]

            if kind == ' ':
                if c_seen >= old_count or c2_seen >= new_count:
                    raise ValueError("Too many lines in hunk body")
                c_seen += 1
                c2_seen += 1
                if text != old[old_idx]:
                    raise ValueError("Context line mismatch")
                new_list.append(text)
                old_idx += 1
            elif kind == '-':
                if c_seen >= old_count:
                    raise ValueError("Too many delete lines in hunk body")
                c_seen += 1
                if text != old[old_idx]:
                    raise ValueError("Deleted line mismatch")
                old_idx += 1
            elif kind == '+':
                if c2_seen >= new_count:
                    raise ValueError("Too many insert lines in hunk body")
                c2_seen += 1
                new_list.append(text)
            else:
                raise ValueError(f"Invalid line kind: {kind}")

            i += 1

        if c_seen != old_count or c2_seen != new_count:
            raise ValueError("Hunk body count mismatch")

    if old_idx != len(old):
        raise ValueError("Patch does not cover entire file")

    return new_list

