        header = lines[i]
        m = hunk_re.match(header)
        if not m:
            raise ValueError(f"Invalid hunk header: {header}")

        S = int(m.group(1))
        C = int(m.group(2)) if m.group(2) is not None else 1
        S2 = int(m.group(3))
        C2 = int(m.group(4)) if m.group(4) is not None else 1

        if C > 0 and S < 1:
            raise ValueError("Invalid S for C > 0")
        if C2 > 0 and S2 < 1:
            raise ValueError("Invalid S2 for C2 > 0")

        old_start = S if C == 0 else S - 1
        new_start = S2 if C2 == 0 else S2 - 1

        if old_start < old_idx or old_start > len(old):
            raise ValueError("Hunk start out of bounds")

        if old_start > old_idx:
            new_lines.extend(old[old_idx:old_start])
        old_idx = old_start

        if new_start != len(new_lines):
            raise ValueError("New side start inconsistent")

        ctx_count = 0
        del_count = 0
        add_count = 0
        total_lines = C + C2

