        # S is 1-based index of first line if C > 0.
        # S is line number before insertion point if C == 0 (0 = before first line).
        if C > 0:
            expected_S = old_idx + 1
            if S != expected_S:
                raise ValueError(f"Hunk start mismatch: expected S={expected_S}, got S={S}")
        else:
            # C == 0, insertion at a point. S is line number before.
            # If S=0, before first line (index 0). If S=1, after line 1 (index 1).
            # So S should equal old_idx.
            if S != old_idx:
                raise ValueError(f"Hunk start mismatch: expected S={old_idx}, got S={S}")

