        # S2 is 1-based index of first line if C2 > 0.
        # S2 is line number before insertion point if C2 == 0.
        # Consistency check: new_start_index == old_start_index + shift

        if C > 0:
            old_start_index = S - 1
        else:
            old_start_index = S

