        # Check next line is either another hunk or end of patch
        if idx < len(lines):
            if not lines[idx].startswith("@@"):
                raise ValueError(f"Unexpected line after hunk body: {lines[idx]}")

    # Append any remaining lines from old file
    if old_idx < len(old):
        new_lines.extend(old[old_idx:])

    return new_lines

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    import re

    # Helper to check if a character is a valid start of a name
    def is_name_start(c):
        return c.isalpha() or c == '_'

    # Helper to check if a character is a valid name char
    def is_name_char(c):
        return c.isalnum() or c in '_.-'

    # Helper to check whitespace
    def is_ws(c):
        return c in ' \t\n\r'

    # Helper to raise error
    def error(msg=""):
        raise ValueError(msg)

    # Parser state
    pos = 0
    length = len(s)

    def peek(offset=0):
        idx = pos + offset
        if idx < length:
            return s[idx]
        return None

    def advance(n=1):
        nonlocal pos
        pos += n

    def consume_whitespace():
        nonlocal pos
        while pos < length and is_ws(s[pos]):
            pos += 1

    def parse_name():
        nonlocal pos
        if pos >= length or not is_name_start(s[pos]):
            error("Expected name start")

        start = pos
        pos += 1
        while pos < length and is_name_char(s[pos]):
            pos += 1

        return s[start:pos]

    def parse_attribute(attrs_dict):
        nonlocal pos
        # Expect Name
        name = parse_name()
        if name in attrs_dict:
            error(f"Duplicate attribute: {name}")

        # Expect optional whitespace then '='
        consume_whitespace()
        if pos >= length or s[pos] != '=':
            error("Expected '=' in attribute")
        pos += 1 # consume '='

        # Expect optional whitespace
        consume_whitespace()

        # Expect quote
        if pos >= length:
            error("Expected quote for attribute value")
        quote_char = s[pos]
        if quote_char not in ('"', "'"):
            error("Expected quote for attribute value")
        pos += 1 # consume quote

        # Parse value content
        value_chars = []
        while pos < length and s[pos] != quote_char:
            if s[pos] == '<':
                error("'< ' not allowed in attribute value")
            if s[pos] == quote_char:
                # Should not happen if loop condition correct, but safety
                error("Unexpected quote in attribute value")
            if s[pos] == '&':
                # Parse reference
                char = parse_reference()
                value_chars.append(char)
            else:
                value_chars.append(s[pos])
                pos += 1

        if pos >= length:
            error("Unterminated attribute value")
        pos += 1 # consume closing quote

        attrs_dict[name] = "".join(value_chars)

    def parse_reference():
        nonlocal pos
        if pos >= length or s[pos] != '&':
            error("Expected '&' for reference")
        pos += 1 # consume '&'

        if pos >= length:
            error("Unexpected end of input in reference")

        if s[pos] == '#':
            pos += 1 # consume '#'
            if pos >= length:
                error("Unexpected end of input in numeric reference")

            is_hex = False
            if s[pos] == 'x':
                is_hex = True
                pos += 1
            elif s[pos] == 'X':
                error("Only lowercase 'x' allowed for hex references")
                # Should not return, but for flow
            else:
                is_hex = False # Decimal

            # Read digits
            digits = []
            if pos >= length:
                error("No digits in numeric reference")

            while pos < length and (s[pos].isdigit() or (is_hex and s[pos] in '0123456789abcdefABCDEF')):
                digits.append(s[pos])
                pos += 1

            if not digits:
                error("No digits in numeric reference")

            if pos >= length or s[pos] != ';':
                error("Missing ';' in numeric reference")
            pos += 1 # consume ';'

            try:
                if is_hex:
                    code_point = int("".join(digits), 16)
                else:
                    code_point = int("".join(digits), 10)
            except ValueError:
                error("Invalid numeric reference")

            # Validate code point
            if code_point < 1:
                error("Code point 0 not allowed")
            if code_point > 0x10FFFF:
                error("Code point out of range")
            if 0xD800 <= code_point <= 0xDFFF:
                error("Surrogate code points not allowed")

            return chr(code_point)
        else:
            # Named reference
            name_chars = []
            while pos < length and s[pos] != ';':
                if not (s[pos].isalnum() or s[pos] == '_'):
                    error("Invalid character in reference name")
                name_chars.append(s[pos])
                pos += 1

            if pos >= length:
                error("Unterminated reference")
            if s[pos] != ';':
                error("Expected ';' in reference")
            pos += 1 # consume ';'

            name = "".join(name_chars)
            if name == 'lt':
                return '<'
            elif name == 'gt':
                return '>'
            elif name == 'amp':
                return '&'
            elif name == 'quot':
                return '"'
            elif name == 'apos':
                return "'"
            else:
                error(f"Unknown entity: &{name};")

    def parse_element():
        nonlocal pos
        # Expect '<'
        if pos >= length or s[pos] != '<':
            error("Expected '<' for element")
        pos += 1

        # Parse tag name
        tag = parse_name()

        # Parse attributes
        attrs = {}

        # Check for whitespace or end of tag
        # Grammar: zero or more attributes each preceded by at least one whitespace character
        # So after tag name, we can have whitespace then attribute, or whitespace then /> or >

        # Consume initial whitespace before attributes
        consume_whitespace()

        # Check if we are at end of tag start
        if pos < length and s[pos] in ('>', '/'):
            if s[pos] == '/':
                # Empty element <tag />
                pos += 1
                if pos >= length or s[pos] != '>':
                    error("Expected '>' after '/'")
                pos += 1
                return (tag, attrs, [])
            else:
                # <tag> start content
                pos += 1
                children = parse_content()
                # Expect closing tag </tag>
                if pos >= length or s[pos] != '<':
                    error("Expected '</' for closing tag")
                pos += 1 # consume '<'
                if pos >= length or s[pos] != '/':
                    error("Expected '/' after '<' in closing tag")
                pos += 1 # consume '/'

                close_tag = parse_name()
                if close_tag != tag:
                    error(f"Mismatched tags: <{tag}> and </{close_tag}>")

                # Optional whitespace before '>'
                consume_whitespace()
                if pos >= length or s[pos] != '>':
                    error("Expected '>' at end of closing tag")
                pos += 1

                return (tag, attrs, children)

        # If not at > or /, we might be at an attribute
        # But attributes must be preceded by whitespace.
        # We already consumed whitespace.
        # If next char is not Name start, it's an error (unless we missed > or / check?)
        # Wait, if we consumed whitespace and are not at > or /, we must be at Name start for attribute.

        if pos < length and is_name_start(s[pos]):
            # Parse attributes loop
            while True:
                # Parse attribute
                parse_attribute(attrs)

                # After attribute value, expect whitespace or end of tag
                # Grammar: "each preceded by at least one whitespace character"
                # This implies separation.
                # So after value, we must have whitespace before next attribute or end.

                # Consume whitespace after attribute value
                consume_whitespace()

                if pos < length and s[pos] in ('>', '/'):
                    if s[pos] == '/':
                        # Empty element <tag attr="val" />
                        pos += 1
                        if pos >= length or s[pos] != '>':
                            error("Expected '>' after '/'")
                        pos += 1
                        return (tag, attrs, [])
                    else:
                        # <tag attr="val">
                        pos += 1
                        children = parse_content()
                        if pos >= length or s[pos] != '<':
                            error("Expected '</' for closing tag")
                        pos += 1
                        if pos >= length or s[pos] != '/':
                            error("Expected '/' after '<' in closing tag")
                        pos += 1
                        close_tag = parse_name()
                        if close_tag != tag:
                            error(f"Mismatched tags: <{tag}> and </{close_tag}>")
                        consume_whitespace()
                        if pos >= length or s[pos] != '>':
                            error("Expected '>' at end of closing tag")
                        pos += 1
                        return (tag, attrs, children)

                # If not > or /, check if next attribute
                # Must be preceded by whitespace. We consumed whitespace.
                # So if next is Name, it's an attribute.
                # But wait, if we consumed whitespace and found Name, it means there WAS whitespace.
                # So it's valid.
                # If next is not Name, error.

                if pos < length and is_name_start(s[pos]):
                    continue
                else:
                    # If we are here, we consumed whitespace, didn't find > or /, and didn't find Name.
                    # This means we have whitespace followed by something else (e.g. <, =, etc)
                    # Or end of string.
                    error("Unexpected character after attribute value")
        else:
            # After tag name and whitespace, we are not at >, /, or Name.
            # Error.
            # Check if we are at end of string
            if pos >= length:
                error("Unexpected end of input")
            error(f"Unexpected character '{s[pos]}' after tag name")

    def parse_content():
        nonlocal pos
        children = []
        text_buffer = []

        while True:
            if pos >= length:
                error("Unexpected end of input in content")

            char = s[pos]

            if char == '<':
                # Check for closing tag
                if pos + 1 < length and s[pos+1] == '/':
                    # Closing tag found
                    break

                # Child element
                # Flush text buffer
                if text_buffer:
                    text_str = "".join(text_buffer)
                    if text_str:
                        children.append(text_str)
                    text_buffer = []

                child = parse_element()
                children.append(child)

            elif char == '&':
                # Reference
                char = parse_reference()
                text_buffer.append(char)

            else:
                # Text
                # Text chars: anything except < and &
                # Scan forward
                start = pos
                while pos < length and s[pos] not in ('<', '&'):
                    pos += 1
                text_str = s[start:pos]
                if text_str:
                    text_buffer.append(text_str)

        # End of content (closing tag found)
        if text_buffer:
            text_str = "".join(text_buffer)
            if text_str:
                children.append(text_str)

        return children

    # Main parsing logic
    # Document: optional whitespace, exactly one element, optional whitespace, end.

    consume_whitespace()

    if pos >= length:
        error("Empty input")

    root = parse_element()

    consume_whitespace()

    if pos < length:
        error("Unexpected content after root element")

    return root

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    import re

    # Helper to check if char is whitespace
    def is_ws(c):
        return c in (' ', '\t', '\n', '\r')

    # Helper to check if char is valid Name start
    def is_name_start(c):
        return c.isalpha() or c == '_'

    # Helper to check if char is valid Name char
    def is_name_char(c):
        return c.isalnum() or c in ('_', '.', '-')

    # State
    idx = 0
    length = len(s)

    def peek(offset=0):
        pos = idx + offset
        if pos < length:
            return s[pos]
        return None

    def advance(n=1):
        nonlocal idx
        idx += n

    def skip_whitespace():
        nonlocal idx
        while idx < length and is_ws(s[idx]):
            idx += 1

    def error(msg="Invalid XML"):
        raise ValueError(msg)

    # Parse Name
    def parse_name():
        nonlocal idx
        if idx >= length or not is_name_start(s[idx]):
            error("Expected Name start")
        start = idx
        while idx < length and is_name_char(s[idx]):
            idx += 1
        return s[start:idx]

    # Parse Attribute
    def parse_attribute():
        nonlocal idx
        # Name
        name = parse_name()

        # Optional whitespace
        skip_whitespace()

        # '='
        if idx >= length or s[idx] != '=':
            error("Expected '=' in attribute")
        idx += 1

        # Optional whitespace
        skip_whitespace()

        # Value
        if idx >= length:
            error("Expected value in attribute")
        quote = s[idx]
        if quote not in ('"', "'"):
            error("Attribute value must be quoted")
        idx += 1

        # Value content
        val_start = idx
        val_chars = []
        while idx < length and s[idx] != quote:
            if s[idx] == '<':
                error("Attribute value cannot contain '<'")
            if s[idx] == '&':
                # Parse reference
                ref_char = parse_reference()
                val_chars.append(ref_char)
            else:
                val_chars.append(s[idx])
                idx += 1

        if idx >= length:
            error("Unterminated attribute value")

        # Closing quote
        if s[idx] != quote:
            error("Expected closing quote")
        idx += 1 # consume quote

        value = "".join(val_chars)
        return name, value

    # Parse Reference
    def parse_reference():
        nonlocal idx
        if idx >= length or s[idx] != '&':
            error("Expected '&' for reference")
        idx += 1 # consume &

        if idx >= length:
            error("Unexpected end after '&'")

        c = s[idx]
        if c == 'l':
            if s[idx:idx+3] == '&lt;':
                idx += 3
                return '<'
            error("Invalid reference")
        elif c == 'g':
            if s[idx:idx+3] == '&gt;':
                idx += 3
                return '>'
            error("Invalid reference")
        elif c == 'a':
            if s[idx:idx+4] == '&amp;':
                idx += 4
                return '&'
            elif s[idx:idx+5] == '&apos;':
                idx += 5
                return "'"
            error("Invalid reference")
        elif c == 'q':
            if s[idx:idx+6] == '&quot;':
                idx += 6
                return '"'
            error("Invalid reference")
        elif c == '#':
            idx += 1 # consume #
            if idx >= length:
                error("Unexpected end after '&#")

            is_hex = False
            if s[idx] == 'x':
                is_hex = True
                idx += 1
            elif s[idx].isdigit():
                pass
            else:
                error("Expected digit or 'x' after '&#")

            num_start = idx
            while idx < length and (s[idx].isdigit() or (is_hex and s[idx] in '0123456789abcdefABCDEF')):
                idx += 1

            if idx == num_start:
                error("No digits in reference")

            if idx >= length or s[idx] != ';':
                error("Missing ';' in reference")
            idx += 1 # consume ;

            num_str = s[num_start:idx-1]
            try:
                if is_hex:
                    code_point = int(num_str, 16)
                else:
                    code_point = int(num_str, 10)
            except ValueError:
                error("Invalid reference number")

            if code_point == 0 or code_point > 0x10FFFF:
                error("Invalid code point")
            if 0xD800 <= code_point <= 0xDFFF:
                error("Surrogate code point")

            return chr(code_point)
        else:
            error("Invalid reference")

    # Parse Element
    def parse_element():
        nonlocal idx

        # <
        if idx >= length or s[idx] != '<':
            error("Expected '<' for element")
        idx += 1

        # Name
        tag = parse_name()

        # Attributes
        attrs = {}
        needs_whitespace = True

        while True:
            skip_whitespace()

            # Check for closing tag
            if peek() in ('/', '>'):
                break

            # Check for PI/Comment/Doctype
            if peek() in ('?', '!'):
                error("Comments, PIs, and DOCTYPEs are not supported")

            # Check for valid Name start
            if not is_name_start(peek()):
                error("Expected attribute name or closing tag")

            # Check whitespace requirement
            if needs_whitespace:
                # We consumed whitespace, so it's valid
                needs_whitespace = False
            else:
                # We didn't consume whitespace, but we are looking for an attribute
                # This implies adjacent attributes without whitespace or similar
                error("Attributes must be separated by whitespace")

            # Parse Attribute
            name, value = parse_attribute()
            if name in attrs:
                error(f"Duplicate attribute: {name}")
            attrs[name] = value
            needs_whitespace = True

        # Check closer
        if idx >= length:
            error("Unterminated element")

        if peek() == '/':
            # Empty element
            idx += 1
            if idx >= length or s[idx] != '>':
                error("Expected '>'")
            idx += 1
            return (tag, attrs, [])
        elif peek() == '>':
            idx += 1
            # Parse Content
            children = parse_content(tag)
            return (tag, attrs, children)
        else:
            error("Expected '>' or '/>'")

    # Parse Content
    def parse_content(closing_tag):
        nonlocal idx
        children = []
        buffer = []

        while True:
            if idx >= length:
                error(f"Unterminated element, expected </{closing_tag}>")

            c = s[idx]

            if c == '<':
                # Check for closing tag
                if s[idx:idx+2] == '</':
                    # Check if it matches
                    if idx + 2 + len(closing_tag) + 1 <= length:
                        # Check tag name
                        tag_end = idx + 2 + len(closing_tag)
                        if s[idx+2:tag_end] == closing_tag:
                            # Check whitespace and >
                            rest = s[tag_end:]
                            # Optional whitespace before >
                            j = 0
                            while j < len(rest) and is_ws(rest[j]):
                                j += 1
                            if j < len(rest) and rest[j] == '>':
                                idx = tag_end + j + 1
                                break
                            else:
                                error("Expected '>' after closing tag name")
                        else:
                            error(f"Tag mismatch: expected </{closing_tag}>")
                    else:
                        error("Unexpected end of input")

                # Child element
                child = parse_element()
                # Flush buffer
                if buffer:
                    children.append("".join(buffer))
                    buffer = []
                children.append(child)

            elif c == '&':
                # Reference
                ref = parse_reference()
                buffer.append(ref)

            else:
                # Text
                # Collect text until <, &, or end
                start = idx
                while idx < length and s[idx] not in '<&':
                    idx += 1
                text = s[start:idx]
                if text:
                    buffer.append(text)

        # Flush remaining buffer
        if buffer:
            children.append("".join(buffer))

        return children

    # Main parsing
    skip_whitespace()
    if idx >= length:
        error("Empty input")

    root = parse_element()

    skip_whitespace()
    if idx < length:
        error("Text outside root element")

    return root

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    parser = _XMLParser(s)
    return parser.parse_document()

class _XMLParser:
    def __init__(self, s: str):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def error(self, msg=""):
        raise ValueError(f"Parse error at index {self.pos}: {msg}")

    def peek(self):
        if self.pos < self.n:
            return self.s[self.pos]
        return None

    def consume(self):
        if self.pos < self.n:
            char = self.s[self.pos]
            self.pos += 1
            return char
        self.error("Unexpected end of input")

    def expect(self, char):
        if self.peek() != char:
            self.error(f"Expected '{char}'")
        return self.consume()

    def match(self, char):
        if self.peek() == char:
            self.consume()
            return True
        return False

    def skip_whitespace(self):
        while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
            self.pos += 1

    def parse_document(self):
        self.skip_whitespace()
        if self.pos >= self.n:
            raise ValueError("Empty input")

        tag, attrs, children = self.parse_element()

        self.skip_whitespace()
        if self.pos < self.n:
            raise ValueError("Content after root element")

        return (tag, attrs, children)

    def parse_element(self):
        self.expect('<')
        tag = self.parse_name()

        attrs = {}
        # Parse attributes
        while self.pos < self.n:
            self.skip_whitespace()
            char = self.peek()

            if char == '>':
                self.consume()
                break # End of open tag
            elif char == '/':
                # Check for />
                if self.pos + 1 < self.n and self.s[self.pos+1] == '>':
                    self.consume() # /
                    self.consume() # >
                    return (tag, attrs, [])
                else:
                    self.error("Expected />")
            elif char is not None and (char.isalpha() or char == '_'):
                # Attribute
                name, value = self.parse_attribute()
                if name in attrs:
                    self.error(f"Duplicate attribute {name}")
                attrs[name] = value
            else:
                # Unexpected char
                if char is None:
                    self.error("Unexpected end of input in element tag")
                else:
                    self.error(f"Unexpected char '{char}'")

        # Parse content
        children = []
        current_text = []

        while self.pos < self.n:
            # Check for closing tag
            if self.peek() == '<':
                if self.s[self.pos:self.pos+2] == '</':
                    # Closing tag
                    if current_text:
                        children.append("".join(current_text))
                        current_text = []
                    self.parse_closing_tag(tag)
                    return (tag, attrs, children)
                else:
                    # Child element
                    if current_text:
                        children.append("".join(current_text))
                        current_text = []
                    child = self.parse_element()
                    children.append(child)
                    continue

            # Text or Reference
            # Scan for '&' or '<' (though '<' handled above, but safe to scan)
            # Actually, since we checked '<' above, we are here if peek() != '<'.
            # So we look for '&' or end of string.

            start = self.pos
            while self.pos < self.n:
                char = self.s[self.pos]
                if char == '<' or char == '&':
                    break
                self.pos += 1

            text_segment = self.s[start:self.pos]
            if text_segment:
                current_text.append(text_segment)

            if self.pos < self.n:
                char = self.s[self.pos]
                if char == '&':
                    decoded = self.parse_reference()
                    current_text.append(decoded)
                    # Continue loop to check for next tag or text
                elif char == '<':
                    # This is handled by the check at start of loop
                    pass
                else:
                    # End of string
                    raise ValueError("Unclosed element")
            else:
                raise ValueError("Unclosed element")

    def parse_name(self):
        if self.pos >= self.n:
            self.error("Expected name")
        char = self.s[self.pos]
        if not (char.isalpha() or char == '_'):
            self.error(f"Invalid name start: '{char}'")

        start = self.pos
        self.pos += 1
        while self.pos < self.n:
            char = self.s[self.pos]
            if char.isalnum() or char in '_-.':
                self.pos += 1
            else:
                break
        return self.s[start:self.pos]

    def parse_attribute(self):
        name = self.parse_name()
        self.skip_whitespace()
        self.expect('=')
        self.skip_whitespace()
        value = self.parse_value()
        return (name, value)

    def parse_value(self):
        quote = self.consume()
        if quote not in ('"', "'"):
            self.error("Expected quote")

        parts = []
        while self.pos < self.n:
            char = self.s[self.pos]
            if char == quote:
                self.consume()
                break
            if char == '<':
                self.error("Attribute value cannot contain '<'")
            if char == '&':
                # Parse reference
                # But wait, if we parse reference, we consume chars.
                # We need to be careful not to consume the closing quote if it's part of a reference?
                # References end with ';'. Quote is distinct.
                # However, we must ensure we don't consume the quote if it's not part of reference?
                # Actually, references are well defined.
                # But we need to make sure we don't consume the quote if it's just a quote.
                # But quote check is at start of loop.
                # If we are inside reference parsing, we consume until ';'.
                # So quote is safe.

                # But wait, what if reference contains quote? e.g. &quot;
                # That expands to ".
                # So we are safe.

                # However, we need to parse reference without consuming the quote if it's not part of it.
                # But reference always ends with ';'.
                # So we can just parse it.

                # But we need to save position? No, reference parsing consumes.
                # But we need to check if we consumed the quote?
                # No, reference parsing stops at ';'.

                # Wait, if I call parse_reference, it consumes '&', name/digits, ';'.
                # It does not consume quote.
                # So it's safe.

                # But wait, parse_reference expects '&' to be at current pos.
                # I am at '&'.
                # So I can call it.

                # But I need to handle the case where '&' is not a reference?
                # parse_reference will raise error if not valid.

                # So:
                decoded = self.parse_reference()
                parts.append(decoded)
            else:
                parts.append(char)
                self.pos += 1

        return "".join(parts)

    def parse_reference(self):
        if not self.match('&'):
            self.error("Expected '&'")

        if self.peek() == '#':
            self.consume() # #
            if self.peek() in ('x', 'X'):
                # Hex
                self.consume() # x
                hex_digits = []
                while self.pos < self.n and self.s[self.pos] in '0123456789abcdefABCDEF':
                    hex_digits.append(self.s[self.pos])
                    self.pos += 1
                if not hex_digits:
                    self.error("Empty hex digits in reference")
                if not self.match(';'):
                    self.error("Missing ';' in reference")
                val = int("".join(hex_digits), 16)
            else:
                # Decimal
                digits = []
                while self.pos < self.n and self.s[self.pos].isdigit():
                    digits.append(self.s[self.pos])
                    self.pos += 1
                if not digits:
                    self.error("Empty decimal digits in reference")
                if not self.match(';'):
                    self.error("Missing ';' in reference")
                val = int("".join(digits))
        else:
            # Named entity
            start = self.pos
            while self.pos < self.n and self.s[self.pos] not in ';':
                self.pos += 1
            name = self.s[start:self.pos]
            if not self.match(';'):
                self.error("Missing ';' in reference")

            if name == 'lt':
                val = ord('<')
            elif name == 'gt':
                val = ord('>')
            elif name == 'amp':
                val = ord('&')
            elif name == 'quot':
                val = ord('"')
            elif name == 'apos':
                val = ord("'")
            else:
                self.error(f"Unknown entity &{name};")

        # Validate code point
        if val < 1 or val > 0x10FFFF:
            self.error(f"Invalid code point {val}")
        if 0xD800 <= val <= 0xDFFF:
            self.error(f"Surrogate code point {val}")

        return chr(val)

    def parse_closing_tag(self, expected_tag):
        self.expect('</')
        tag = self.parse_name()
        self.skip_whitespace()
        self.expect('>')
        if tag != expected_tag:
            self.error(f"Tag mismatch: expected </{expected_tag}> but found </{tag}>")

def parse_xml(s: str):
    if not s:
        raise ValueError("Empty input")

    pos = 0
    n = len(s)
    WS = set(' \t\n\r')

    def peek(offset=0):
        idx = pos + offset
        return s[idx] if idx < n else None

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in WS:
            pos += 1

    def parse_name():
        nonlocal pos
        if pos >= n or not (s[pos].isalpha() or s[pos] == '_'):
            raise ValueError("Invalid name start")
        start = pos
        pos += 1
        while pos < n and (s[pos].isalnum() or s[pos] in '_-.'):
            pos += 1
        return s[start:pos]

    def parse_attr():
        nonlocal pos
        name = parse_name()
        skip_ws()
        if peek() != '=':
            raise ValueError("Expected '=' in attribute")
        pos += 1
        skip_ws()
        quote = peek()
        if quote not in ('"', "'"):
            raise ValueError("Expected quote for attribute value")
        pos += 1
        value_chars = []
        while pos < n and s[pos] != quote:
            if s[pos] == '<':
                raise ValueError("'<' not allowed in attribute value")
            if s[pos] == '&':
                val, _ = parse_ref()
                value_chars.append(val)
            else:
                value_chars.append(s[pos])
                pos += 1
        if pos >= n:
            raise ValueError("Unterminated attribute value")
        pos += 1
        return name, ''.join(value_chars)

    def parse_ref():
        nonlocal pos
        if peek() != '&':
            raise ValueError("Expected '&'")
        pos += 1
        start = pos
        if peek() == '#':
            pos += 1
            radix = 10
            if peek() == 'x':
                radix = 16
                pos += 1
            if pos >= n or s[pos] == ';':
                raise ValueError("Numeric reference must have at least one digit")
            while pos < n and (s[pos].isalnum() if radix == 10 else s[pos] in '0123456789abcdefABCDEF'):
                pos += 1
            if pos >= n or s[pos] != ';':
                raise ValueError("Missing ';' or invalid character in reference")
            num_str = s[start+1:pos-1]
            try:
                cp = int(num_str, radix)
            except ValueError:
                raise ValueError("Invalid numeric reference")
            if cp < 1 or cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                raise ValueError("Invalid code point in reference")
            return chr(cp), pos - start
        else:
            while pos < n and s[pos] != ';':
                pos += 1
            if pos >= n:
                raise ValueError("Missing ';' in reference")
            name = s[start:pos]
            pos += 1
            refs = {'lt': '<', 'gt': '>', 'amp': '&', 'quot': '"', 'apos': "'"}
            if name not in refs:
                raise ValueError(f"Unknown entity: &{name};")
            return refs[name], pos - start

    def parse_element():
        nonlocal pos
        if peek() != '<':
            raise ValueError("Expected '<' for element")
        pos += 1
        tag = parse_name()
        attrs = {}
        first_attr = True
        while pos < n and s[pos] not in ('/', '>'):
            if not first_attr:
                if pos >= n or s[pos] not in WS:
                    raise ValueError("Attributes must be separated by whitespace")
            skip_ws()
            if pos >= n or s[pos] in ('/', '>'):
                break
            a_name, a_val = parse_attr()
            if a_name in attrs:
                raise ValueError(f"Duplicate attribute: {a_name}")
            attrs[a_name] = a_val
            first_attr = False
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of input in element")
        if s[pos] == '/':
            pos += 1
            if peek() != '>':
                raise ValueError("Expected '>' after '/>'")
            pos += 1
            return tag, attrs, []
        elif s[pos] == '>':
            pos += 1
            children = []
            text_buf = []
            while pos < n:
                if peek() == '<':
                    if text_buf:
                        children.append(''.join(text_buf))
                        text_buf = []
                    if pos + 1 < n and s[pos+1] == '/':
                        pos += 2
                        close_tag = parse_name()
                        skip_ws()
                        if peek() != '>':
                            raise ValueError("Expected '>' in closing tag")
                        pos += 1
                        if close_tag != tag:
                            raise ValueError(f"Tag mismatch: {tag} vs {close_tag}")
                        break
                    else:
                        child = parse_element()
                        children.append(child)
                elif peek() == '&':
                    val, _ = parse_ref()
                    text_buf.append(val)
                else:
                    start = pos
                    while pos < n and s[pos] not in ('<', '&'):
                        pos += 1
                    text_buf.append(s[start:pos])
            if text_buf:
                children.append(''.join(text_buf))
            return tag, attrs, children
        else:
            raise ValueError("Expected '>' or '/>'")

    skip_ws()
    if pos >= n:
        raise ValueError("Empty input or only whitespace")

    tag, attrs, children = parse_element()

    skip_ws()
    if pos < n:
        raise ValueError("Text or elements outside root")

    return tag, attrs, children

