        result_parts = []

        while self.pos < self.n:
            c = self.s[self.pos]
            if c == quote:
                break
            if c == '<':
                self.error("Invalid character '<' in attribute value")
            if c == '&':
                ref_text = self.parse_reference()
                result_parts.append(ref_text)
                continue

            # Text char
            text_start = self.pos
            while self.pos < self.n and self.s[self.pos] not in (quote, '<', '&'):
                self.pos += 1
            result_parts.append(self.s[text_start:self.pos])

