            self.error("Unterminated attribute value")

        self.advance()
        return "".join(result_parts)

    def parse_content(self, root_tag):
        children = []
        current_text = []

        while True:
            if self.pos >= self.n:
                self.error("Unclosed element")

            c = self.peek()

            if c == '<':
                if self.match('</'):
                    close_tag = self.parse_name()
                    self.skip_whitespace()
                    if not self.match('>'):
                        self.error("Expected '>' in closing tag")
                    if close_tag != root_tag:
                        self.error(f"Mismatched tags: {root_tag} vs {close_tag}")
                    if current_text:
                        children.append("".join(current_text))
                    return children
                else:
                    if current_text:
                        children.append("".join(current_text))
                        current_text = []
                    tag, attrs, child_children = self.parse_element()
                    children.append((tag, attrs, child_children))

            elif c == '&':
                ref_char = self.parse_reference()
                current_text.append(ref_char)

            else:
                text_start = self.pos
                while self.pos < self.n and self.s[self.pos] not in ('<', '&'):
                    self.pos += 1
                text_chunk = self.s[text_start:self.pos]
                if text_chunk:
