                child_element = parse_element()
                children.append(child_element)

            elif char == '&':
                ref = parse_reference()
                current_text.append(ref)
            else:
                current_text.append(char)
                pos += 1

        # End of content (either end tag or end of string? No, end tag required)
        if current_text:
            text = "".join(current_text)
            if text:
                children.append(text)

        return children

    def parse_element():
        nonlocal pos
        match_expected('<')
        tag_name = parse_name()
        attrs = parse_attributes()

        # Check if empty element
        if peek() == '/':
            match_expected('/>')
            return (tag_name, attrs, [])
        else:
            match_expected('>')
            children = parse_content()

            # Expect end tag
            if pos >= n or s[pos] != '<':
                raise ValueError("Expected closing tag")
            if pos + 1 >= n or s[pos+1] != '/':
                raise ValueError("Expected closing tag")

            pos += 2 # consume '</'
            end_name = parse_name()
            skip_whitespace()
            if pos >= n or s[pos] != '>':
                raise ValueError("Expected '>' at end of closing tag")
            pos += 1 # consume '>'

            if end_name != tag_name:
                raise ValueError(f"Mismatched tags: '{tag_name}' and '{end_name}'")

            return (tag_name, attrs, children)

    # Parse Document
    skip_whitespace()
    if pos >= n:
        raise ValueError("Empty input or only whitespace")

    root = parse_element()

    skip_whitespace()
    if pos < n:
        raise ValueError("Text or element outside root")

    return root

