    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    # Internal parser class
    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def error(self, msg=""):
            raise ValueError(f"XML parse error at pos {self.pos}: {msg}")

        def peek(self):
            if self.pos < self.n:
                return self.s[self.pos]
            return None

        def advance(self):
            if self.pos < self.n:
                char = self.s[self.pos]
                self.pos += 1
                return char
            return None

        def match(self, char):
            if self.peek() == char:
                self.advance()
                return True
            return False

