            if self.pos >= self.n:
                self.error("Unexpected end of input, expected name")
            c = self.s[self.pos]
            if not (c.isalpha() or c == '_'):
                self.error(f"Invalid name start character '{c}'")
            self.pos += 1
            name = c
            while self.pos < self.n:
                c = self.s[self.pos]
                if c.isalnum() or c in '_-.':
                    name += c
                    self.pos += 1
                else:
                    break
            return name

        def parse_reference(self):
            # Current char is '&'
            if self.pos + 1 >= self.n:
                self.error("Unexpected end of input in reference")

            next_char = self.s[self.pos+1]

            if next_char == '#':
                # Numeric reference
                if self.pos + 2 >= self.n:
                    self.error("Unexpected end of input in numeric reference")

                type_char = self.s[self.pos+2]
                self.pos += 3 # skip &#

