                if type_char == 'x':
                    is_hex = True
                elif type_char == 'X':
                    self.error("Hex reference must use lowercase 'x'")
                elif type_char.isdigit():
                    is_hex = False
                else:
                    self.error(f"Invalid numeric reference start '{type_char}'")

                digits = []
                while self.pos < self.n:
                    c = self.s[self.pos]
                    if is_hex:
                        if c in '0123456789abcdefABCDEF':
                            digits.append(c)
                            self.pos += 1
                        else:
                            break
                    else:
                        if c.isdigit():
                            digits.append(c)
                            self.pos += 1
                        else:
                            break

                if not digits:
                    self.error("Numeric reference must have at least one digit")

                if self.pos >= self.n or self.s[self.pos] != ';':
                    self.error("Expected ';' in reference")
                self.pos += 1 # skip ;

                val_str = "".join(digits)
                try:
                    if is_hex:
                        code_point = int(val_str, 16)
                    else:
                        code_point = int(val_str, 10)
                except ValueError:
                    self.error("Invalid numeric value")

                # Validation
                if code_point == 0:
                    self.error("Null character not allowed")
                if code_point > 0x10FFFF:
                    self.error("Code point out of range")
                if 0xD800 <= code_point <= 0xDFFF:
                    self.error("Surrogate code point not allowed")

                return chr(code_point)

            else:
                # Named reference
                start = self.pos + 1
                while self.pos < self.n and self.s[self.pos] != ';':
                    c = self.s[self.pos]
