        def parse_attribute_value(self):
            # Expects to be at opening quote
            quote_char = self.s[self.pos]
            if quote_char not in ('"', "'"):
                self.error("Expected quote for attribute value")
            self.pos += 1

            value_chars = []
            while self.pos < self.n:
                c = self.s[self.pos]
                if c == quote_char:
                    self.pos += 1
                    break
                if c == '<':
                    self.error("Attribute value cannot contain '<'")
                if c == '&':
                    value_chars.append(self.parse_reference())
                else:
                    value_chars.append(c)
                    self.pos += 1

            return "".join(value_chars)

        def parse_element(self):
            # Expects to be at '<'
            if not self.match('<'):
                self.error("Expected '<'")

            tag = self.parse_name()

            attrs = {}
            while self.pos < self.n:
                self.skip_whitespace()
                if self.pos >= self.n:
                    self.error("Unexpected end of input in element start")

                if self.s[self.pos] == '>':
                    self.pos += 1
                    break
                if self.s[self.pos] == '/':
                    if self.pos + 1 < self.n and self.s[self.pos+1] == '>':
                        self.pos += 2
                        return (tag, attrs, [])
                    else:
                        self.error("Expected '>' or '/>'")

                # Parse Attribute
                attr_name = self.parse_name()
                if attr_name in attrs:
                    self.error(f"Duplicate attribute '{attr_name}'")

                self.skip_whitespace()
                if not self.match('='):
                    self.error("Expected '='")
                self.skip_whitespace()

                attr_val = self.parse_attribute_value()
                attrs[attr_name] = attr_val

            # Parse Content
            children = self.parse_content(tag)

            # Parse Closing Tag
            self.skip_whitespace()
            if not self.match('</'):
                self.error("Expected '</'")

            end_tag = self.parse_name()
            if end_tag != tag:
                self.error(f"Mismatched tags: '{tag}' and '{end_tag}'")

            self.skip_whitespace()
            if not self.match('>'):
                self.error("Expected '>'")

            return (tag, attrs, children)

        def parse_content(self, tag):
            children = []
            current_text = ""

            while self.pos < self.n:
                if self.peek() == '<':
                    # Check for closing tag
                    if self.pos + 1 < self.n and self.s[self.pos+1] == '/':
                        # It must be a closing tag
                        # Parse it strictly
                        self.match('<') # consume <
                        self.match('/') # consume /
                        end_tag = self.parse_name()
                        if end_tag != tag:
                            self.error(f"Mismatched tags: '{tag}' and '{end_tag}'")
                        self.skip_whitespace()
                        if not self.match('>'):
                            self.error("Expected '>'")

                        if current_text:
                            children.append(current_text)
                            current_text = ""
                        return children
                    else:
                        # It's a start tag
                        if current_text:
                            children.append(current_text)
                            current_text = ""
                        child_elem = self.parse_element()
                        children.append(child_elem)

                elif self.peek() == '&':
                    ref_str = self.parse_reference()
                    current_text += ref_str

                else:
                    # Text character
                    # Collect all text chars until < or &
                    start = self.pos
                    while self.pos < self.n:
                        c = self.s[self.pos]
                        if c == '<' or c == '&':
                            break
                        self.pos += 1
                    current_text += self.s[start:self.pos]

            # If we exit loop, we didn't find closing tag
            self.error(f"Unclosed tag '{tag}'")
            return []

        def parse_document(self):
            if not self.s:
                self.error("Empty input")

            self.skip_whitespace()
            if self.pos >= self.n:
                self.error("Empty input (only whitespace)")

            # Parse exactly one element
            root = self.parse_element()

            # Check for more content
            self.skip_whitespace()
            if self.pos < self.n:
                self.error("Content after root element")

            return root

    parser = Parser(s)
    return parser.parse_document()

def parse_xml(s: str):
    if not s:
        raise ValueError("Empty input")

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def peek(self):
            return self.s[self.pos] if self.pos < self.n else None

        def advance(self):
            self.pos += 1

        def expect(self, char):
            if self.pos >= self.n or self.s[self.pos] != char:
                raise ValueError(f"Expected '{char}' at pos {self.pos}")
            self.advance()

        def skip_ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.advance()

        def parse_name(self):
            if self.pos >= self.n or not (self.s[self.pos].isalpha() or self.s[self.pos] == '_'):
                raise ValueError("Invalid name start")
            start = self.pos
            self.advance()
            while self.pos < self.n and (self.s[self.pos].isalnum() or self.s[self.pos] in '_.-'):
                self.advance()
            return self.s[start:self.pos]

        def parse_reference(self):
            if self.pos + 2 < self.n and self.s[self.pos:self.pos+3] == 'lt;':
                self.pos += 3
                return '<'
            if self.pos + 2 < self.n and self.s[self.pos:self.pos+3] == 'gt;':
                self.pos += 3
                return '>'
            if self.pos + 3 < self.n and self.s[self.pos:self.pos+4] == 'amp;':
                self.pos += 4
                return '&'
            if self.pos + 4 < self.n and self.s[self.pos:self.pos+5] == 'quot;':
                self.pos += 5
                return '"'
            if self.pos + 4 < self.n and self.s[self.pos:self.pos+5] == 'apos;':
                self.pos += 5
                return "'"

            if self.pos < self.n and self.s[self.pos] == '#':
                self.advance()
                is_hex = False
                if self.pos < self.n and self.s[self.pos] == 'x':
                    is_hex = True
                    self.advance()
                start_digit = self.pos
                while self.pos < self.n and self.s[self.pos].isdigit():
                    self.advance()
                if start_digit == self.pos:
                    raise ValueError("No digits in reference")
                if self.pos >= self.n or self.s[self.pos] != ';':
                    raise ValueError("Missing ; in reference")
                self.advance()
                num_str = self.s[start_digit:self.pos-1]
                try:
                    code = int(num_str, 16 if is_hex else 10)
                except ValueError:
                    raise ValueError("Invalid reference digits")
                if code == 0 or code > 0x10FFFF:
                    raise ValueError("Code point out of range")
                if 0xD800 <= code <= 0xDFFF:
                    raise ValueError("Surrogate code point")
                return chr(code)
            raise ValueError("Unknown entity")

        def parse_value(self):
            if self.pos >= self.n:
                raise ValueError("Expected value")
            q = self.s[self.pos]
            if q not in ('"', "'"):
                raise ValueError("Unquoted value")
            self.advance()
            parts = []
            while self.pos < self.n:
                c = self.s[self.pos]
                if c == q:
                    self.advance()
                    break
                if c == '<':
                    raise ValueError("'<' in attribute value")
                if c == '&':
                    self.advance()
                    parts.append(self.parse_reference())
                else:
                    parts.append(c)
                    self.advance()
            if self.pos >= self.n:
                raise ValueError("Unterminated attribute value")
            return ''.join(parts)

        def parse_attributes(self):
            attrs = {}
            while self.pos < self.n:
                self.skip_ws()
                if self.pos < self.n and (self.s[self.pos] == '>' or (self.pos + 1 < self.n and self.s[self.pos:self.pos+2] == '/>')):
                    break
                if self.pos > 0 and self.s[self.pos-1] not in ' \t\n\r':
                    raise ValueError("Attributes must be separated by whitespace")
                attr_name = self.parse_name()
                self.skip_ws()
                self.expect('=')
                self.skip_ws()
                attr_val = self.parse_value()
                if attr_name in attrs:
                    raise ValueError("Duplicate attribute")
                attrs[attr_name] = attr_val
            return attrs

        def parse_content(self, parent_tag):
            children = []
            text_buf = []
            while self.pos < self.n:
                if self.s[self.pos] == '<':
                    text = ''.join(text_buf)
                    if text:
                        children.append(text)
                    text_buf = []

                    if self.s[self.pos:self.pos+2] == '</':
                        temp = self.pos + 2
                        if temp >= self.n or not (self.s[temp].isalpha() or self.s[temp] == '_'):
                            raise ValueError("Invalid closing tag")
                        start = temp
                        temp += 1
                        while temp < self.n and (self.s[temp].isalnum() or self.s[temp] in '_.-'):
                            temp += 1
                        if self.s[start:temp] != parent_tag:
                            raise ValueError("Mismatched closing tag")
                        while temp < self.n and self.s[temp] in ' \t\n\r':
                            temp += 1
                        if temp >= self.n or self.s[temp] != '>':
                            raise ValueError("Invalid closing tag")
                        self.pos = temp + 1
                        break
                    else:
                        child_tag, child_attrs, child_children = self.parse_element()
                        children.append((child_tag, child_attrs, child_children))
                elif self.s[self.pos] == '&':
                    self.advance()
                    text_buf.append(self.parse_reference())
                else:
                    self.advance()
                    text_buf.append(self.s[self.pos-1])

            text = ''.join(text_buf)
            if text:
                children.append(text)
            return children

        def parse_element(self):
            self.expect('<')
            tag = self.parse_name()
            attrs = self.parse_attributes()

            self.skip_ws()
            if self.pos < self.n and self.s[self.pos:self.pos+2] == '/>':
                self.pos += 2
                return (tag, attrs, [])
            elif self.pos < self.n and self.s[self.pos] == '>':
                self.advance()
                children = self.parse_content(tag)
                return (tag, attrs, children)
            else:
                raise ValueError("Expected '/>' or '>'")

    p = Parser(s)
    p.skip_ws()
    if p.pos >= p.n:
        raise ValueError("Empty input")
    tag, attrs, children = p.parse_element()
    p.skip_ws()
    if p.pos < p.n:
        raise ValueError("Content after root")
    return (tag, attrs, children)

