                # Next char is `b` (letter).
                # It's not `>` or `/`.
                # So we proceed to parse attribute.
                # This violates "preceded by whitespace".
                # We need to detect if whitespace was present.

                # Let's restructure:
                # We are at pos. We expect either end-of-attrs or whitespace then attr.
                # If next char is not whitespace, it must be end-of-attrs?
                # No, if next char is letter, it's an error (missing whitespace).

                # Check if next char is whitespace
                if self.peek() not in ' \t\n\r':
                    # Not whitespace. Must be end of tag?
                    if self.peek() in '>':
                        break
                    if self.peek() == '/' and self.peek(1) == '>':
                        break
                    # If it's a letter/underscore, it's an attribute name without whitespace -> Error
                    if self.peek().isalpha() or self.peek() == '_':
                        raise ValueError(f"Attribute '{self.peek()}' not preceded by whitespace")
                    else:
                        raise ValueError(f"Unexpected character '{self.peek()}' in attributes")

                # Consume whitespace
                self.skip_whitespace()

                # Parse Attribute Name
                attr_name = self.parse_name()

                # Check '='
                self.skip_whitespace()
                self.expect('=')
                self.skip_whitespace()

                # Parse Value
                attr_value = self.parse_quoted_value()

                if attr_name in attrs:
                    raise ValueError(f"Duplicate attribute '{attr_name}'")

                attrs[attr_name] = attr_value

            return attrs

        def parse_element(self) -> tuple:
            self.expect('<')
            tag = self.parse_name()

            attrs = self.parse_attributes()

            self.skip_whitespace()

            # Check for empty element />
            if self.peek() == '/' and self.peek(1) == '>':
                self.advance(2)
                return (tag, attrs, [])

            # Check for >
            if self.peek() == '>':
                self.advance()
                # Parse content
                children = self.parse_content(tag)

                # Expect closing tag </tag>
                self.expect('</')
                end_tag = self.parse_name()
                if end_tag != tag:
                    raise ValueError(f"Mismatched tags: expected '{tag}', found '{end_tag}'")

                self.skip_whitespace()
                self.expect('>')

                return (tag, attrs, children)
            else:
                raise ValueError(f"Expected '>' or '/>' after attributes, got '{self.peek()}'")

        def parse_content(self, parent_tag: str) -> list:
            children = []
            text_buf = []

            while self.pos < self.n:
                c = self.peek()

                # Check for end tag
                if c == '<' and self.peek(1) == '/':
                    # It is an end tag
                    self.advance(2) # skip </
                    end_tag = self.parse_name()
                    self.skip_whitespace()
                    self.expect('>')

                    if end_tag != parent_tag:
                        raise ValueError(f"Mismatched tags: expected '{parent_tag}', found '{end_tag}'")

                    # End of content reached
                    break

                # Check for child element
                elif c == '<':
                    # Flush text buffer
                    if text_buf:
                        children.append("".join(text_buf))
                        text_buf = []

                    child_elem = self.parse_element()
                    children.append(child_elem)

                # Check for reference
                elif c == '&':
                    char = self.parse_reference()
                    text_buf.append(char)

                # Text character
                else:
                    # Text chars are anything except '<' and '&'
                    # But we are in a loop checking specific chars.
                    # If we are here, it's a valid text char.
                    # We should scan forward to gather all consecutive text chars.
                    start = self.pos
                    while self.pos < self.n:
                        tc = self.s[self.pos]
                        if tc in '<&':
                            break
                        self.pos += 1
                    text_buf.append(self.s[start:self.pos])

            # Flush remaining text
            if text_buf:
                children.append("".join(text_buf))

            return children

    # Main parsing logic
    if not s:
        raise ValueError("Empty input")

    parser = Parser(s)
    parser.skip_whitespace()

    if parser.pos >= parser.n:
        raise ValueError("No root element found")

    # Parse root element
    root = parser.parse_element()

    # Check for trailing content (must be only whitespace)
    parser.skip_whitespace()
    if parser.pos < parser.n:
        raise ValueError(f"Unexpected content after root element: '{s[parser.pos:]}'")

    return root

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    Raises ValueError on invalid input.
    """
    if not s:
        raise ValueError("Empty input")

    # Parser state
    pos = [0]
    n = len(s)

    def peek(offset=0):
        idx = pos[0] + offset
        if 0 <= idx < n:
            return s[idx]
        return None

    def advance(count=1):
        pos[0] += count
        if pos[0] > n:
            raise ValueError("Unexpected end of input")

    def expect(char):
        if peek() != char:
            raise ValueError(f"Expected '{char}' at pos {pos[0]}, found '{peek()}'")
        advance()

    def is_ws(c):
        return c in (' ', '\t', '\n', '\r')

    def skip_ws():
        while peek() is not None and is_ws(peek()):
            advance()

    def read_name():
        if peek() is None:
            raise ValueError("Unexpected end of input, expected name")
        c = peek()
        if not (c.isalpha() or c == '_'):
            raise ValueError(f"Invalid start of name: '{c}'")
        advance()
        name = c
        while peek() is not None:
            c = peek()
            if c.isalnum() or c in ('_', '-', '.'):
                name += c
                advance()
            else:
                break
        return name

    def parse_value():
        quote = peek()
        if quote not in ('"', "'"):
            raise ValueError(f"Expected quote for value, found '{quote}'")
        advance()

        val_chars = []
        while True:
            c = peek()
            if c is None:
                raise ValueError("Unexpected end of input in value")
            if c == quote:
                advance()
                break
            if c == '<':
                raise ValueError("'< ' not allowed in attribute value")
            if c == '&':
                ref_char = parse_ref()
                val_chars.append(ref_char)
            else:
                val_chars.append(c)
                advance()
        return "".join(val_chars)

    def parse_ref():
        if peek() != '&':
            raise ValueError("Expected & for reference")
        advance()

        c = peek()
        if c == '#':
            advance()
            c = peek()
            if c == 'x':
                advance()
                digits = []
                while True:
                    d = peek()
                    if d is None or d == ';':
                        break
                    if d in '0123456789abcdefABCDEF':
                        digits.append(d)
                        advance()
                    else:
                        raise ValueError(f"Invalid hex digit '{d}' in reference")
                if not digits:
                    raise ValueError("Hex reference must have at least one digit")
                expect(';')
                val = int("".join(digits), 16)
            elif c is not None and c in '0123456789':
                digits = []
                while True:
                    d = peek()
                    if d is None or d == ';':
                        break
                    if d in '0123456789':
                        digits.append(d)
                        advance()
                    else:
                        raise ValueError(f"Invalid decimal digit '{d}' in reference")
                if not digits:
                    raise ValueError("Decimal reference must have at least one digit")
                expect(';')
                val = int("".join(digits), 10)
            else:
                raise ValueError("Expected digit after &#")
        else:
            name_chars = []
            while True:
                d = peek()
                if d is None or d == ';':
                    break
                if d.isalnum() or d == '_':
                    name_chars.append(d)
                    advance()
                else:
                    raise ValueError(f"Unexpected char '{d}' in reference name")

            if not name_chars:
                raise ValueError("Empty reference name")

            ref_name = "".join(name_chars)
            expect(';')

            if ref_name == 'lt':
                val = '<'
            elif ref_name == 'gt':
                val = '>'
            elif ref_name == 'amp':
                val = '&'
            elif ref_name == 'quot':
                val = '"'
            elif ref_name == 'apos':
                val = "'"
            else:
                raise ValueError(f"Unknown entity '{ref_name}'")

        if val < 1 or val > 0x10FFFF:
            raise ValueError(f"Code point {val} out of range")
        if 0xD800 <= val <= 0xDFFF:
            raise ValueError(f"Surrogate code point {val}")

        return chr(val)

    def parse_attr():
        name = read_name()
        skip_ws()
        expect('=')
        skip_ws()
        value = parse_value()
        return name, value

    def parse_element():
        expect('<')
        tag = read_name()

        attrs = {}
        while True:
            c = peek()
            if c is None:
                raise ValueError("Unexpected end of input in element start tag")

            if c == '>':
                break
            if c == '/':
                if peek(1) == '>':
                    break
                else:
                    raise ValueError("Invalid character '/' in tag start")

            # Check if there is whitespace before attribute?
            # Grammar: "attributes each preceded by at least one whitespace character"
            # If we are here, c is not > or /.
            # It must be whitespace or start of attribute name.
            # But if it's not whitespace, it's an error (unless it's a name start, but we need ws before it).
            # Actually, if c is not whitespace, it implies no whitespace before this attribute.
            # However, the first attribute is preceded by whitespace after <tag.
            # If we are at the start of attributes, and c is not whitespace, it means <tagattr...
            # But read_name would have consumed 'tagattr' as the tag name?
            # No, read_name stops at non-name char.
            # If input is <tag attr...>, read_name consumes 'tag', stops at space.
            # So c is space.
            # If input is <tagattr...>, read_name consumes 'tagattr', stops at '='.
            # c is '='.
            # So if c is not whitespace, and not > or /, it's an error.
            if not is_ws(c):
                raise ValueError("Attribute must be preceded by whitespace")

            skip_ws()

            # After skipping ws, check if we hit > or /
            c = peek()
            if c == '>':
                break
            if c == '/':
                if peek(1) == '>':
                    break
                else:
                    raise ValueError("Invalid /")

            # Now parse attribute
            attr_name, attr_val = parse_attr()
            if attr_name in attrs:
                raise ValueError(f"Duplicate attribute '{attr_name}'")
            attrs[attr_name] = attr_val

        # Check for empty element or content
        c = peek()
        if c == '/':
            expect('/')
            expect('>')
            return (tag, attrs, [])
        else:
            expect('>')
            children = parse_content()
            expect('</')
            end_tag = read_name()
            if end_tag != tag:
                raise ValueError(f"Mismatched tags: <{tag}> and </{end_tag}>")
            skip_ws()
            expect('>')
            return (tag, attrs, children)

    def parse_content():
        children = []
        current_text = []

        while True:
            c = peek()

            if c is None:
                raise ValueError("Unexpected end of input in content")

            if c == '<':
                # Check for closing tag
                if peek(1) == '/':
                    break

                # Check for invalid tags
                next_c = peek(1)
                if next_c == '!':
                    raise ValueError("Comments, CDATA, DOCTYPE not allowed")
                if next_c == '?':
                    raise ValueError("Processing instructions not allowed")

                # Check if valid name start
                if next_c is None or not (next_c.isalpha() or next_c == '_'):
                    raise ValueError("Invalid start of tag")

                # Flush text
                if current_text:
                    text_str = "".join(current_text)
                    if text_str:
                        children.append(text_str)
                    current_text = []

                child = parse_element()
                children.append(child)

            elif c == '&':
                # Flush text
                if current_text:
                    text_str = "".join(current_text)
                    if text_str:
                        children.append(text_str)
                    current_text = []

                ref_char = parse_ref()
                current_text.append(ref_char)

            else:
                # Text character
                # Find next < or &
                next_special = -1
                for i in range(pos[0], n):
                    ch = s[i]
                    if ch == '<' or ch == '&':
                        next_special = i
                        break

                if next_special == -1:
                    text_chunk = s[pos[0]:]
                    pos[0] = n
                    current_text.append(text_chunk)
                else:
                    text_chunk = s[pos[0]:next_special]
                    pos[0] = next_special
                    current_text.append(text_chunk)

        # Flush remaining text
        if current_text:
            text_str = "".join(current_text)
            if text_str:
                children.append(text_str)

        return children

    # Main parsing logic
    skip_ws()

    if peek() is None:
        raise ValueError("Document must contain exactly one element")

    root = parse_element()

    skip_ws()

    if peek() is not None:
        raise ValueError("Content after root element")

    return root

def parse_xml(s: str) -> tuple:
    class _Parser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def _skip_ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

        def _parse_name(self) -> str:
            if self.pos >= self.n or not (self.s[self.pos].isalpha() or self.s[self.pos] == '_'):
                raise ValueError("Invalid name start")
            start = self.pos
            self.pos += 1
            while self.pos < self.n and (self.s[self.pos].isalnum() or self.s[self.pos] in '._-'):
                self.pos += 1
            return self.s[start:self.pos]

        def _parse_reference(self) -> str:
            if self.pos >= self.n or self.s[self.pos] != '&':
                raise ValueError("Expected '&'")
            self.pos += 1
            if self.pos >= self.n:
                raise ValueError("Unterminated reference")

            if self.s[self.pos] == '#':
                self.pos += 1
                is_hex = False
                if self.pos < self.n and self.s[self.pos] == 'x':
                    is_hex = True
                    self.pos += 1
                start = self.pos
                count = 0
                while self.pos < self.n:
                    c = self.s[self.pos]
                    if is_hex:
                        if c in '0123456789abcdefABCDEF':
                            self.pos += 1
                            count += 1
                        else:
                            break
                    else:
                        if c in '0123456789':
                            self.pos += 1
                            count += 1
                        else:
                            break
                if count == 0:
                    raise ValueError("Reference must have at least one digit")
                num_str = self.s[start:self.pos]
                if self.pos >= self.n or self.s[self.pos] != ';':
                    raise ValueError("Missing ';' in reference")
                self.pos += 1
                if is_hex:
                    cp = int(num_str, 16)
                else:
                    cp = int(num_str)
                if cp < 1 or cp > 0x10FFFF or (0xD800 <= cp <= 0xDFFF):
                    raise ValueError("Invalid code point in reference")
                return chr(cp)
            else:
                start = self.pos
                while self.pos < self.n and self.s[self.pos] != ';':
                    if not (self.s[self.pos].isalnum() or self.s[self.pos] == '-'):
                        raise ValueError("Invalid named reference")
                    self.pos += 1
                if self.pos >= self.n or self.s[self.pos] != ';':
                    raise ValueError("Missing ';' in reference")
                name = self.s[start:self.pos]
                self.pos += 1
                refs = {'lt': '<', 'gt': '>', 'amp': '&', 'quot': '"', 'apos': "'"}
                if name not in refs:
                    raise ValueError(f"Unknown entity: &{name};")
                return refs[name]

        def _parse_attr_value(self, quote_char: str) -> str:
            self.pos += 1
            parts = []
            while self.pos < self.n:
                c = self.s[self.pos]
                if c == quote_char:
                    self.pos += 1
                    break
                if c == '<':
                    raise ValueError("Attribute value may not contain '<'")
                if c == '&':
                    parts.append(self._parse_reference())
                    continue
                parts.append(c)
                self.pos += 1
            else:
                raise ValueError("Unterminated attribute value")
            return ''.join(parts)

        def _parse_attributes(self, tag_name: str) -> dict:
            attrs = {}
            while self.pos < self.n:
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError("Unexpected end in attributes")
                if self.s[self.pos] == '>':
                    self.pos += 1
                    break
                if self.s[self.pos:self.pos+2] == '/>':
                    self.pos += 2
                    break
                if self.pos > 0 and self.s[self.pos-1] not in ' \t\n\r':
                    raise ValueError("Attributes must be preceded by whitespace")
                if self.s[self.pos:self.pos+2] in ('<!', '<?'):
                    raise ValueError("Comments, PIs, CDATA, or DOCTYPE not allowed")
                attr_name = self._parse_name()
                if attr_name in attrs:
                    raise ValueError(f"Duplicate attribute: {attr_name}")
                self._skip_ws()
                if self.pos >= self.n or self.s[self.pos] != '=':
                    raise ValueError("Expected '=' after attribute name")
                self.pos += 1
                self._skip_ws()
                if self.pos >= self.n or self.s[self.pos] not in ('"', "'"):
                    raise ValueError("Unquoted attribute value")
                quote = self.s[self.pos]
                attr_val = self._parse_attr_value(quote)
                attrs[attr_name] = attr_val
            return attrs

        def _parse_content(self, tag_name: str) -> list:
            children = []
            current_text = []

            def flush_text():
                if current_text:
                    text = ''.join(current_text)
                    if text:
                        if children and isinstance(children[-1], str):
                            children[-1] += text
                        else:
                            children.append(text)
                    current_text.clear()

            while self.pos < self.n:
                if self.s[self.pos] == '<':
                    flush_text()
                    if self.pos + 1 < self.n and self.s[self.pos+1] == '/':
                        self.pos += 2
                        self._skip_ws()
                        end_name = self._parse_name()
                        self._skip_ws()
                        if self.pos >= self.n or self.s[self.pos] != '>':
                            raise ValueError("Expected '>' after closing tag")
                        self.pos += 1
                        if end_name != tag_name:
                            raise ValueError(f"Mismatched tags: </{end_name}> vs </{tag_name}>")
                        break
                    elif self.pos + 1 < self.n and self.s[self.pos+1] in '!?':
                        raise ValueError("Comments, PIs, CDATA, or DOCTYPE not allowed")
                    else:
                        child = self._parse_element()
                        children.append(child)
                elif self.s[self.pos] == '&':
                    ref = self._parse_reference()
                    current_text.append(ref)
                else:
                    start = self.pos
                    while self.pos < self.n and self.s[self.pos] not in '<&':
                        self.pos += 1
                    text = self.s[start:self.pos]
                    current_text.append(text)

            flush_text()
            return children

        def _parse_element(self) -> tuple:
            if self.pos >= self.n or self.s[self.pos] != '<':
                raise ValueError("Expected '<'")
            self.pos += 1
            tag = self._parse_name()
            attrs = self._parse_attributes(tag)

            if self.pos < self.n and self.s[self.pos:self.pos+2] == '/>':
                self.pos += 2
                return (tag, attrs, [])

            if self.pos >= self.n or self.s[self.pos] != '>':
                raise ValueError("Expected '>' or '/>'")
            self.pos += 1

            children = self._parse_content(tag)
            return (tag, attrs, children)

        def parse_document(self) -> tuple:
            if not self.s:
                raise ValueError("Empty input")
            self._skip_ws()
            if self.pos >= self.n:
                raise ValueError("Empty input after whitespace")
            root = self._parse_element()
            self._skip_ws()
            if self.pos < self.n:
                raise ValueError("Text or element after root")
            return root

    return _Parser(s).parse_document()

import re

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    if not s:
        raise ValueError("Empty input")

    # State
    pos = 0
    length = len(s)
    s_bytes = s.encode('utf-8') # Not needed, but keeping in mind encoding is UTF-8 for chr()

    # Helpers
    def peek(offset=0):
        idx = pos + offset
        if idx >= length:
            return None
        return s[idx]

    def advance(n=1):
        nonlocal pos
        pos += n

    def match(expected):
        if peek() == expected:
            advance()
            return True
        return False

    def expect(expected, msg=None):
        if not match(expected):
            raise ValueError(msg or f"Expected '{expected}'")
        return True

    def error(msg):
        raise ValueError(msg)

    def skip_whitespace():
        nonlocal pos
        while pos < length and s[pos] in ' \t\n\r':
            pos += 1

    def is_name_start(c):
        return c.isascii() and (c.isalpha() or c == '_')

    def is_name_char(c):
        return c.isascii() and (c.isalnum() or c in '_.-')

    def parse_name():
        if pos >= length or not is_name_start(peek()):
            error("Invalid name start")
        start = pos
        pos += 1
        while pos < length and is_name_char(peek()):
            pos += 1
        return s[start:pos]

    def parse_reference():
        nonlocal pos
        # s[pos] is '&'
        if pos + 1 >= length:
            error("Unexpected end of string after &")

        if s[pos+1] == '#':
            # Numeric reference
            if pos + 2 >= length:
                error("Unexpected end of string after &#")

            if s[pos+2] == 'x':
                # Hex
                pos += 3 # skip &#x
                start = pos
                while pos < length and s[pos] in '0123456789abcdefABCDEF':
                    pos += 1
                if start == pos:
                    error("No hex digits")
                val_str = s[start:pos]
                if not match(';'):
                    error("Missing ;")
                try:
                    code = int(val_str, 16)
                except ValueError:
                    error("Invalid hex value")
            elif s[pos+2] == 'X':
                error("Hex digits must be lowercase 'x'")
            else:
                # Decimal
                pos += 2 # skip &#
                start = pos
                while pos < length and s[pos].isdigit():
                    pos += 1
                if start == pos:
                    error("No decimal digits")
                val_str = s[start:pos]
                if not match(';'):
                    error("Missing ;")
                try:
                    code = int(val_str, 10)
                except ValueError:
                    error("Invalid decimal value")

            # Validation
            if code < 1 or code > 0x10FFFF:
                error("Code point out of range")
            if 0xD800 <= code <= 0xDFFF:
                error("Surrogate code point")
            return chr(code)
        else:
            # Named reference
            start = pos + 1
            while pos < length and s[pos] != ';':
                pos += 1
            if pos >= length:
                error("Missing ;")
            name = s[start:pos]
            if not match(';'): 
                error("Missing ;")

            if name == 'lt': return '<'
            if name == 'gt': return '>'
            if name == 'amp': return '&'
            if name == 'quot': return '"'
            if name == 'apos': return "'"
            error(f"Unknown entity: &{name};")

    def parse_value():
        nonlocal pos
        quote = peek()
        if quote not in ('"', "'"):
            error("Unquoted attribute value")
        advance() # consume opening quote
        chars = []
        while pos < length:
            c = peek()
            if c == quote:
                break
            if c == '<':
                error("Attribute value contains '<'")
            if c == '&':
                val_char = parse_reference()
                chars.append(val_char)
            else:
                chars.append(c)
                advance()
        if pos >= length:
            error("Unterminated attribute value")
        advance() # consume closing quote
        return "".join(chars)

    def parse_content(parent_tag):
        children = []
        text_buffer = []

        while pos < length:
            c = peek()

            if c is None:
                error("Unexpected end of string in content")

            if c == '<':
                # Check what follows
                if pos + 1 >= length:
                    error("Unexpected end of string")

                next_c = s[pos+1]

                if next_c == '/':
                    # Closing tag
                    # Flush text
                    if text_buffer:
                        children.append("".join(text_buffer))
                        text_buffer = []

                    # Parse closing tag
                    advance() # skip <
                    advance() # skip /

                    end_tag_name = parse_name()
                    if end_tag_name != parent_tag:
                        error(f"Tag mismatch: expected </{parent_tag}>, got </{end_tag_name}>")

                    skip_whitespace()
                    expect('>')
                    return children

                elif next_c == '!':
                    error("Comments or CDATA not supported")
                elif next_c == '?':
                    error("Processing instructions not supported")
                else:
                    # Child element
                    # Flush text
                    if text_buffer:
                        children.append("".join(text_buffer))
                        text_buffer = []

                    child_elem = parse_element()
                    children.append(child_elem)

            elif c == '&':
                # Reference
                ref_str = parse_reference()
                text_buffer.append(ref_str)
            else:
                # Text character
                # Grammar: text characters (anything except '<' and '&')
                # Consume run of text chars
                start = pos
                while pos < length:
                    c2 = peek()
                    if c2 in ('<', '&'):
                        break
                    pos += 1
                text_buffer.append(s[start:pos])

        # End of string reached inside content
        error("Unclosed element")

    def parse_element():
        nonlocal pos
        if pos >= length or peek() != '<':
            error("Expected '<'")
        advance() # skip <

        tag_name = parse_name()

        attrs = {}

        # Parse attributes
        while pos < length:
            c = peek()
            if c in ('>', '/'):
                break
            if c in ' \t\n\r':
                # Consume whitespace
                while pos < length and peek() in ' \t\n\r':
                    pos += 1
                # Check if we hit end or attribute name
                c = peek()
                if c in ('>', '/'):
                    break
                if not (is_name_start(c)):
                     error("Expected attribute name or end of tag")

                # Parse Attribute Name
                attr_name = parse_name()

                # Expect =
                skip_whitespace()
                if not match('='):
                    error("Expected '=' in attribute")

                skip_whitespace()

                # Parse Value
                attr_value = parse_value()

                if attr_name in attrs:
                    error(f"Duplicate attribute: {attr_name}")

                attrs[attr_name] = attr_value
            else:
                # Not whitespace, not > or /
                # If it's a name char, it means missing whitespace
                if c and is_name_start(c):
                    error("Attribute not separated by whitespace")
                else:
                    error("Unexpected character in tag")

        # After loop, check for closing
        skip_whitespace()

        if match('/>'):
            return (tag_name, attrs, [])
        elif match('>'):
            children = parse_content(tag_name)
            return (tag_name, attrs, children)
        else:
            error("Expected '>' or '/>'")

    # Main execution
    skip_whitespace()
    if pos >= length:
        error("Empty input")

    root = parse_element()

    skip_whitespace()
    if pos < length:
        error("Text outside root element")

    return root

def parse_xml(s: str):
    n = len(s)
    i = 0

    def peek():
        return s[i] if i < n else None

    def advance():
        nonlocal i
        if i >= n:
            raise ValueError("Unexpected end of input")
        ch = s[i]
        i += 1
        return ch

    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1

    def parse_name():
        nonlocal i
        if i >= n or not (s[i].isalpha() or s[i] == '_'):
            raise ValueError("Invalid name start")
        start = i
        i += 1
        while i < n and (s[i].isalnum() or s[i] in '_-.'):
            i += 1
        return s[start:i]

    def parse_reference():
        nonlocal i
        if i >= n or s[i] != '&':
            raise ValueError("Expected &")
        i += 1
        start = i
        while i < n and s[i] != ';':
            i += 1
        if i >= n:
            raise ValueError("Missing ;")
        entity = s[start:i]
        i += 1  # skip ;

        if entity == 'lt': return '<'
        if entity == 'gt': return '>'
        if entity == 'amp': return '&'
        if entity == 'quot': return '"'
        if entity == 'apos': return "'"

        if entity.startswith('#x'):
            hex_str = entity[2:]
            if not hex_str:
                raise ValueError("No hex digits")
            code = int(hex_str, 16)
        elif entity.startswith('#'):
            dec_str = entity[1:]
            if not dec_str:
                raise ValueError("No digits")
            code = int(dec_str, 10)
        else:
            raise ValueError("Unknown entity")

        if code < 1 or code > 0x10FFFF:
            raise ValueError("Invalid code point")
        if 0xD800 <= code <= 0xDFFF:
            raise ValueError("Surrogate")
        return chr(code)

    def parse_value():
        nonlocal i
        quote = s[i]
        i += 1
        parts = []
        while i < n and s[i] != quote:
            if s[i] == '&':
                parts.append(parse_reference())
            elif s[i] == '<':
                raise ValueError("Value cannot contain <")
            else:
                parts.append(s[i])
                i += 1
        if i >= n:
            raise ValueError("Unterminated attribute value")
        i += 1  # skip closing quote
        return ''.join(parts)

    def parse_attributes():
        nonlocal i
        attrs = {}
        while i < n and s[i] != '>' and s[i] != '/':
            if s[i] not in ' \t\n\r':
                raise ValueError("Attribute must be preceded by whitespace")
            skip_ws()
            if i >= n or s[i] == '>' or s[i] == '/':
                raise ValueError("Expected attribute name")
            name = parse_name()
            skip_ws()
            if i >= n or s[i] != '=':
                raise ValueError("Expected =")
            i += 1
            skip_ws()
            if i >= n or s[i] not in ('"', "'"):
                raise ValueError("Expected quote")
            val = parse_value()
            if name in attrs:
                raise ValueError("Duplicate attribute")
            attrs[name] = val
        return attrs

    def parse_content(tag):
        nonlocal i
        children = []
        current_text = []

        def flush_text():
            if current_text:
                text = ''.join(current_text)
                if text:
                    children.append(text)
                current_text.clear()

        while i < n:
            if s[i] == '<':
                flush_text()
                if i + 1 < n and s[i+1] == '/':
                    i += 2
                    end_name = parse_name()
                    skip_ws()
                    if i >= n or s[i] != '>':
                        raise ValueError("Expected >")
                    i += 1
                    if end_name != tag:
                        raise ValueError("Mismatched tags")
                    return children
                else:
                    child = parse_element()
                    children.append(child)
            elif s[i] == '&':
                current_text.append(parse_reference())
            else:
                current_text.append(s[i])
                i += 1
        raise ValueError("Unclosed element")

    def parse_element():
        nonlocal i
        if i >= n or s[i] != '<':
            raise ValueError("Expected <")
        i += 1  # skip <
        tag = parse_name()
        attrs = parse_attributes()
        skip_ws()
        if i < n and s[i] == '/':
            i += 1  # skip /
            if i >= n or s[i] != '>':
                raise ValueError("Expected >")
            i += 1  # skip >
            return (tag, attrs, [])
        elif i < n and s[i] == '>':
            i += 1  # skip >
            children = parse_content(tag)
            return (tag, attrs, children)
        else:
            raise ValueError("Expected /> or >")

    def parse_document():
        nonlocal i
        if not s:
            raise ValueError("Empty input")
        skip_ws()
        if i >= n:
            raise ValueError("No element found")
        root = parse_element()
        skip_ws()
        if i < n:
            raise ValueError("Text outside root")
        return root

    return parse_document()

def parse_xml(s: str):
    """
    Parses a small XML subset and returns the root element as a tuple (tag, attrs, children).
    """
    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def peek(self):
            if self.pos < self.n:
                return self.s[self.pos]
            return None

        def advance(self, count=1):
            self.pos += count

        def match(self, expected):
            if self.s.startswith(expected, self.pos):
                self.advance(len(expected))
                return True
            return False

        def expect(self, expected):
            if not self.match(expected):
                raise ValueError(f"Expected '{expected}' at pos {self.pos}")

        def skip_ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

        def parse_name(self):
            if self.pos >= self.n:
                raise ValueError("Unexpected end of input in name")
            char = self.s[self.pos]
            if not (char.isalpha() or char == '_'):
                raise ValueError(f"Invalid start of name at pos {self.pos}: '{char}'")

            start = self.pos
            self.advance()
            while self.pos < self.n:
                char = self.s[self.pos]
                if not (char.isalnum() or char in '_-.'):
                    break
                self.advance()
            return self.s[start:self.pos]

        def parse_attributes(self):
            attrs = {}
            while self.pos < self.n and self.s[self.pos] not in '/>':
                # Attributes must be preceded by whitespace
                if self.s[self.pos] not in ' \t\n\r':
                    raise ValueError(f"Expected whitespace or closing tag at pos {self.pos}")

                self.skip_ws()

                # Parse attribute name
                attr_name = self.parse_name()

                # Optional whitespace
                self.skip_ws()

                # Expect '='
                self.expect('=')

                # Optional whitespace
                self.skip_ws()

                # Parse value
                value = self.parse_value()

                if attr_name in attrs:
                    raise ValueError(f"Duplicate attribute '{attr_name}'")
                attrs[attr_name] = value

            return attrs

        def parse_value(self):
            if self.pos >= self.n:
                raise ValueError("Unexpected end of input in value")
            quote = self.s[self.pos]
            if quote not in ('"', "'"):
                raise ValueError(f"Expected quote at pos {self.pos}")

            self.advance() # consume quote
            start = self.pos
            chars = []
            while self.pos < self.n:
                char = self.s[self.pos]
                if char == quote:
                    break
                if char == '<':
                    raise ValueError("Attribute value cannot contain '<'")
                if char == '&':
                    text_part = self.s[start:self.pos]
                    chars.append(text_part)
                    ref_val = self.parse_reference()
                    chars.append(ref_val)
                    start = self.pos
                else:
                    self.advance()

            if self.pos >= self.n:
                raise ValueError("Unterminated attribute value")

            # Consume closing quote
            self.advance()

            return "".join(chars)

        def parse_reference(self):
            if not self.s.startswith('&', self.pos):
                raise ValueError("Expected '&' for reference")
            self.advance() # consume '&'

            if self.pos >= self.n:
                raise ValueError("Reference ends with &")

            char = self.s[self.pos]
            if char == ';':
                raise ValueError("Empty reference")

            if char == '#':
                self.advance() # consume '#'
                if self.pos >= self.n:
                    raise ValueError("Incomplete reference")
                char = self.s[self.pos]
                if char == 'x':
                    self.advance() # consume 'x'
                    start = self.pos
                    while self.pos < self.n and self.s[self.pos] in '0123456789abcdefABCDEF':
                        self.advance()
                    if start == self.pos:
                        raise ValueError("No hex digits in reference")
                    hex_str = self.s[start:self.pos]
                    if self.pos >= self.n or self.s[self.pos] != ';':
                        raise ValueError("Missing ';' in reference")
                    self.advance() # consume ';'
                    code_point = int(hex_str, 16)
                elif char == 'X':
                    raise ValueError("Hex reference must use lowercase 'x'")
                else:
                    start = self.pos
                    while self.pos < self.n and self.s[self.pos] in '0123456789':
                        self.advance()
                    if start == self.pos:
                        raise ValueError("No digits in reference")
                    dec_str = self.s[start:self.pos]
                    if self.pos >= self.n or self.s[self.pos] != ';':
                        raise ValueError("Missing ';' in reference")
                    self.advance() # consume ';'
                    code_point = int(dec_str)
            else:
                start = self.pos
                while self.pos < self.n and self.s[self.pos] not in ';':
                    self.advance()
                if self.pos >= self.n:
                    raise ValueError("Missing ';' in reference")
                name = self.s[start:self.pos]
                self.advance() # consume ';'

                if name == 'lt': return '<'
                if name == 'gt': return '>'
                if name == 'amp': return '&'
                if name == 'quot': return '"'
                if name == 'apos': return "'"
                raise ValueError(f"Unknown entity '{name}'")

            # Validate code point
            if code_point < 1 or code_point > 0x10FFFF:
                raise ValueError("Code point out of range")
            if 0xD800 <= code_point <= 0xDFFF:
                raise ValueError("Surrogate code point")

            return chr(code_point)

        def parse_element(self):
            if not self.s.startswith('<', self.pos):
                raise ValueError("Expected '<' for element")
            self.advance() # consume '<'

            tag = self.parse_name()

            attrs = self.parse_attributes()

            # Check for closing
            self.skip_ws()

            if self.match('/>'):
                return (tag, attrs, [])

            if self.match('>'):
                # Parse content
                children = self.parse_content(tag)
                return (tag, attrs, children)

            raise ValueError("Expected '>' or '/>'")

        def parse_content(self, parent_tag):
            children = []
            text_buffer = []

            while self.pos < self.n:
                if self.s.startswith('</', self.pos):
                    # Check if it closes the current element
                    if self.s.startswith('</' + parent_tag, self.pos):
                        # Consume '</'
                        self.advance(2)
                        # Expect Name
                        end_tag = self.parse_name()
                        if end_tag != parent_tag:
                            raise ValueError(f"Tag mismatch: expected </{parent_tag}, got </{end_tag}")
                        # Optional whitespace
                        self.skip_ws()
                        # Expect '>'
                        if not self.match('>'):
                            raise ValueError("Expected '>' to close tag")
                        break
                    else:
                        raise ValueError(f"Unexpected closing tag '</{self.s[self.pos+2:self.pos+2+10]}...'")

                elif self.s.startswith('<', self.pos):
                    # It's a child element
                    # Flush text buffer
                    if text_buffer:
                        text_str = "".join(text_buffer)
                        if text_str:
                            children.append(text_str)
                        text_buffer = []

                    child_tag, child_attrs, child_children = self.parse_element()
                    children.append((child_tag, child_attrs, child_children))

                elif self.s.startswith('&', self.pos):
                    # Reference
                    ref_val = self.parse_reference()
                    text_buffer.append(ref_val)

                else:
                    # Text character
                    start = self.pos
                    while self.pos < self.n:
                        char = self.s[self.pos]
                        if char == '<' or char == '&':
                            break
                        self.advance()

                    text_part = self.s[start:self.pos]
                    if text_part:
                        text_buffer.append(text_part)

            # End of content
            if text_buffer:
                text_str = "".join(text_buffer)
                if text_str:
                    children.append(text_str)

            return children

    # Document: optional whitespace, exactly one element, optional whitespace, end.
    parser = Parser(s)
    parser.skip_ws()
    if parser.pos >= parser.n:
        raise ValueError("Empty input")

    tag, attrs, children = parser.parse_element()

    parser.skip_ws()
    if parser.pos != parser.n:
        raise ValueError("Unexpected characters after root element")

    return (tag, attrs, children)

class _Node:
    __slots__ = 'key', 'prev', 'next'
    def __init__(self, key):
        self.key = key
        self.prev = None
        self.next = None

class _DLL:
    __slots__ = 'head', 'tail'
    def __init__(self):
        self.head = _Node(None)
        self.tail = _Node(None)
        self.head.next = self.tail
        self.tail.prev = self.head

    def add_tail(self, key):
        node = _Node(key)
        p = self.tail.prev
        p.next = node
        node.prev = p
        node.next = self.tail
        self.tail.prev = node
        return node

    def remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def pop_head(self):
        node = self.head.next
        self.remove(node)
        return node.key

def lfu_run(capacity: int, ops: list[tuple]) -> list:
    if capacity <= 0:
        return [None for op in ops if op[0] == 'get']

    key_to_val = {}
    key_to_freq = {}
    key_to_node = {}
    freq_to_dll = {}
    min_freq = 1
    res = []

    for op in ops:
        if op[0] == 'get':
            key = op[1]
            if key in key_to_val:
                f = key_to_freq[key]
                node = key_to_node[key]
                old_dll = freq_to_dll[f]
                node.prev.next = node.next
                node.next.prev = node.prev
                if old_dll.head.next is old_dll.tail:
                    if f == min_freq:
                        min_freq += 1
                key_to_freq[key] = f + 1
                new_dll = freq_to_dll.get(f + 1)
                if new_dll is None:
                    new_dll = _DLL()
                    freq_to_dll[f + 1] = new_dll
                key_to_node[key] = new_dll.add_tail(key)
                res.append(key_to_val[key])
            else:
                res.append(None)
        else:
            key, value = op[1], op[2]
            if key in key_to_val:
                key_to_val[key] = value
                f = key_to_freq[key]
                node = key_to_node[key]
                old_dll = freq_to_dll[f]
                node.prev.next = node.next
                node.next.prev = node.prev
                if old_dll.head.next is old_dll.tail:
                    if f == min_freq:
                        min_freq += 1
                key_to_freq[key] = f + 1
                new_dll = freq_to_dll.get(f + 1)
                if new_dll is None:
                    new_dll = _DLL()
                    freq_to_dll[f + 1] = new_dll
                key_to_node[key] = new_dll.add_tail(key)
            else:
                if len(key_to_val) >= capacity:
                    evict_key = freq_to_dll[min_freq].pop_head()
                    del key_to_val[evict_key]
                    del key_to_freq[evict_key]
                    del key_to_node[evict_key]
                key_to_val[key] = value
                key_to_freq[key] = 1
                new_dll = freq_to_dll.get(1)
                if new_dll is None:
                    new_dll = _DLL()
                    freq_to_dll[1] = new_dll
                key_to_node[key] = new_dll.add_tail(key)
                min_freq = 1

    return res

def pal_partition(s: str) -> list[str]:
    n = len(s)
    if n == 0:
        return []

    # Precompute palindrome table
    # is_pal[i][j] is True if s[i:j+1] is a palindrome
    is_pal = [[False] * n for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                is_pal[i][j] = True
            elif length == 2:
                is_pal[i][j] = (s[i] == s[j])
            else:
                is_pal[i][j] = (s[i] == s[j] and is_pal[i+1][j-1])

    # Compute minimum number of pieces for each suffix
    # min_pieces[i] stores the min pieces for s[i:]
    min_pieces = [float('inf')] * (n + 1)
    min_pieces[n] = 0

    for i in range(n - 1, -1, -1):
        # We want to minimize 1 + min_pieces[j+1]
        # Iterate j from i to n-1
        # Optimization: We only care about j where is_pal[i][j] is True
        # But since n is small (1200), O(n^2) loop is acceptable.
        best = float('inf')
        for j in range(i, n):
            if is_pal[i][j]:
                if min_pieces[j+1] + 1 < best:
                    best = min_pieces[j+1] + 1
        min_pieces[i] = best

    # Reconstruct the partition greedily
    res = []
    curr = 0
    while curr < n:
        # Find the longest palindrome starting at curr that leads to an optimal solution
        # We need is_pal[curr][end] == True and 1 + min_pieces[end+1] == min_pieces[curr]
        # We want to maximize end, so iterate backwards from n-1
        found = False
        for end in range(n - 1, curr - 1, -1):
            if is_pal[curr][end]:
                if min_pieces[end+1] + 1 == min_pieces[curr]:
                    res.append(s[curr : end+1])
                    curr = end + 1
                    found = True
                    break
        if not found:
            # Should not happen if logic is correct
            break

    return res

import sys

def tree_max_path(n: int, weights: list[int], edges: list[tuple[int, int]]) -> tuple[int, int]:
    if n == 1:
        return (weights[0], 1)

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Iterative BFS to determine parent and processing order
    parent = [-1] * n
    order = []
    stack = [0]
    visited = [False] * n
    visited[0] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # Reverse order gives bottom-up processing (leaves to root)
    # Separate children from parent
    children = [[] for _ in range(n)]
    for i in range(1, n):
        u = order[i]
        p = parent[u]
        children[p].append(u)

    # Arrays for downward max path and count
    down = [0] * n
    cnt_down = [0] * n

    # Initialize with leaf values conceptually, but we process bottom-up
    for u in reversed(order):
        w = weights[u]
        down[u] = w
        cnt_down[u] = 1

        best_child_w = -1
        for v in children[u]:
            dv = down[v]
            if dv > 0:
                if w + dv > down[u]:
                    down[u] = w + dv
                    cnt_down[u] = cnt_down[v]
                elif w + dv == down[u]:
                    cnt_down[u] += cnt_down[v]
            elif dv == 0:
                if w == down[u]:
                    cnt_down[u] += cnt_down[v]

    # Now compute global max path and count
    # Each path has a unique highest node (LCA of its endpoints in rooted tree)
    global_best = -float('inf')
    global_cnt = 0

    for u in range(n):
        w = weights[u]
        # Collect (down[v], cnt_down[v]) for children with down[v] >= 0
        vals = []
        for v in children[u]:
            dv = down[v]
            if dv >= 0:
                vals.append((dv, cnt_down[v]))

        if not vals:
            cur_best = w
            cur_cnt = 1
        else:
            # Sort by weight descending
            vals.sort(key=lambda x: x[0], reverse=True)

            w1, c1 = vals[0]
            if len(vals) == 1:
                cur_best = w + w1
                cur_cnt = c1
                if w1 == 0:
                    cur_cnt += 1
            else:
                w2, c2 = vals[1]
                if w1 + w2 > w1: # w2 > 0
                    cur_best = w + w1 + w2
                    if w1 == w2:
                        cur_cnt = c1 * (c1 - 1) // 2
                    else:
                        cur_cnt = c1 * c2
                else:
                    # w2 == 0
                    cur_best = w + w1
                    if w1 == 0:
                        # All weights are 0
                        cur_cnt = 1 + c1 + c1 * (c1 - 1) // 2
                    else:
                        cur_cnt = c1 * (1 + c2)

        if cur_best > global_best:
            global_best = cur_best
            global_cnt = cur_cnt
        elif cur_best == global_best:
            global_cnt += cur_cnt

    return (global_best, global_cnt)

import heapq

def earliest_order(n: int, edges: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    out_degree = [0] * n
    adj = [[] for _ in range(n)]

    for u, v in edges:
        out_degree[u] += 1
        adj[v].append(u)

    heap = []
    for i in range(n):
        if out_degree[i] == 0:
            heapq.heappush(heap, -i)

    order = [0] * n
    for i in range(n - 1, -1, -1):
        if not heap:
            return []  # Cycle detected
        v = -heapq.heappop(heap)
        order[i] = v
        for u in adj[v]:
            out_degree[u] -= 1
            if out_degree[u] == 0:
                heapq.heappush(heap, -u)

    return order

def edit_script(a: str, b: str) -> list[str]:
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n, -1, -1):
        dp[i][m] = n - i
    for j in range(m, -1, -1):
        dp[n][j] = m - j

    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            cost_sub = 1 + dp[i+1][j+1]
            cost_match = dp[i+1][j+1] if a[i] == b[j] else cost_sub
            cost_del = 1 + dp[i+1][j]
            cost_ins = 1 + dp[i][j+1]
            dp[i][j] = min(cost_match, cost_del, cost_ins)

    script = []
    i, j = 0, 0
    while i < n or j < m:
        if i < n and j < m and a[i] == b[j] and dp[i][j] == dp[i+1][j+1]:
            script.append(f"={a[i]}")
            i += 1
            j += 1
        elif i < n and j < m and a[i] != b[j] and dp[i][j] == 1 + dp[i+1][j+1]:
            script.append(f"~{a[i]}{b[j]}")
            i += 1
            j += 1
        elif i < n and dp[i][j] == 1 + dp[i+1][j]:
            script.append(f"-{a[i]}")
            i += 1
        elif j < m and dp[i][j] == 1 + dp[i][j+1]:
            script.append(f"+{b[j]}")
            j += 1
        else:
            break

    return script

import math
from typing import List, Tuple, Optional

def crt_solve(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    for _, m in congruences:
        if m < 1:
            raise ValueError("Modulus must be an integer >= 1")

    x, m = congruences[0]
    x %= m

    for i in range(1, len(congruences)):
        a_prime, m_prime = congruences[i]
        a_prime %= m_prime

        diff = a_prime - x
        g = math.gcd(m, m_prime)

        if diff % g != 0:
            return None

        m_red = m // g
        m_prime_red = m_prime // g
        diff_red = diff // g

        if m_prime_red == 1:
            k = 0
        else:
            inv = pow(m_red, -1, m_prime_red)
            k = (diff_red * inv) % m_prime_red

        x = x + k * m
        m = m * m_prime_red
        x %= m

    return (x, m)

import sys

# Increase recursion limit just in case, though not needed here
sys.setrecursionlimit(2000)

def perfect_power(n: int) -> tuple[int, int]:
    if abs(n) < 2:
        raise ValueError("abs(n) must be >= 2")

    m = abs(n)
    max_e = m.bit_length() - 1

    # We search for the largest e such that m = b^e
    # We iterate e from max_e down to 2.
    # For each e, we compute the integer e-th root of m.
    # If b^e == m, we found the answer.

    for e in range(max_e, 1, -1):
        # Compute integer e-th root of m using binary search
        # Initial guess: 2^(bit_length // e)
        low = 1 << (m.bit_length() // e)
        high = low << 1  # Strict upper bound since m < 2^bit_length

        # Binary search for floor root
        while low < high:
            mid = (low + high + 1) // 2
            if mid ** e <= m:
                low = mid
            else:
                high = mid - 1

        b = low
        if b ** e == m:
            # Found a perfect power
            if n < 0:
                # For negative n, exponent must be odd.
                # Reduce e to the largest odd divisor and adjust base.
                while e % 2 == 0:
                    e //= 2
                    b = b * b
                b = -b
            return (b, e)

    return (n, 1)

import math

def perfect_power(n: int) -> tuple[int, int]:
    if abs(n) < 2:
        raise ValueError("abs(n) must be >= 2")

    sign = -1 if n < 0 else 1
    abs_n = abs(n)

    def iroot(n: int, e: int) -> tuple[int, bool]:
        if e == 1:
            return n, True
        if e == 2:
            r = math.isqrt(n)
            return r, r * r == n

        # Upper bound: 2^(bit_length/e + 1) > n^(1/e)
        x = 1 << (n.bit_length() // e + 1)

        while True:
            x_pow = x ** (e - 1)
            x_new = ((e - 1) * x + n // x_pow) // e
            if x_new >= x:
                break
            x = x_new

        return x, x ** e == n

    max_e = abs_n.bit_length()
    start_e = max_e
    step = 1

    # For negative numbers, only odd exponents are possible
    if n < 0:
        if start_e % 2 == 0:
            start_e -= 1
        step = 2

    for e in range(start_e, 0, -step):
        root, exact = iroot(abs_n, e)
        if exact:
            return (sign * root, e)

    return (n, 1)

def convex_hull(points: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not points:
        return []

    # Remove duplicates and sort by x, then y
    pts = sorted(set(points))

    # Handle single unique point
    if len(pts) == 1:
        return [pts[0]]

    # Cross product of vectors OA and OB
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower hull
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate lower and upper hulls, removing duplicate endpoints
    hull = lower[:-1] + upper[:-1]

    # Rotate to start at the point with smallest y, ties broken by smallest x
    start_idx = min(range(len(hull)), key=lambda i: (hull[i][1], hull[i][0]))
    return hull[start_idx:] + hull[:start_idx]

from fractions import Fraction

def segment_intersection(s1, s2):
    # Convert all coordinates to exact Fractions
    p1 = (Fraction(s1[0][0]), Fraction(s1[0][1]))
    p2 = (Fraction(s1[1][0]), Fraction(s1[1][1]))
    p3 = (Fraction(s2[0][0]), Fraction(s2[0][1]))
    p4 = (Fraction(s2[1][0]), Fraction(s2[1][1]))

    def cross(o, a, b):
        """2D cross product of vectors OA and OB."""
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        """Check if point p lies on the closed segment ab (bounding box check)."""
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    dx1, dy1 = p2[0] - p1[0], p2[1] - p1[1]
    dx2, dy2 = p4[0] - p3[0], p4[1] - p3[1]

    denom = dx1 * dy2 - dy1 * dx2

    if denom != 0:
        # Non-parallel lines
        # Parametric intersection: p1 + t*(p2-p1) = p3 + u*(p4-p3)
        t_num = (p3[0] - p1[0]) * dy2 - (p3[1] - p1[1]) * dx2
        u_num = (p3[0] - p1[0]) * dy1 - (p3[1] - p1[1]) * dx1

        t = t_num / denom
        u = u_num / denom

        if 0 <= t <= 1 and 0 <= u <= 1:
            ix = p1[0] + t * dx1
            iy = p1[1] + t * dy1
            return (ix, iy)
        return None
    else:
        # Parallel or collinear
        # Check if they actually lie on the same infinite line
        if cross(p1, p3, p2) != 0:
            return None

        # Collinear: intersection is the overlap of the two intervals on the line.
        # Collect all original endpoints that lie on both segments.
        candidates = []
        for p in (p1, p2, p3, p4):
            if on_segment(p, p1, p2) and on_segment(p, p3, p4):
                candidates.append(p)

        # Remove duplicates while preserving order (doesn't matter, we sort later)
        unique_candidates = []
        for c in candidates:
            if c not in unique_candidates:
                unique_candidates.append(c)

        if len(unique_candidates) == 0:
            return None
        elif len(unique_candidates) == 1:
            return (unique_candidates[0][0], unique_candidates[0][1])
        else:
            # Sort lexicographically (x first, then y)
            unique_candidates.sort()
            return ((unique_candidates[0][0], unique_candidates[0][1]),
                    (unique_candidates[1][0], unique_candidates[1][1]))

from fractions import Fraction

def segment_intersection(s1, s2):
    (x1, y1), (x2, y2) = s1
    (x3, y3), (x4, y4) = s2

    def cross(O, A, B):
        return (A[0] - O[0]) * (B[1] - O[1]) - (A[1] - O[1]) * (B[0] - O[0])

    cp1 = cross((x1, y1), (x2, y2), (x3, y3))
    cp2 = cross((x1, y1), (x2, y2), (x4, y4))
    cp3 = cross((x3, y3), (x4, y4), (x1, y1))
    cp4 = cross((x3, y3), (x4, y4), (x2, y2))

    def on_segment(A, B, C):
        return min(A[0], B[0]) <= C[0] <= max(A[0], B[0]) and \
               min(A[1], B[1]) <= C[1] <= max(A[1], B[1])

    # Collinear case
    if cp1 == 0 and cp2 == 0:
        ix1 = max(min(x1, x2), min(x3, x4))
        ix2 = min(max(x1, x2), max(x3, x4))
        iy1 = max(min(y1, y2), min(y3, y4))
        iy2 = min(max(y1, y2), max(y3, y4))

        if ix1 <= ix2 and iy1 <= iy2:
            if ix1 == ix2 and iy1 == iy2:
                return Fraction(ix1), Fraction(iy1)
            else:
                A = (Fraction(ix1), Fraction(iy1))
                B = (Fraction(ix2), Fraction(iy2))
                if A > B:
                    A, B = B, A
                return A, B
        else:
            return None

    # Proper intersection
    if ((cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0)) and \
       ((cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0)):
        denom = cp1 - cp2
        ix = cp1 * x4 - cp2 * x3
        iy = cp1 * y4 - cp2 * y3
        return Fraction(ix, denom), Fraction(iy, denom)

    # Endpoint touches
    if cp1 == 0 and on_segment((x1, y1), (x2, y2), (x3, y3)):
        return Fraction(x3), Fraction(y3)
    if cp2 == 0 and on_segment((x1, y1), (x2, y2), (x4, y4)):
        return Fraction(x4), Fraction(y4)
    if cp3 == 0 and on_segment((x3, y3), (x4, y4), (x1, y1)):
        return Fraction(x1), Fraction(y1)
    if cp4 == 0 and on_segment((x3, y3), (x4, y4), (x2, y2)):
        return Fraction(x2), Fraction(y2)

    return None

def _is_leap(y: int) -> bool:
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _days_in_month(y: int, m: int) -> int:
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if m in (4, 6, 9, 11):
        return 30
    if m == 2:
        return 29 if _is_leap(y) else 28
    return 0

def _days_before_year(y: int) -> int:
    return (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400

def _date_to_daynum(y: int, m: int, d: int) -> int:
    return _days_before_year(y) + sum(_days_in_month(y, i) for i in range(1, m)) + d

def _daynum_to_date(n: int) -> tuple[int, int, int]:
    y = 1
    rem = n
    while True:
        diy = 366 if _is_leap(y) else 365
        if rem <= diy:
            break
        rem -= diy
        y += 1
    m = 1
    while True:
        dim = _days_in_month(y, m)
        if rem <= dim:
            break
        rem -= dim
        m += 1
    return y, m, rem

def _weekday(n: int) -> int:
    # 1=Monday, 7=Sunday
    return (n - 1) % 7 + 1

def _validate_date(y: int, m: int, d: int) -> None:
    if not (1 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")
    if not (1 <= d <= _days_in_month(y, m)):
        raise ValueError("Day out of range")

def _max_weeks(iy: int) -> int:
    n_jan1 = _date_to_daynum(iy, 1, 1)
    w_jan1 = _weekday(n_jan1)
    n_mon_w1 = n_jan1 - (w_jan1 - 1)
    n_dec31 = _date_to_daynum(iy, 12, 31)
    return (n_dec31 - n_mon_w1) // 7 + 1

def to_iso_week(year: int, month: int, day: int) -> tuple[int, int, int]:
    _validate_date(year, month, day)
    n = _date_to_daynum(year, month, day)
    w = _weekday(n)
    # Thursday of the current week determines the ISO year
    n_thu = n + (4 - w)
    iy, _, _ = _daynum_to_date(n_thu)

    # Monday of week 1 of the ISO year
    n_jan1_iy = _date_to_daynum(iy, 1, 1)
    w_jan1_iy = _weekday(n_jan1_iy)
    n_mon_w1 = n_jan1_iy - (w_jan1_iy - 1)

    iso_week = (n - n_mon_w1) // 7 + 1
    return iy, iso_week, w

def from_iso_week(iso_year: int, week: int, weekday: int) -> tuple[int, int, int]:
    if not (1 <= iso_year <= 9999):
        raise ValueError("ISO year out of range")
    if not (1 <= weekday <= 7):
        raise ValueError("Weekday out of range")
    if not (1 <= week <= _max_weeks(iso_year)):
        raise ValueError("Week out of range")

    n_jan1 = _date_to_daynum(iso_year, 1, 1)
    w_jan1 = _weekday(n_jan1)
    n_mon_w1 = n_jan1 - (w_jan1 - 1)
    n = n_mon_w1 + (week - 1) * 7 + (weekday - 1)

    y, m, d = _daynum_to_date(n)
    if not (1 <= y <= 9999):
        raise ValueError("Resulting calendar date out of range")
    return y, m, d

def _is_leap(y: int) -> bool:
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _date_to_ordinal(y: int, m: int, d: int) -> int:
    days = 365 * (y - 1) + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    leap = _is_leap(y)
    month_days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if leap:
        month_days[2] = 29
    for i in range(1, m):
        days += month_days[i]
    return days + d

def _ordinal_to_date(ord_val: int):
    y = 1 + (ord_val - 1) // 365
    y += (ord_val - 1) // 146097 - (ord_val - 1) // 36525 + (ord_val - 1) // 9700
    while _date_to_ordinal(y, 1, 1) > ord_val:
        y -= 1
    while _date_to_ordinal(y + 1, 1, 1) <= ord_val:
        y += 1
    leap = _is_leap(y)
    month_days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if leap:
        month_days[2] = 29
    d = ord_val - _date_to_ordinal(y, 1, 1) + 1
    m = 1
    for i in range(1, 13):
        if d <= month_days[i]:
            break
        d -= month_days[i]
        m += 1
    return y, m, d

def to_iso_week(year: int, month: int, day: int) -> tuple[int, int, int]:
    if not (1 <= year <= 9999):
        raise ValueError("year out of range")
    if not (1 <= month <= 12):
        raise ValueError("month out of range")
    leap = _is_leap(year)
    month_days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if leap:
        month_days[2] = 29
    if not (1 <= day <= month_days[month]):
        raise ValueError("day out of range")

    ord_val = _date_to_ordinal(year, month, day)
    dow = (ord_val - 1) % 7 + 1  # 1=Mon, 2=Tue, ..., 7=Sun

    # ISO year is the year of the Thursday in the same week
    thursday_ord = ord_val + (4 - dow)
    iso_year = _ordinal_to_date(thursday_ord)[0]

    # Week 1 starts on the Monday of the week containing January 4
    jan4_ord = _date_to_ordinal(iso_year, 1, 4)
    jan4_dow = (jan4_ord - 1) % 7 + 1
    week1_monday_ord = jan4_ord - (jan4_dow - 1) % 7

    iso_week = (ord_val - week1_monday_ord) // 7 + 1
    return iso_year, iso_week, dow

def from_iso_week(iso_year: int, week: int, weekday: int) -> tuple[int, int, int]:
    if not (1 <= iso_year <= 9999):
        raise ValueError("iso_year out of range")
    if not (1 <= weekday <= 7):
        raise ValueError("weekday out of range")

    jan4_ord = _date_to_ordinal(iso_year, 1, 4)
    jan4_dow = (jan4_ord - 1) % 7 + 1
    week1_monday_ord = jan4_ord - (jan4_dow - 1) % 7

    dec31_ord = _date_to_ordinal(iso_year, 12, 31)
    max_week = 53 if (dec31_ord - week1_monday_ord) >= 364 else 52
    if not (1 <= week <= max_week):
        raise ValueError("week out of range")

    target_ord = week1_monday_ord + (week - 1) * 7 + (weekday - 1)
    max_ord = _date_to_ordinal(9999, 12, 31)
    if target_ord < 1 or target_ord > max_ord:
        raise ValueError("result date out of range")

    y, m, d = _ordinal_to_date(target_ord)
    return y, m, d

from typing import Tuple

def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def _days_in_month(year: int, month: int) -> int:
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    return 29 if _is_leap(year) else 28

def _validate_calendar(year: int, month: int, day: int) -> None:
    if not (1 <= year <= 9999):
        raise ValueError("Year must be between 1 and 9999")
    if not (1 <= month <= 12):
        raise ValueError("Month must be between 1 and 12")
    if not (1 <= day <= _days_in_month(year, month)):
        raise ValueError("Day is invalid for the given month and year")

def _total_days(year: int, month: int, day: int) -> int:
    yd = 365 * (year - 1) + (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
    md = sum(_days_in_month(year, m) for m in range(1, month))
    return yd + md + day - 1

def _td_to_ymd(td: int) -> Tuple[int, int, int]:
    year = 1
    while True:
        yd = 366 if _is_leap(year) else 365
        if td < yd:
            break
        td -= yd
        year += 1
    month = 1
    while True:
        md = _days_in_month(year, month)
        if td < md:
            break
        td -= md
        month += 1
    return year, month, td + 1

def to_iso_week(year: int, month: int, day: int) -> Tuple[int, int, int]:
    _validate_calendar(year, month, day)
    td = _total_days(year, month, day)
    iso_weekday = (td % 7) + 1

    # Find the Thursday of the current week
    thursday_td = td + (4 - iso_weekday)
    iso_year, _, _ = _td_to_ymd(thursday_td)

    # Find the Monday of ISO week 1 for that ISO year
    jan4_td = _total_days(iso_year, 1, 4)
    jan4_weekday = (jan4_td % 7) + 1
    thursday_jan4_td = jan4_td + (4 - jan4_weekday)
    iso_year_start_td = thursday_jan4_td - 3

    week = 1 + (td - iso_year_start_td) // 7
    return iso_year, week, iso_weekday

def from_iso_week(iso_year: int, week: int, weekday: int) -> Tuple[int, int, int]:
    if not (1 <= iso_year <= 9999):
        raise ValueError("ISO year must be between 1 and 9999")
    if not (1 <= weekday <= 7):
        raise ValueError("Weekday must be between 1 and 7")

    # Calculate the Monday of ISO week 1
    jan4_td = _total_days(iso_year, 1, 4)
    jan4_weekday = (jan4_td % 7) + 1
    thursday_jan4_td = jan4_td + (4 - jan4_weekday)
    iso_year_start_td = thursday_jan4_td - 3

    # Determine number of weeks in this ISO year
    thursday_w53_td = iso_year_start_td + 7 * 52 + 3
    max_weeks = 53 if _td_to_ymd(thursday_w53_td)[0] == iso_year else 52

    if not (1 <= week <= max_weeks):
        raise ValueError("Week is out of range for the given ISO year")

    result_td = iso_year_start_td + (week - 1) * 7 + (weekday - 1)
    max_td = _total_days(9999, 12, 31)

    if result_td < 0 or result_td > max_td:
        raise ValueError("Resulting calendar date falls outside 0001-01-01 .. 9999-12-31")

    return _td_to_ymd(result_td)

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    DAYS_IN_MONTH = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def is_leap(y: int) -> bool:
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def dim(y: int, m: int) -> int:
        if m == 2 and is_leap(y):
            return 29
        return DAYS_IN_MONTH[m]

    def next_date(y: int, m: int, d: int):
        d += 1
        if d > dim(y, m):
            d = 1
            m += 1
            if m > 12:
                m = 1
                y += 1
        return y, m, d

    def prev_date(y: int, m: int, d: int):
        d -= 1
        if d < 1:
            m -= 1
            if m < 1:
                m = 12
                y -= 1
            d = dim(y, m)
        return y, m, d

    def date_str(y: int, m: int, d: int) -> str:
        return f"{y:04d}-{m:02d}-{d:02d}"

    def dow(y: int, m: int, d: int) -> int:
        # Sakamoto's algorithm: 0=Sun, 1=Mon, ..., 6=Sat
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        if m < 3:
            y -= 1
        return (y + y // 4 - y // 100 + y // 400 + t[m - 1] + d) % 7

    def is_valid(s: str) -> bool:
        if len(s) != 10 or s[4] != '-' or s[7] != '-':
            return False
        parts = [s[:4], s[5:7], s[8:10]]
        for p in parts:
            if not all('0' <= c <= '9' for c in p):
                return False
        return True

    def validate_and_parse(s: str):
        if not is_valid(s):
            raise ValueError(f"Invalid date format: {s}")
        y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        if m < 1 or m > 12 or d < 1 or d > dim(y, m):
            raise ValueError(f"Invalid date: {s}")
        return y, m, d

    # Validate start
    sy, sm, sd = validate_and_parse(start)

    # Validate and parse holidays into a set
    holidays_set = set()
    for h in holidays:
        hy, hm, hd = validate_and_parse(h)
        holidays_set.add(date_str(hy, hm, hd))

    def is_business_day(y: int, m: int, d: int) -> bool:
        # Check weekday (0=Sun, 6=Sat)
        if dow(y, m, d) in (0, 6):
            return False
        ds = date_str(y, m, d)
        # Direct holiday
        if ds in holidays_set:
            return False
        # Observed holiday rules
        if dow(y, m, d) == 5:  # Friday -> check Saturday
            ny, nm, nd = next_date(y, m, d)
            if date_str(ny, nm, nd) in holidays_set:
                return False
        if dow(y, m, d) == 1:  # Monday -> check Sunday
            ny, nm, nd = prev_date(y, m, d)
            if date_str(ny, nm, nd) in holidays_set:
                return False
        return True

    # Handle n == 0
    if n == 0:
        if is_business_day(sy, sm, sd):
            return start
        n = 1

    if n > 0:
        y, m, d = sy, sm, sd
        count = 0
        while count < n:
            y, m, d = next_date(y, m, d)
            if is_business_day(y, m, d):
                count += 1
        return date_str(y, m, d)
    else:
        y, m, d = sy, sm, sd
        count = 0
        while count < abs(n):
            y, m, d = prev_date(y, m, d)
            if is_business_day(y, m, d):
                count += 1
        return date_str(y, m, d)

def best_rational(num: int, den: int, max_den: int) -> tuple[int, int]:
    if den == 0 or max_den < 1:
        raise ValueError("den must be non-zero and max_den >= 1")

    # Keep original values for exact distance comparison
    num_orig, den_orig = num, den

    # Normalize sign so den > 0
    if den < 0:
        num, den = -num, -den
    sign = -1 if num < 0 else 1
    num = abs(num)

    if num == 0:
        return (0, 1)

    # Compute continued fraction coefficients for num/den
    a0, r = divmod(num, den)
    coeffs = [a0]
    while r:
        num, den = den, r
        a, r = divmod(num, den)
        coeffs.append(a)

    # Generate convergents p_k/q_k
    # Recurrence: p_k = a_k*p_{k-1} + p_{k-2}, q_k = a_k*q_{k-1} + q_{k-2}
    p_prev2, p_prev1 = 0, 1
    q_prev2, q_prev1 = 1, 0

    p1, q1 = p_prev1, q_prev1  # Candidate 1: last valid convergent
    p2, q2 = None, None        # Candidate 2: semiconvergent at max_den limit

    for a in coeffs:
        p_curr = a * p_prev1 + p_prev2
        q_curr = a * q_prev1 + q_prev2

        if q_curr > max_den:
            # The best approximation with q <= max_den lies between 
            # p_prev1/q_prev1 and p_curr/q_curr.
            # It is given by t * p_prev1 + p_prev2 / t * q_prev1 + q_prev2
            # where t = floor((max_den - q_prev2) / q_prev1)
            t = (max_den - q_prev2) // q_prev1
            # Since q_prev1 <= max_den and q_prev1 > q_prev2, t >= 1 always.
            p2, q2 = t * p_prev1 + p_prev2, t * q_prev1 + q_prev2
            break
        p_prev2, p_prev1 = p_prev1, p_curr
        q_prev2, q_prev1 = q_prev1, q_curr
    else:
        # All convergents fit within max_den; the last one is best.
        p1, q1 = p_prev1, q_prev1

    # Compare candidates based on distance to num_orig/den_orig
    # Distance = |num_orig/q - den_orig*p| / (den_orig * q)
    # We compare |num_orig*q1 - den_orig*p1| * q2 vs |num_orig*q2 - den_orig*p2| * q1
    if p2 is not None:
        d1 = abs(num_orig * q1 - den_orig * p1)
        d2 = abs(num_orig * q2 - den_orig * p2)

        val1 = d1 * q2
        val2 = d2 * q1

        if val1 < val2:
            p_best, q_best = p1, q1
        elif val2 < val1:
            p_best, q_best = p2, q2
        else:
            # Tie in distance: prefer smaller q
            if q1 < q2:
                p_best, q_best = p1, q1
            elif q2 < q1:
                p_best, q_best = p2, q2
            else:
                # Same q: prefer smaller value p/q => smaller p (q > 0)
                if p1 < p2:
                    p_best, q_best = p1, q1
                else:
                    p_best, q_best = p2, q2
    else:
        p_best, q_best = p1, q1

    p_best *= sign
    return (p_best, q_best)

import math

def best_rational(num: int, den: int, max_den: int) -> tuple[int, int]:
    if den == 0 or max_den < 1:
        raise ValueError
    if num == 0:
        return (0, 1)

    sign = 1
    if num < 0:
        num = -num
        sign = -sign
    if den < 0:
        den = -den
        sign = -sign

    g = math.gcd(num, den)
    num //= g
    den //= g

    if den <= max_den:
        return (sign * num, den)

    # Continued fraction state
    # p_prev2/q_prev2 corresponds to p_{k-2}/q_{k-2}
    # p_prev1/q_prev1 corresponds to p_{k-1}/q_{k-1}
    p_prev2, q_prev2 = 0, 1
    p_prev1, q_prev1 = 1, 0

    best_p, best_q = 0, 1
    best_diff = abs(num * 1 - den * 0)  # |num*best_q - den*best_p|

    a, b = num, den
    while b != 0:
        a0 = a // b
        r = a % b

        # Next convergent p_k/q_k
        p_k = a0 * p_prev1 + p_prev2
        q_k = a0 * q_prev1 + q_prev2

        if q_k > max_den:
            # Best approximation lies among semi-convergents between
            # p_{k-1}/q_{k-1} and p_k/q_k: (p_{k-2} + t*p_{k-1}) / (q_{k-2} + t*q_{k-1})
            t = (max_den - q_prev2) // q_prev1
            if t < 1:
                t = 1
            p_cand = p_prev2 + t * p_prev1
            q_cand = q_prev2 + t * q_prev1
            diff_cand = abs(num * q_cand - den * p_cand)

            # Compare diff_cand/q_cand vs best_diff/best_q
            lhs = diff_cand * best_q
            rhs = best_diff * q_cand
            if lhs < rhs or (lhs == rhs and (q_cand < best_q or (q_cand == best_q and p_cand * best_q < best_p * q_cand))):
                best_p, best_q, best_diff = p_cand, q_cand, diff_cand
            return (sign * best_p, best_q)

        # Check this convergent
        diff = abs(num * q_k - den * p_k)
        if diff * best_q < best_diff * q_k:
            best_p, best_q, best_diff = p_k, q_k, diff
        elif diff * best_q == best_diff * q_k:
            if q_k < best_q or (q_k == best_q and p_k * best_q < best_p * q_k):
                best_p, best_q, best_diff = p_k, q_k, diff

        # Shift for next iteration
        p_prev2, q_prev2 = p_prev1, q_prev1
        p_prev1, q_prev1 = p_k, q_k
        a, b = b, r

    return (sign * best_p, best_q)
